const dateLabelY = (key) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(key || ''))) return String(key || '');
  const [y, m, d] = String(key).split('-').map(Number);
  return `${y}/${m}/${d}`;
};

// ---- 日本の祝日判定 ----
const _nthMonday = (year, month, n) => {
  let count = 0;
  for (let d = 1; d <= 31; d++) {
    const dt = new Date(year, month - 1, d);
    if (dt.getMonth() !== month - 1) break;
    if (dt.getDay() === 1) {
      count++;
      if (count === n) return d;
    }
  }
  return null;
};
const _holidayCache = {};
function getJapaneseHolidays(year) {
  if (_holidayCache[year]) return _holidayCache[year];
  const base = {};
  const add = (m, d, name) => { if (d) base[`${year}-${pad(m)}-${pad(d)}`] = name; };

  add(1, 1, '元日');
  add(1, _nthMonday(year, 1, 2), '成人の日');
  add(2, 11, '建国記念の日');
  if (year >= 2020) add(2, 23, '天皇誕生日');
  const shunbun = Math.floor(20.8431 + 0.242194 * (year - 1980)) - Math.floor((year - 1980) / 4);
  add(3, shunbun, '春分の日');
  add(4, 29, '昭和の日');
  add(5, 3, '憲法記念日');
  add(5, 4, 'みどりの日');
  add(5, 5, 'こどもの日');
  add(7, _nthMonday(year, 7, 3), '海の日');
  add(8, 11, '山の日');
  add(9, _nthMonday(year, 9, 3), '敬老の日');
  const shubun = Math.floor(23.2488 + 0.242194 * (year - 1980)) - Math.floor((year - 1980) / 4);
  add(9, shubun, '秋分の日');
  add(10, _nthMonday(year, 10, 2), 'スポーツの日');
  add(11, 3, '文化の日');
  add(11, 23, '勤労感謝の日');

  const result = { ...base };

  // 国民の休日：前後を祝日に挟まれた平日（日曜以外）
  Object.keys(base).forEach((dateStr) => {
    const d = new Date(dateStr + 'T00:00:00');
    const next = new Date(d);
    next.setDate(next.getDate() + 2);
    const nextKey = todayKey(next);
    const between = new Date(d);
    between.setDate(between.getDate() + 1);
    const betweenKey = todayKey(between);
    if (base[nextKey] && !base[betweenKey] && between.getDay() !== 0) {
      result[betweenKey] = '国民の休日';
    }
  });

  // 振替休日：日曜に当たる祝日の翌日以降、最初の非祝日
  Object.entries(base).forEach(([dateStr, name]) => {
    const d = new Date(dateStr + 'T00:00:00');
    if (d.getDay() === 0) {
      let next = new Date(d);
      do {
        next.setDate(next.getDate() + 1);
      } while (result[todayKey(next)]);
      result[todayKey(next)] = '振替休日';
    }
  });

  _holidayCache[year] = result;
  return result;
}
const getHolidayName = (dateStr) => {
  const year = Number(dateStr.slice(0, 4));
  return getJapaneseHolidays(year)[dateStr] || null;
};

// 一覧用：YYYY-MM-DD → M/D(曜) と、表示に使う色
//   textClass  … 日付の文字色。土＝水色、日祝＝ピンク。行の背景は塗らない
//   badgeClass … 「土」「日」「祝」の小さなバッジ用（背景つき）。カレンダー表示で使う
const formatAdminDate = (key) => {
  const d = new Date(key + 'T00:00:00');
  const days = ['日', '月', '火', '水', '木', '金', '土'];
  const wd = d.getDay();
  const holidayName = getHolidayName(key);
  const label = `${d.getMonth() + 1}/${d.getDate()}(${days[wd]}${holidayName ? '・祝' : ''})`;
  const badgeClass = (wd === 0 || holidayName) ? 'bg-rose-100 text-rose-700' : wd === 6 ? 'bg-sky-100 text-sky-700' : '';
  const textClass = (wd === 0 || holidayName) ? 'text-rose-600' : wd === 6 ? 'text-sky-600' : 'text-slate-700';
  return { label, badgeClass, textClass, holidayName };
};

// ---- Leave (休暇) ----
// ---- 通知の件名から、確認すべき画面を判定する ----
// topTab は画面上部のタブ、adminTab は「勤怠」タブ内のサブ画面を指す
// 「承認」「却下」「差し戻し」を含む件名は、管理者が処理した結果をスタッフへ知らせるものなので、
// 改めて開く必要がない。リンクにせず、処理済みとして薄く表示する。
const NOTIFICATION_DONE_KEYWORDS = ['承認', '却下', '差し戻し'];
function isNotificationDone(subject = '') {
  return NOTIFICATION_DONE_KEYWORDS.some((k) => subject.includes(k));
}

function resolveNotificationTarget(subject = '') {
  if (isNotificationDone(subject)) return null;
  const has = (...keys) => keys.some((k) => subject.includes(k));
  if (has('出勤確認', '退勤確認')) return { topTab: 'attendance', adminTab: 'attendance', label: '勤怠一覧' };
  if (has('勤怠修正')) return { topTab: 'attendance', adminTab: 'requests', label: '勤怠修正申請' };
  if (has('休暇申請')) return { topTab: 'attendance', adminTab: 'leave', label: '休暇申請' };
  if (has('個人情報変更', '年末調整')) return { topTab: 'hr', adminTab: null, label: '人材' };
  if (has('交通費精算', '給与明細')) return { topTab: 'payroll', adminTab: null, label: '給与' };
  return null;
}

