const EDIT_HISTORY_MAX = 200;

function makeHistoryEntry(actor, action, changes = []) {
  return {
    at: new Date().toISOString(),
    by_id: actor?.id || null,
    by_name: actor?.name || '',
    action,
    changes,
  };
}

function appendHistory(existingHistory, entry) {
  return [entry, ...(Array.isArray(existingHistory) ? existingHistory : [])].slice(0, EDIT_HISTORY_MAX);
}

// 支給項目・控除項目の差分を、読める文に直す
function diffAmountItems(before, after, kindLabel) {
  const toMap = (list) => {
    const m = new Map();
    (Array.isArray(list) ? list : []).forEach((it) => {
      const label = String(it?.label || '').trim();
      if (!label) return;
      m.set(label, (m.get(label) || 0) + (Number(it?.amount) || 0));
    });
    return m;
  };
  const a = toMap(before);
  const b = toMap(after);
  const lines = [];
  b.forEach((amount, label) => {
    if (!a.has(label)) lines.push(`${kindLabel}を追加：${label} ${formatYen(amount)}`);
    else if (a.get(label) !== amount) lines.push(`${kindLabel}：${label} ${formatYen(a.get(label))} → ${formatYen(amount)}`);
  });
  a.forEach((amount, label) => {
    if (!b.has(label)) lines.push(`${kindLabel}を削除：${label} ${formatYen(amount)}`);
  });
  return lines;
}

// ---- 法定帳簿（賃金台帳・出勤簿）用の計算 ----
// 賃金台帳には深夜労働時間数の記載が必要（労働基準法施行規則第54条）。
// 深夜は22時〜翌5時。日をまたぐ勤務の運用は無いため、1日の中での重なりだけを見る。
// 休憩（固定60分）がどの時刻に取られたかは記録していないため、
// 休憩が深夜帯にかかる場合は差し引けない。日中に取る運用のため影響しない想定。
const NIGHT_FROM_MIN = 22 * 60;   // 22:00
const NIGHT_UNTIL_MIN = 5 * 60;   // 05:00

function overlapMinutes(startMin, endMin, fromMin, untilMin) {
  return Math.max(0, Math.min(endMin, untilMin) - Math.max(startMin, fromMin));
}

function computeNightMinutes(record) {
  if (!record || !record.clockIn || !record.clockOut) return 0;
  const inMin = toMinutes(hhmm(new Date(record.clockIn)));
  const outMin = toMinutes(hhmm(new Date(record.clockOut)));
  if (outMin <= inMin) return 0;
  // 早朝（0:00〜5:00）と夜（22:00〜24:00）の2つの帯
  return overlapMinutes(inMin, outMin, 0, NIGHT_UNTIL_MIN)
    + overlapMinutes(inMin, outMin, NIGHT_FROM_MIN, 24 * 60);
}

// ---- Geolocation ----
function useGeolocation() {
  const [status, setStatus] = useState('idle');
  const capture = useCallback(() => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        setStatus('error');
        resolve(null);
        return;
      }
      setStatus('loading');
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setStatus('granted');
          resolve({ lat: Number(pos.coords.latitude.toFixed(5)), lng: Number(pos.coords.longitude.toFixed(5)) });
        },
        () => {
          setStatus('denied');
          resolve(null);
        },
        { timeout: 8000 }
      );
    });
  }, []);
  return { status, capture };
}

// ---- Toast ----
function useToast() {
  const [toast, setToast] = useState(null);
  const timerRef = useRef(null);
  const show = (msg, tone = 'default') => {
    setToast({ msg, tone });
    clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setToast(null), 3200);
  };
  return { toast, show };
}

function ToastView({ toast }) {
  if (!toast) return null;
  const toneStyles = {
    default: 'bg-slate-800 text-white',
    success: 'bg-emerald-600 text-white',
    warn: 'bg-amber-600 text-white',
  };
  return (
    <div className={`fixed bottom-5 left-1/2 -translate-x-1/2 px-4 py-2.5 rounded-lg shadow-lg text-sm font-medium z-50 ${toneStyles[toast.tone] || toneStyles.default}`}>
      {toast.msg}
    </div>
  );
}

