// ---- 確定シフトの月表（スタッフ）----
// スプレッドシートから取り込んだ、決まったシフトを1か月分並べる
function MyShiftCalendar({ employeeId, assignments = [], shiftRequests = [], isDesktop }) {
  const now = new Date();
  const [month, setMonth] = useState(`${now.getFullYear()}-${pad(now.getMonth() + 1)}`);
  const days = useMemo(() => shiftMonthDays(month), [month]);
  const todayStr = todayKey();

  const shiftOf = (dateKey) => shiftForDate(shiftRequests, employeeId, dateKey, assignments);
  const hasConfirmed = days.some((d) => shiftOf(d.key)?.confirmed);

  const workDays = days.filter((d) => shiftOf(d.key)?.kind === 'ok').length;
  const paidDays = days.filter((d) => shiftOf(d.key)?.kind === 'paid').length;
  const filled = days.filter((d) => shiftOf(d.key)).length;

  const shiftMonth = (diff) => {
    const d = new Date(Number(month.slice(0, 4)), Number(month.slice(5, 7)) - 1 + diff, 1);
    setMonth(`${d.getFullYear()}-${pad(d.getMonth() + 1)}`);
  };

  // 1日ごとの色分け（出勤・有給・休み・未定）
  const toneOf = (kind) =>
    kind === 'ok' ? 'border-amber-500 bg-amber-50'
    : kind === 'paid' ? 'border-teal-300 bg-teal-50'
    : kind === 'off' ? 'border-slate-200 bg-slate-50'
    : 'border-dashed border-slate-200 bg-white';

  // PC表示はカレンダーの形にする。曜日が縦にそろうため、
  // 土日の出勤や連勤が一目で分かる。
  const WEEKDAY_HEADERS = ['日', '月', '火', '水', '木', '金', '土'];
  const renderMonthGrid = () => {
    const firstWeekday = new Date(`${month}-01T00:00:00`).getDay();
    const cells = [];
    for (let i = 0; i < firstWeekday; i++) cells.push(null);
    days.forEach((d) => cells.push(d));
    while (cells.length % 7 !== 0) cells.push(null);

    return (
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="grid grid-cols-7 border-b border-slate-100 bg-slate-50">
          {WEEKDAY_HEADERS.map((w, i) => (
            <div
              key={w}
              className={`py-2 text-center text-[11.5px] font-bold ${i === 0 ? 'text-rose-500' : i === 6 ? 'text-sky-500' : 'text-slate-400'}`}
            >
              {w}
            </div>
          ))}
        </div>
        <div className="grid grid-cols-7">
          {cells.map((d, i) => {
            if (!d) return <div key={`blank-${i}`} className="min-h-[5.5rem] border-b border-r border-slate-100 bg-slate-50/40 last:border-r-0" />;
            const shift = shiftOf(d.key);
            const isToday = d.key === todayStr;
            const kind = shift?.kind || '';
            const bg =
              kind === 'ok' ? 'bg-amber-50'
              : kind === 'paid' ? 'bg-teal-50'
              : kind === 'off' ? 'bg-white'
              : 'bg-white';
            return (
              <div
                key={d.key}
                className={`min-h-[5.5rem] border-b border-r border-slate-100 px-2 py-1.5 ${bg} ${isToday ? 'ring-2 ring-inset ring-slate-800' : ''}`}
              >
                <div className="flex items-baseline gap-1">
                  <span className={`text-[12.5px] font-bold ${d.isSunday || d.holidayName ? 'text-rose-600' : d.isSaturday ? 'text-sky-600' : 'text-slate-700'}`}>
                    {d.day}
                  </span>
                  {isToday && <span className="rounded-full bg-slate-800 px-1.5 py-[1px] text-[9px] font-bold text-white">今日</span>}
                </div>
                {d.holidayName && (
                  <div className="truncate text-[9.5px] font-bold text-rose-500" title={d.holidayName}>{d.holidayName}</div>
                )}
                <div className="mt-1">
                  {!shift ? (
                    <span className="text-[11px] text-slate-300">未定</span>
                  ) : kind === 'paid' ? (
                    <span className="text-[12px] font-bold text-teal-700">有給</span>
                  ) : kind === 'off' ? (
                    <span className="text-[11.5px] text-slate-400">休み</span>
                  ) : (
                    <span className="block break-words text-[12.5px] font-bold leading-tight text-slate-800" title={shift.place || '出勤'}>
                      {shift.place || '出勤'}
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  const renderDay = (d) => {
    const shift = shiftOf(d.key);
    const isToday = d.key === todayStr;
    const kind = shift?.kind || '';
    const tone = toneOf(kind);
    return (
      <div key={d.key} className={`rounded-xl border px-3 py-2.5 ${tone} ${isToday ? 'ring-2 ring-slate-800' : ''}`}>
        <div className="flex items-center gap-1.5 flex-wrap">
          <span className={`text-[12.5px] font-bold ${d.isSunday || d.holidayName ? 'text-rose-600' : d.isSaturday ? 'text-sky-600' : 'text-slate-700'}`}>
            {d.day}日({d.weekday})
          </span>
          {isToday && <span className="rounded-full bg-slate-800 px-1.5 py-[1px] text-[9.5px] font-bold text-white">今日</span>}
          {d.holidayName && (
            <span className="rounded-full bg-rose-50 px-1.5 py-[1px] text-[9.5px] font-bold text-rose-600">{d.holidayName}</span>
          )}
          <span className="ml-auto text-[13px] font-bold text-slate-800">
            {!shift ? <span className="text-[11.5px] font-medium text-slate-300">未定</span>
              : kind === 'paid' ? <span className="text-teal-700">有給</span>
              : kind === 'off' ? <span className="text-[11.5px] font-medium text-slate-400">休み</span>
              : (shift.place || '出勤')}
          </span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-3">
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-5 py-3.5 border-b border-slate-100 flex items-center gap-2 flex-wrap">
          <CalendarDays size={15} className="text-slate-400" />
          <h2 className="font-bold text-[13.5px]">シフト表</h2>
          {!hasConfirmed && filled > 0 && (
            <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10.5px] font-bold text-slate-500">提出した希望</span>
          )}
          <span className="ml-auto flex items-center gap-1">
            <button onClick={() => shiftMonth(-1)} className="rounded-lg border border-slate-200 p-1.5 text-slate-500" aria-label="前の月">
              <ChevronLeft size={14} />
            </button>
            <span className="min-w-[6.5rem] text-center text-[13px] font-bold text-slate-700">{monthKeyLabel(month)}</span>
            <button onClick={() => shiftMonth(1)} className="rounded-lg border border-slate-200 p-1.5 text-slate-500" aria-label="次の月">
              <ChevronRight size={14} />
            </button>
          </span>
        </div>
        <div className="px-5 py-3 grid grid-cols-3 gap-2">
          <div className="rounded-lg bg-slate-50 px-2.5 py-2 text-center">
            <div className="text-[10px] text-slate-400">出勤</div>
            <div className="font-mono text-[15px] font-bold text-slate-800">{workDays}日</div>
          </div>
          <div className="rounded-lg bg-slate-50 px-2.5 py-2 text-center">
            <div className="text-[10px] text-slate-400">有給</div>
            <div className="font-mono text-[15px] font-bold text-slate-800">{paidDays}日</div>
          </div>
          <div className="rounded-lg bg-slate-50 px-2.5 py-2 text-center">
            <div className="text-[10px] text-slate-400">休み</div>
            <div className="font-mono text-[15px] font-bold text-slate-800">{days.length - workDays - paidDays}日</div>
          </div>
        </div>
        {filled === 0 && (
          <div className="px-5 pb-4 text-[11.5px] text-slate-400">
            {monthKeyLabel(month)}のシフトはまだ出ていません。確定すると、ここに表示されます。
          </div>
        )}
        {!hasConfirmed && filled > 0 && (
          <div className="px-5 pb-4 text-[11.5px] text-amber-700">
            これはご自身が提出したシフト希望です。確定したシフトが取り込まれると、そちらに切り替わります。
          </div>
        )}
      </div>

      {filled > 0 && (isDesktop ? renderMonthGrid() : (
        <div className="space-y-2">
          {days.map(renderDay)}
        </div>
      ))}
    </div>
  );
}

// ---- メイングループごとの入力フォーマット ----
// app_settings に { "グループ名": { shift: 'symbol'|'place'|'none', performance: 'eo'|'simple'|'none' } } を
// JSON で1件だけ保存する。設定がないグループは下の既定値を使う。
const SETTING_GROUP_FORMATS = 'group_formats';

// シフト希望の入力の型
const SHIFT_FORMATS = {
  symbol: { label: '●×有給（3択）', desc: '1日ごとに 出勤可能／希望休／有給 から選びます' },
  place: { label: '活動場所を入力', desc: '希望休／有給は同じ。出勤できる日は活動場所を書きます' },
  none: { label: '使わない', desc: 'このグループには「シフト希望」を表示しません' },
};

// 保存されている設定を読む。壊れていても画面は動かす
function parseGroupFormats(settings) {
  try {
    const raw = settings?.[SETTING_GROUP_FORMATS];
    if (!raw) return {};
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch (e) {
    console.error('フォーマット設定の読み取りに失敗しました', e);
    return {};
  }
}

// 既定：eo業務は今までどおりの3択、それ以外のグループは活動場所の入力
function shiftFormatKeyFor(group, settings) {
  const key = parseGroupFormats(settings)[group]?.shift;
  if (SHIFT_FORMATS[key]) return key;
  return group === EO_GROUP_NAME ? 'symbol' : 'place';
}

// 既定：eo業務はeo用の実績入力、それ以外のグループは実績入力を出さない
function performanceFormatKeyFor(group, settings) {
  const key = parseGroupFormats(settings)[group]?.performance;
  if (key === 'none' || PERFORMANCE_FORMATS[key]) return key;
  return group === EO_GROUP_NAME ? 'eo' : 'none';
}

// 交通費申請の扱い。既定は「使う」（これまでどおり全員が対象）
const COMMUTE_FORMATS = {
  use: { label: '使う', desc: 'このグループのスタッフに「交通費申請」を表示します' },
  none: { label: '使わない', desc: 'このグループには「交通費申請」を表示しません' },
};

function commuteFormatKeyFor(group, settings) {
  const key = parseGroupFormats(settings)[group]?.commute;
  return COMMUTE_FORMATS[key] ? key : 'use';
}

// ---- 申請の対象かどうか（グループの既定 ＋ スタッフごとの例外）----
// グループごとの既定は上の group_formats（app_settings）で決める。
// スタッフごとの例外は employees の3列で、マスター管理者だけが変えられる（77番）。
//   null       … グループの設定に従う（これまでどおり。既存のスタッフは全員これ）
//   'exempt'   … この方には出さない
//   'required' … この方には出す
//
// シフト希望と実績入力は「入力の形」がグループ側にしかないため、
// グループが「使わない」設定のときに個人だけ「必要」にすることはできない。
// （出す形が決まらないため。画面でも「不要」だけを選べるようにしてある）
// 交通費申請は形が無く、出すか出さないかだけなので、両方向に設定できる。
const REQUIREMENT_FIELDS = {
  shift: { column: 'shiftRequestRequirement', label: 'シフト希望', canForce: false },
  performance: { column: 'performanceRequirement', label: '実績入力', canForce: false },
  commute: { column: 'commuteClaimRequirement', label: '交通費申請', canForce: true },
};

// グループの設定で「使う」ことになっているか
function groupUsesRequest(kind, group, settings) {
  if (kind === 'shift') return shiftFormatKeyFor(group, settings) !== 'none';
  if (kind === 'performance') return performanceFormatKeyFor(group, settings) !== 'none';
  if (kind === 'commute') return commuteFormatKeyFor(group, settings) !== 'none';
  return true;
}

// その方に申請を出すか。account は employees の1件（mainGroup と上の3列を持つ）
function requiresRequest(kind, account, settings) {
  const field = REQUIREMENT_FIELDS[kind];
  if (!field) return true;
  const own = account?.[field.column];
  if (own === 'exempt') return false;
  if (own === 'required' && field.canForce) return true;
  return groupUsesRequest(kind, account?.mainGroup || '', settings);
}

// スタッフ詳細で選べる値
const REQUIREMENT_CHOICES = [
  { value: '', label: 'グループの設定に従う' },
  { value: 'exempt', label: '不要（この方には出さない）' },
];
const REQUIREMENT_CHOICES_FORCEABLE = [
  { value: '', label: 'グループの設定に従う' },
  { value: 'required', label: '必要（この方には出す）' },
  { value: 'exempt', label: '不要（この方には出さない）' },
];

function requirementLabel(kind, account, settings) {
  const field = REQUIREMENT_FIELDS[kind];
  const own = account?.[field?.column];
  if (own === 'exempt') return '不要';
  if (own === 'required' && field?.canForce) return '必要';
  return groupUsesRequest(kind, account?.mainGroup || '', settings) ? 'グループの設定どおり（必要）' : 'グループの設定どおり（不要）';
}

// ---- 実績入力の締切 ----
// 「翌月の何日まで本人が編集できるか」を日にちの数字で持つ。
// 0（または未設定）は「締切を設けない」＝いつでも本人が直せる。
// 締切を過ぎても、管理者は「実績の確認」からいつでも直せる。
//
// 設定は2段構え：
//   ・全業務に共通の既定 … app_settings の performance_deadline_day（数字1つ）
//   ・業務ごとの設定     … group_formats の perfDeadline（業務ごとの数字）
// 業務ごとの設定が無い業務は、共通の既定に従う。
const SETTING_PERF_DEADLINE_DAY = 'performance_deadline_day';

// 1〜28 だけを有効な日にちとする（月末が28日の2月でも必ず来る日に限る）
function normalizePerfDeadlineDay(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  const d = Math.floor(n);
  if (d === 0) return 0;
  if (d < 1 || d > 28) return null;
  return d;
}

// 全業務に共通の既定
function perfDeadlineDefaultDay(settings) {
  return normalizePerfDeadlineDay(settings?.[SETTING_PERF_DEADLINE_DAY]) ?? 0;
}

// その業務に設定された日にち。未設定なら共通の既定に従う。
// 業務に 0 が設定されているときは「この業務は締切なし」として扱う。
function perfDeadlineDayFor(group, settings) {
  const raw = parseGroupFormats(settings)[group]?.perfDeadline;
  if (raw !== undefined && raw !== null && raw !== '') {
    const own = normalizePerfDeadlineDay(raw);
    if (own !== null) return own;
  }
  return perfDeadlineDefaultDay(settings);
}

// その業務に専用の設定があるか（画面で「既定に従う」と区別するため）
function hasOwnPerfDeadline(group, settings) {
  const raw = parseGroupFormats(settings)[group]?.perfDeadline;
  if (raw === undefined || raw === null || raw === '') return false;
  return normalizePerfDeadlineDay(raw) !== null;
}

// 対象月（year年month月分）の実績を、本人が編集できる最後の瞬間
// 「翌月○日のおわり」まで。日本時間で判定する（端末の時計を使う）
function perfDeadlineAt(group, year, month, settings) {
  const day = perfDeadlineDayFor(group, settings);
  if (!day) return null;
  // new Date の月は0始まりのため、month をそのまま渡すと「翌月」になる
  return new Date(year, month, day, 23, 59, 59, 999);
}

function perfDeadlineLabel(group, year, month, settings) {
  const at = perfDeadlineAt(group, year, month, settings);
  if (!at) return '';
  return `${at.getFullYear()}年${at.getMonth() + 1}月${at.getDate()}日`;
}

// 本人の編集が締め切られているか
function isPerfLockedForStaff(group, year, month, settings, now = new Date()) {
  const at = perfDeadlineAt(group, year, month, settings);
  if (!at) return false;
  return now.getTime() > at.getTime();
}

// ---- シフト希望の答えの読み書き ----
// 値は 'ok' | 'off' | 'paid' | 'place:<活動場所>' のいずれか
const SHIFT_PLACE_PREFIX = 'place:';
const isPlaceAnswer = (v) => String(v || '').startsWith(SHIFT_PLACE_PREFIX);
// 出勤・休み・有給のどれか（活動場所の入力も「出勤」として扱う）
function shiftAnswerKind(v) {
  if (!v) return '';
  return isPlaceAnswer(v) ? 'ok' : v;
}
function shiftAnswerPlace(v) {
  return isPlaceAnswer(v) ? String(v).slice(SHIFT_PLACE_PREFIX.length) : '';
}
// 一覧や書き出しに出す文字
function shiftAnswerText(v) {
  const place = shiftAnswerPlace(v).trim();
  if (place) return place;
  if (v === 'ok') return '●';
  if (v === 'off') return '×';
  if (v === 'paid') return '有給';
  return '';
}
// 入力済みとみなせるか（活動場所が空のままは未入力）
function shiftAnswerFilled(v) {
  if (!v) return false;
  return isPlaceAnswer(v) ? shiftAnswerPlace(v).trim().length > 0 : true;
}

