// ---- 現在ログイン中のユーザーが見える範囲のデータを全テーブルから取得 ----
// （RLSが自動でフィルタしてくれるため、スタッフは自分の行だけ、管理者は全行が返る）
async function fetchAllData() {
  const [
    employeesRes,
    recordsRes,
    correctionsRes,
    leaveRes,
    notifRes,
    payrollRes,
    auditRes,
    profileReqRes,
    groupLeaveRes,
    employeeAttendanceRes,
    announcementsRes,
    yearEndRes,
    commuteClaimsRes,
    resignationReasonsRes,
    appSettingsRes,
    monthlyConfirmRes,
    shiftPeriodRes,
    shiftRequestRes,
    bonusRes,
    assignmentRes,
    importLogRes,
    aliasRes,
    shiftChangeRes,
    loginAttemptRes,
    leaveGrantRes,
  ] = await Promise.all([
    // 個人情報（住所・生年月日・口座・賃金など）は本人とマスター管理者にしか
    // 返らない。管理者には null で返る。詳しくは supabase/71_employee_sensitive_fields.sql
    supabase.from('employees_visible').select('*'),
    supabase.from('attendance_records').select('*'),
    supabase.from('corrections').select('*, employees(name)'),
    supabase.from('leave_requests').select('*, employees(name)'),
    supabase.from('notifications').select('*').order('sent_at', { ascending: false }).limit(50),
    supabase.from('payroll_records').select('*, employees(name)'),
    supabase.from('audit_logs').select('*').order('created_at', { ascending: false }).limit(100),
    supabase.from('profile_update_requests').select('*, employees(name)').order('submitted_at', { ascending: false }),
    supabase.from('group_attendance_schedules').select('*'),
    supabase.from('employee_attendance_schedules').select('*'),
    supabase.from('announcements').select('*').order('is_pinned', { ascending: false }).order('created_at', { ascending: false }),
    supabase.from('year_end_adjustments').select('*, employees(name)').order('submitted_at', { ascending: false }),
    supabase.from('commute_expense_claims').select('*, employees(name)').order('created_at', { ascending: false }),
    supabase.from('resignation_reasons').select('*').order('sort_order', { ascending: true }),
    supabase.from('app_settings').select('*'),
    supabase.from('monthly_attendance_confirmations').select('*, employees(name)').order('target_month', { ascending: false }),
    supabase.from('shift_request_periods').select('*').order('target_month', { ascending: false }),
    supabase.from('shift_request_answers').select('*, employees(name)').order('target_month', { ascending: false }),
    supabase.from('bonus_records').select('*, employees(name)').order('year', { ascending: false }),
    supabase.from('shift_assignments').select('*').order('date', { ascending: true }),
    supabase.from('shift_import_logs').select('*').order('imported_at', { ascending: false }).limit(20),
    supabase.from('shift_name_aliases').select('*'),
    supabase.from('shift_assignment_changes').select('*').order('changed_at', { ascending: false }).limit(500),
    supabase.from('login_attempts').select('*').order('occurred_at', { ascending: false }).limit(100),
    // 有休の付与レコード（引き継ぎ・手動分。法定付与は入職日から導く）
    supabase.from('employee_leave_grants').select('*').order('grant_date', { ascending: true }),
  ]);

  for (const res of [employeesRes, recordsRes, correctionsRes, leaveRes, notifRes, payrollRes, auditRes, profileReqRes, groupLeaveRes, employeeAttendanceRes, announcementsRes, yearEndRes, commuteClaimsRes]) {
    if (res.error) throw res.error;
  }
  // 退職理由マスタはSQL未実行でも画面が落ちないよう、エラー時は空扱いにする
  const resignationReasons = resignationReasonsRes?.error ? [] : (resignationReasonsRes?.data || []).map(rowToResignationReason);

  // 月次勤怠の確定（SQL未実行でも画面が落ちないよう、エラー時は空扱いにする）
  const monthlyConfirmations = monthlyConfirmRes?.error ? [] : (monthlyConfirmRes?.data || []).map(rowToMonthlyConfirm);

  // シフト希望（SQL未実行でも画面が落ちないよう、エラー時は空扱いにする）
  const shiftPeriods = shiftPeriodRes?.error ? [] : (shiftPeriodRes?.data || []).map(rowToShiftPeriod);
  const shiftRequests = shiftRequestRes?.error ? [] : (shiftRequestRes?.data || []).map(rowToShiftRequest);
  // SQLが未実行だとテーブルが無く、取得に失敗する。画面でお知らせするために持っておく
  const shiftTablesReady = !shiftPeriodRes?.error && !shiftRequestRes?.error;

  // 賞与明細（SQL未実行でも画面が落ちないよう、エラー時は空扱いにする）
  const bonusRecords = bonusRes?.error ? [] : (bonusRes?.data || []).map(rowToBonus);
  const bonusTableReady = !bonusRes?.error;

  // 確定シフト（SQL未実行でも画面が落ちないよう、エラー時は空扱いにする）
  const shiftAssignments = assignmentRes?.error ? [] : (assignmentRes?.data || []).map(rowToAssignment);
  const shiftAssignmentReady = !assignmentRes?.error;
  const shiftImportLogs = importLogRes?.error ? [] : (importLogRes?.data || []).map(rowToImportLog);
  const shiftNameAliases = aliasRes?.error ? [] : (aliasRes?.data || []).map(rowToShiftAlias);
  const shiftChanges = shiftChangeRes?.error ? [] : (shiftChangeRes?.data || []).map(rowToShiftChange);

  // ログイン失敗の記録（管理者以外はRLSで0件、SQL未実行ならエラー→空扱い）
  const loginAttempts = loginAttemptRes?.error ? [] : (loginAttemptRes?.data || []).map(rowToLoginAttempt);

  // 有休の付与レコード（SQL未実行でも画面が落ちないよう、エラー時は空扱いにする）
  // 空のときは法定付与だけで計算されます（引き継ぎ分は入らない）。
  const leaveGrants = leaveGrantRes?.error ? [] : (leaveGrantRes?.data || []).map(rowToLeaveGrant);
  const leaveGrantsReady = !leaveGrantRes?.error;

  // アプリ全体の設定（SQL未実行でも画面が落ちないよう、エラー時は空扱いにする）
  const settings = {};
  if (!appSettingsRes?.error) {
    (appSettingsRes?.data || []).forEach((row) => { settings[row.key] = row.value || ''; });
  }

  const records = {};
  (recordsRes.data || []).forEach((row) => {
    records[row.employee_id] = records[row.employee_id] || {};
    records[row.employee_id][row.date] = rowToRecord(row);
  });

  // グループ別「出勤規定日数」（月ごと・1〜12月）
  const groupLeaveSchedules = {};
  (groupLeaveRes.data || []).forEach((row) => {
    groupLeaveSchedules[row.group_name] = groupLeaveSchedules[row.group_name] || {};
    groupLeaveSchedules[row.group_name][row.year] = groupLeaveSchedules[row.group_name][row.year] || {};
    groupLeaveSchedules[row.group_name][row.year][row.month] = Number(row.days);
  });

  // 個人別「出勤規定日数」（グループ未設定のスタッフが対象・月ごと）
  const employeeAttendanceSchedules = {};
  (employeeAttendanceRes.data || []).forEach((row) => {
    employeeAttendanceSchedules[row.employee_id] = employeeAttendanceSchedules[row.employee_id] || {};
    employeeAttendanceSchedules[row.employee_id][row.year] = employeeAttendanceSchedules[row.employee_id][row.year] || {};
    employeeAttendanceSchedules[row.employee_id][row.year][row.month] = Number(row.days);
  });

  return {
    accounts: (employeesRes.data || []).map(rowToAccount),
    records,
    corrections: (correctionsRes.data || []).map(rowToCorrection),
    leaveRequests: (leaveRes.data || []).map(rowToLeave),
    leaveBalances: {},
    payrollRecords: (payrollRes.data || []).map(rowToPayroll),
    notifications: (notifRes.data || []).map(rowToNotif),
    auditLogs: (auditRes.data || []).map(rowToAudit),
    profileUpdateRequests: (profileReqRes.data || []).map(rowToProfileRequest),
    groupLeaveSchedules,
    employeeAttendanceSchedules,
    leaveGrants,
    leaveGrantsReady,
    announcements: (announcementsRes.data || []).map(rowToAnnouncement),
    yearEndAdjustments: (yearEndRes.data || []).map(rowToYearEndAdjustment),
    commuteExpenseClaims: (commuteClaimsRes.data || []).map(rowToCommuteClaim),
    resignationReasons,
    monthlyConfirmations,
    shiftPeriods,
    shiftRequests,
    shiftTablesReady,
    bonusRecords,
    bonusTableReady,
    shiftAssignments,
    shiftAssignmentReady,
    shiftImportLogs,
    shiftNameAliases,
    shiftChanges,
    loginAttempts,
    settings,
  };
}

// 管理者宛の通知メールの送信先を求める。
// 設定があればそれを使い、無ければマスター管理者（居なければ管理者）のアドレスを使う。
// 連絡用メールアドレスが未登録の場合は、ログインIDのアドレスで代用する。
function resolveAdminNotifyAddresses(data) {
  const configured = (data?.settings?.[SETTING_ADMIN_NOTIFY_EMAIL] || '').trim();
  if (configured) {
    return configured.split(/[,、\s]+/).map((v) => v.trim()).filter((v) => v.includes('@'));
  }
  const addressOf = (a) => {
    if ((a.contactEmail || '').includes('@')) return a.contactEmail;
    if ((a.username || '').includes('@')) return a.username;
    return '';
  };
  const accounts = (data?.accounts || []).filter((a) => !a.resignationDate);
  const masters = accounts.filter((a) => a.role === 'master_admin').map(addressOf).filter(Boolean);
  if (masters.length > 0) return masters;
  return accounts.filter((a) => a.role === 'admin').map(addressOf).filter(Boolean);
}

// 通知はベストエフォート（失敗してもメイン処理は止めない）
async function notify(subject, body, relatedId, toEmployeeId = null, toRole = 'admin') {
  try {
    await supabase.from('notifications').insert({
      to_employee_id: toEmployeeId,
      to_role: toRole,
      subject,
      body,
      related_id: relatedId,
    });
  } catch (e) {
    console.error('通知の記録に失敗しました', e);
  }
}

// 実メール送信（Resend未設定の場合は何もしない。失敗してもアプリ本体は止めない）
async function sendEmailBestEffort(toEmail, subject, text) {
  if (!toEmail) return;
  try {
    const { data: sessionData } = await supabase.auth.getSession();
    const accessToken = sessionData?.session?.access_token;
    await supabase.functions.invoke('send-email', {
      body: { to: toEmail, subject, text },
      headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined,
    });
  } catch (e) {
    console.error('メール送信に失敗しました（アプリの動作には影響ありません）', e);
  }
}

// 2段階認証を設定している人かどうか（＝いまコードの入力が必要か）を調べる。
// currentLevel が aal1 のまま nextLevel が aal2 のときは、まだコードを入れていない。
async function needsMfaChallenge() {
  try {
    const { data, error } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
    if (error || !data) return false;
    return data.nextLevel === 'aal2' && data.currentLevel !== 'aal2';
  } catch (e) {
    console.error('2段階認証の確認に失敗しました', e);
    return false;
  }
}

// 入力された6桁のコードで本人確認を済ませる
async function verifyMfaCode(code) {
  const { data: listed, error: listError } = await supabase.auth.mfa.listFactors();
  if (listError) throw listError;
  const factor = (listed?.totp || []).find((f) => f.status === 'verified');
  if (!factor) throw new Error('2段階認証の設定が見つかりません');
  const { data: ch, error: chError } = await supabase.auth.mfa.challenge({ factorId: factor.id });
  if (chError) throw chError;
  const { error: vError } = await supabase.auth.mfa.verify({
    factorId: factor.id,
    challengeId: ch.id,
    code: String(code).replace(/\s/g, ''),
  });
  if (vError) throw vError;
}

// マイナンバーの読み書きは、すべて my-number 関数を通す。
// 番号は暗号化して保存され、復号の鍵はこの関数のシークレットにしか無い。
// ブラウザ側は鍵を持たないため、アプリのキーが漏れても番号は読めない。
// 閲覧・保存・廃棄は関数側で必ず監査ログに記録される。
async function callMyNumberFunction(payload) {
  try {
    const { data: sessionData } = await supabase.auth.getSession();
    const accessToken = sessionData?.session?.access_token;
    if (!accessToken) return { error: 'ログインの情報が取得できませんでした' };
    const { data, error } = await supabase.functions.invoke('my-number', {
      body: payload,
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (data?.error) return { error: data.error };
    if (error) {
      // 関数が 4xx を返した場合、本文にこちらのメッセージが入っている
      if (error.context) {
        try {
          const body = await error.context.json();
          if (body?.error) return { error: body.error };
        } catch (_) { /* noop */ }
      }
      return { error: 'マイナンバーの処理に失敗しました' };
    }
    return data || {};
  } catch (e) {
    console.error('マイナンバーの処理に失敗しました', e);
    return { error: 'マイナンバーの処理に失敗しました' };
  }
}

// 退職日を過ぎたスタッフのログインを Supabase Auth 側で止める。
// 画面の中で signOut するだけでは、すでに持っているトークンで
// APIを直接叩けてしまうため、アカウントそのものを停止する。
// 管理者のログイン時と、退職日を保存したときに呼ぶ。
// 失敗してもアプリの動作は止めない（次に管理者がログインしたときに再び試みる）。
async function syncResignedAuth() {
  try {
    const { data: sessionData } = await supabase.auth.getSession();
    const accessToken = sessionData?.session?.access_token;
    if (!accessToken) return null;
    const { data, error } = await supabase.functions.invoke('sync-resigned-auth', {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (error) {
      console.error('退職者のログイン停止に失敗しました', error);
      return null;
    }
    return data;
  } catch (e) {
    console.error('退職者のログイン停止に失敗しました', e);
    return null;
  }
}

