// ---- 有休の付与レコードの登録・削除（管理者以上。RLSでも絞っています） ----
// 法定の付与は入職日から導くため、ここで登録するのは
//   ・ジョブカンからの引き継ぎ（carryover）
//   ・法定どおりに導けない分を手で足す／直す（manual）
// の2種類だけです。同じ付与日の法定付与は、この行で上書きされます。
async function saveLeaveGrant({ id, employeeId, grantDate, days, kind, note }, actor = null, targetName = '') {
  const payload = {
    employee_id: employeeId,
    grant_date: grantDate,
    days: Number(days),
    kind,
    note: note || null,
    created_by: actor?.id || null,
  };
  const { error } = id
    ? await supabase.from('employee_leave_grants').update(payload).eq('id', id)
    : await supabase.from('employee_leave_grants').insert(payload);
  if (error) {
    console.error('有休の付与の保存に失敗しました', error);
    return { ok: false, message: error.message || '' };
  }
  await logAudit(
    actor,
    id ? '有休の付与を変更' : '有休の付与を登録',
    `${dateLabelY(grantDate)}付与・${fmtDays(Number(days))}日（${kind === 'carryover' ? '引き継ぎ' : '手動'}）${note ? `／${note}` : ''}`,
    employeeId,
    targetName
  );
  return { ok: true };
}

async function deleteLeaveGrant(grant, actor = null, targetName = '') {
  const { error } = await supabase.from('employee_leave_grants').delete().eq('id', grant.id);
  if (error) {
    console.error('有休の付与の削除に失敗しました', error);
    return { ok: false, message: error.message || '' };
  }
  await logAudit(
    actor,
    '有休の付与を削除',
    `${dateLabelY(grant.grantDate)}付与・${fmtDays(grant.days)}日`,
    grant.employeeId,
    targetName
  );
  return { ok: true };
}

// ---- 給与設定（毎月の固定支給・控除項目／通勤手当の経路／標準報酬月額） ----
async function fetchEmployeeSalaryItems(employeeId) {
  const { data, error } = await supabase
    .from('employee_salary_items')
    .select('*')
    .eq('employee_id', employeeId)
    .order('sort_order', { ascending: true });
  if (error) { console.error('固定支給・控除項目の取得に失敗しました', error); return []; }
  return (data || []).map((row) => ({ id: row.id, kind: row.kind, label: row.label, amount: Number(row.amount) || 0, sortOrder: row.sort_order }));
}

// 固定支給・控除項目の保存。
//
// 以前は「全削除→再作成」でした。削除が成功して追加が失敗すると、その人の
// 固定項目がすべて消えてしまうため、次の順番に変えています。
//   1. 残す項目を更新・追加する（IDはそのまま引き継ぐ）
//   2. 最後に、消えた項目だけを削除する
// 途中で失敗しても既存の項目は残ります。
// IDが変わらないので、どの項目をいくらからいくらに直したのかも記録できます。
//
// 戻り値：{ ok, changes }  changes は変更内容の説明（監査ログに残したもの）
async function saveEmployeeSalaryItems(employeeId, items, actor = null, targetName = '') {
  const before = await fetchEmployeeSalaryItems(employeeId);
  const kept = (items || []).filter((it) => String(it.label || '').trim());

  const fail = (e) => {
    console.error('固定支給・控除項目の保存に失敗しました', e);
    return { ok: false, changes: [] };
  };

  // 1. 残す項目を更新・追加
  for (let i = 0; i < kept.length; i += 1) {
    const it = kept[i];
    const row = {
      employee_id: employeeId,
      kind: it.kind,
      label: String(it.label).trim(),
      amount: Number(it.amount) || 0,
      sort_order: i,
    };
    if (it.id) {
      const { error } = await supabase.from('employee_salary_items').update(row).eq('id', it.id);
      if (error) return fail(error);
    } else {
      const { error } = await supabase.from('employee_salary_items').insert(row);
      if (error) return fail(error);
    }
  }

  // 2. 消えた項目だけを削除
  const keptIds = new Set(kept.filter((it) => it.id).map((it) => it.id));
  const removed = before.filter((b) => !keptIds.has(b.id));
  if (removed.length > 0) {
    const { error } = await supabase
      .from('employee_salary_items')
      .delete()
      .in('id', removed.map((r) => r.id));
    if (error) return fail(error);
  }

  // 変更内容をまとめる
  const kindLabel = (k) => (k === 'deduction' ? '控除' : '支給');
  const changes = [];
  kept.forEach((it) => {
    const old = it.id ? before.find((b) => b.id === it.id) : null;
    const amount = Number(it.amount) || 0;
    const label = String(it.label).trim();
    if (!old) {
      changes.push(`追加：${kindLabel(it.kind)}「${label}」${formatYen(amount)}`);
      return;
    }
    if (old.label !== label) changes.push(`名称：${kindLabel(it.kind)}「${old.label}」→「${label}」`);
    if (old.amount !== amount) changes.push(`金額：${kindLabel(it.kind)}「${label}」${formatYen(old.amount)} → ${formatYen(amount)}`);
  });
  removed.forEach((r) => changes.push(`削除：${kindLabel(r.kind)}「${r.label}」${formatYen(r.amount)}`));

  if (changes.length > 0 && actor) {
    await logAudit(actor, '固定支給・控除項目を変更', changes.join('／'), employeeId, targetName);
  }
  return { ok: true, changes };
}

async function fetchEmployeeCommuteRoutes(employeeId) {
  const { data, error } = await supabase
    .from('employee_commute_routes')
    .select('*')
    .eq('employee_id', employeeId)
    .order('sort_order', { ascending: true });
  if (error) { console.error('通勤経路の取得に失敗しました', error); return []; }
  return (data || []).map((row) => ({
    id: row.id,
    transportMethod: row.transport_method || '電車',
    boardingStation: row.boarding_station || '',
    alightingStation: row.alighting_station || '',
    viaPoint: row.via_point || '',
    paymentUnit: row.payment_unit || 'monthly_pass',
    oneWayFare: Number(row.one_way_fare) || 0,
    passFare: Number(row.pass_fare) || 0,
    sortOrder: row.sort_order,
  }));
}

// 通勤経路の保存。固定支給・控除項目と同じ理由で、全削除→再作成はやめている
// （途中で失敗したときに経路がすべて消えるのを防ぐため）
async function saveEmployeeCommuteRoutes(employeeId, routes, actor = null, targetName = '') {
  const before = await fetchEmployeeCommuteRoutes(employeeId);
  const kept = routes || [];

  const fail = (e) => {
    console.error('通勤経路の保存に失敗しました', e);
    return { ok: false, changes: [] };
  };

  for (let i = 0; i < kept.length; i += 1) {
    const r = kept[i];
    const row = {
      employee_id: employeeId,
      transport_method: r.transportMethod,
      boarding_station: r.boardingStation || null,
      alighting_station: r.alightingStation || null,
      via_point: r.viaPoint || null,
      payment_unit: r.paymentUnit,
      one_way_fare: Number(r.oneWayFare) || 0,
      pass_fare: Number(r.passFare) || 0,
      sort_order: i,
    };
    if (r.id) {
      const { error } = await supabase.from('employee_commute_routes').update(row).eq('id', r.id);
      if (error) return fail(error);
    } else {
      const { error } = await supabase.from('employee_commute_routes').insert(row);
      if (error) return fail(error);
    }
  }

  const keptIds = new Set(kept.filter((r) => r.id).map((r) => r.id));
  const removed = before.filter((b) => !keptIds.has(b.id));
  if (removed.length > 0) {
    const { error } = await supabase
      .from('employee_commute_routes')
      .delete()
      .in('id', removed.map((r) => r.id));
    if (error) return fail(error);
  }

  const routeLabel = (r) => `${r.boardingStation || '?'}→${r.alightingStation || '?'}`;
  const changes = [];
  kept.forEach((r) => {
    const old = r.id ? before.find((b) => b.id === r.id) : null;
    if (!old) {
      changes.push(`追加：${routeLabel(r)}（月額換算 ${formatYen(Math.round(computeRouteMonthlyAmount(r)))}）`);
      return;
    }
    const beforeAmount = Math.round(computeRouteMonthlyAmount(old));
    const afterAmount = Math.round(computeRouteMonthlyAmount(r));
    if (routeLabel(old) !== routeLabel(r)) changes.push(`経路：${routeLabel(old)} → ${routeLabel(r)}`);
    if (beforeAmount !== afterAmount) changes.push(`金額：${routeLabel(r)} ${formatYen(beforeAmount)} → ${formatYen(afterAmount)}`);
  });
  removed.forEach((r) => changes.push(`削除：${routeLabel(r)}`));

  if (changes.length > 0 && actor) {
    await logAudit(actor, '通勤経路を変更', changes.join('／'), employeeId, targetName);
  }
  return { ok: true, changes };
}

// 経路1件あたりの月額換算（支給単位に応じて計算）
function computeRouteMonthlyAmount(route, referenceDaysPerMonth = 20) {
  switch (route.paymentUnit) {
    case 'monthly_pass': return route.passFare;
    case 'three_month_pass': return route.passFare / 3;
    case 'six_month_pass': return route.passFare / 6;
    case 'round_trip_daily': return route.oneWayFare * 2 * referenceDaysPerMonth;
    default: return route.passFare;
  }
}

async function fetchStandardRemuneration(employeeId, year, month) {
  const { data, error } = await supabase
    .from('employee_standard_remuneration')
    .select('*')
    .eq('employee_id', employeeId)
    .eq('year', year)
    .eq('month', month)
    .maybeSingle();
  if (error) { console.error('標準報酬月額の取得に失敗しました', error); return null; }
  if (!data) return null;
  return {
    healthInsuranceAmount: data.health_insurance_amount != null ? Number(data.health_insurance_amount) : null,
    pensionAmount: data.pension_amount != null ? Number(data.pension_amount) : null,
    healthInsurancePremium: data.health_insurance_premium != null ? Number(data.health_insurance_premium) : null,
    nursingInsurancePremium: data.nursing_insurance_premium != null ? Number(data.nursing_insurance_premium) : null,
    pensionPremium: data.pension_premium != null ? Number(data.pension_premium) : null,
  };
}

// その月に適用される標準報酬月額。対象月以前で一番新しい登録を使います。
// 標準報酬月額は定時決定で1年間そのままなので、月ごとに登録させると
// 1人あたり年12件になってしまいます。1回登録すれば、変えるまで効き続けます。
async function fetchEffectiveStandardRemuneration(employeeId, year, month) {
  const { data, error } = await supabase
    .from('employee_standard_remuneration')
    .select('*')
    .eq('employee_id', employeeId)
    // 「その年の対象月まで」または「前の年すべて」
    .or(`year.lt.${year},and(year.eq.${year},month.lte.${month})`)
    .order('year', { ascending: false })
    .order('month', { ascending: false })
    .limit(1);
  if (error) { console.error('標準報酬月額の取得に失敗しました', error); return null; }
  const row = (data || [])[0];
  if (!row) return null;
  return {
    year: row.year,
    month: row.month,
    healthInsuranceAmount: row.health_insurance_amount != null ? Number(row.health_insurance_amount) : null,
    pensionAmount: row.pension_amount != null ? Number(row.pension_amount) : null,
  };
}

// 雇用保険の料率と、支給項目ごとの扱いを保存する（全社共通・マスター管理者のみ）
async function saveEmploymentInsuranceSettings({ rate, flags }, actor = null) {
  const rows = [];
  if (rate != null) {
    rows.push({ key: SETTING_EI_RATE, value: String(rate), updated_by: actor?.id || null, updated_at: new Date().toISOString() });
  }
  if (flags != null) {
    rows.push({ key: SETTING_PAYMENT_ITEM_FLAGS, value: JSON.stringify(flags), updated_by: actor?.id || null, updated_at: new Date().toISOString() });
  }
  if (rows.length === 0) return { ok: true };
  const { error } = await supabase.from('app_settings').upsert(rows, { onConflict: 'key' });
  if (error) {
    console.error('雇用保険の設定の保存に失敗しました', error);
    return { ok: false, message: error.message || '' };
  }
  await logAudit(
    actor,
    '雇用保険の設定を変更',
    [rate != null ? `料率 ${rate}%` : '', flags != null ? '支給項目の扱い' : ''].filter(Boolean).join('／')
  );
  return { ok: true };
}

// 住民税の控除月の取り方を保存する（全社共通の設定・マスター管理者のみ）。
// app_settings の書き込みは27番でマスター管理者に限っています。
async function saveResidentTaxOffset(value, actor = null) {
  const next = value === 'same' ? 'same' : 'next';
  const { error } = await supabase.from('app_settings').upsert(
    {
      key: SETTING_RESIDENT_TAX_OFFSET,
      value: next,
      updated_by: actor?.id || null,
      updated_at: new Date().toISOString(),
    },
    { onConflict: 'key' }
  );
  if (error) {
    console.error('住民税の控除月の設定の保存に失敗しました', error);
    return { ok: false, message: error.message || '' };
  }
  await logAudit(
    actor,
    '住民税の控除月の設定を変更',
    next === 'same' ? '明細の月と同じ月の住民税を引く' : '明細の月の翌月分の住民税を引く'
  );
  return { ok: true };
}

