// ---- 月ごとの規定勤怠時間パターン（スタッフが月初に自分で設定） ----
async function fetchSchedulePatterns(employeeId, year, month) {
  const { data, error } = await supabase
    .from('employee_schedule_patterns')
    .select('*')
    .eq('employee_id', employeeId)
    .eq('year', year)
    .eq('month', month)
    .order('pattern_no', { ascending: true });
  if (error) { console.error('規定勤怠時間の取得に失敗しました', error); return []; }
  return (data || []).map((row) => ({
    patternNo: row.pattern_no,
    label: row.label || '',
    startTime: row.start_time,
    endTime: row.end_time,
  }));
}

async function saveSchedulePatterns(employeeId, year, month, patterns) {
  // 空欄になったパターンは削除、それ以外はupsert
  const toSave = patterns.filter((p) => p.startTime && p.endTime);
  const toDeleteNos = patterns.filter((p) => !p.startTime || !p.endTime).map((p) => p.patternNo);
  if (toSave.length > 0) {
    const { error } = await supabase.from('employee_schedule_patterns').upsert(
      toSave.map((p) => ({
        employee_id: employeeId,
        year,
        month,
        pattern_no: p.patternNo,
        label: p.label || null,
        start_time: p.startTime,
        end_time: p.endTime,
        updated_at: new Date().toISOString(),
      })),
      { onConflict: 'employee_id,year,month,pattern_no' }
    );
    if (error) { console.error('規定勤怠時間の保存に失敗しました', error); return false; }
  }
  if (toDeleteNos.length > 0) {
    const { error } = await supabase
      .from('employee_schedule_patterns')
      .delete()
      .eq('employee_id', employeeId)
      .eq('year', year)
      .eq('month', month)
      .in('pattern_no', toDeleteNos);
    if (error) console.error('規定勤怠時間の削除に失敗しました', error);
  }
  return true;
}

// ============================================================
// Main App
// ============================================================
function AttendanceApp() {
  const [data, setData] = useState(EMPTY_DATA);
  const [loaded, setLoaded] = useState(false);
  const [cloudStatus, setCloudStatus] = useState(CLOUD_ENABLED ? 'connecting' : 'local');
  const [session, setSession] = useState(null); // { id, username, name, role, hireDate, resignationDate }
  // 2段階認証のコード待ち（パスワードは通ったが、まだコードを入れていない状態）
  const [mfaPending, setMfaPending] = useState(false);
  const [correctionModal, setCorrectionModal] = useState(null);
  const [leaveModalOpen, setLeaveModalOpen] = useState(false);
  // スタッフ画面の「勤怠」タブの中のサブタブ（勤怠＝打刻／実績＝実績入力／シフト＝月間シフト）
  const [employeeTab, setEmployeeTab] = useState('attendance');
  const [topTab, setTopTab] = useState('attendance'); // attendance | labor | requests(スタッフ) | hr(管理) | payroll | help
  // 各種申請タブの中でいま開いている申請（null = 候補の一覧）
  const [requestTab, setRequestTab] = useState(null);
  // 管理者が自分の打刻・申請画面を開いているかどうか
  const [personalMode, setPersonalMode] = useState(false);
  const [viewMode, setViewMode] = useState(() => (typeof window !== 'undefined' && window.matchMedia('(min-width: 1024px)').matches ? 'desktop' : 'mobile'));
  const [schedulePatterns, setSchedulePatterns] = useState([]);
  const [activePatternNo, setActivePatternNo] = useState(1);
  const [passwordRecoveryMode, setPasswordRecoveryMode] = useState(false);
  // メールのリンクから戻ってきたときのエラー文（ログイン画面に出す）
  const [linkError, setLinkError] = useState('');
  // 「要対応」や通知から、管理画面の特定のサブ画面を開くための指定
  const [pendingAdminTab, setPendingAdminTab] = useState(null);
  // 初回ログインのパスワード設定・登録情報の入力中は、時計の更新を止める
  // （毎秒の再描画でスマートフォンのキーボードが閉じてしまうため）
  const isOnboarding = !!session && (session.mustChangePassword === true || session.profileSetupCompleted === false);
  const now = useNow(!!session && !isOnboarding && !passwordRecoveryMode);
  const geo = useGeolocation();
  const { toast, show } = useToast();

  // 上部メニューの高さをCSS変数にしておき、全画面表示の詳細ページがメニューを隠さないようにする
  const appHeaderRef = useRef(null);
  useEffect(() => {
    const el = appHeaderRef.current;
    if (!el) return;
    const update = () => document.documentElement.style.setProperty('--app-header-h', `${el.offsetHeight}px`);
    update();
    let ro = null;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(update);
      ro.observe(el);
    }
    window.addEventListener('resize', update);
    return () => {
      if (ro) ro.disconnect();
      window.removeEventListener('resize', update);
    };
  });

  // 画面を切り替えたら一番上に戻し、最新データを取得し直す
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
    if (CLOUD_ENABLED && session) refreshData({ showIndicator: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [topTab, requestTab, employeeTab, personalMode]);

  // 今月の規定勤怠時間パターンを取得（管理者も自分の打刻画面で使うため全員分取得する）
  useEffect(() => {
    if (!session) return;
    const y = now.getFullYear();
    const m = now.getMonth() + 1;
    fetchSchedulePatterns(session.id, y, m).then((patterns) => {
      setSchedulePatterns(patterns);
      if (patterns.length > 0 && !patterns.some((p) => p.patternNo === activePatternNo)) {
        setActivePatternNo(patterns[0].patternNo);
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session?.id, now.getFullYear(), now.getMonth()]);

  const savePatterns = async (patterns) => {
    const y = now.getFullYear();
    const m = now.getMonth() + 1;
    const ok = await saveSchedulePatterns(session.id, y, m, patterns);
    if (ok) {
      const updated = await fetchSchedulePatterns(session.id, y, m);
      setSchedulePatterns(updated);
      if (updated.length > 0 && !updated.some((p) => p.patternNo === activePatternNo)) {
        setActivePatternNo(updated[0].patternNo);
      }
      show('規定勤怠時間を保存しました', 'success');
    } else {
      show('規定勤怠時間の保存に失敗しました', 'warn');
    }
  };

  const loadSessionAndData = useCallback(async () => {
    if (!CLOUD_ENABLED) {
      setLoaded(true);
      setCloudStatus('local');
      show('Supabaseの環境変数が未設定のため、クラウド機能は無効です', 'warn');
      return;
    }
    try {
      const { data: authData } = await supabase.auth.getSession();
      const authUser = authData?.session?.user;
      if (!authUser) {
        setSession(null);
        setData(EMPTY_DATA);
        setLoaded(true);
        setCloudStatus('cloud');
        return;
      }
      // 2段階認証を設定している人は、コードを入れるまでデータを読み込まない
      if (await needsMfaChallenge()) {
        setMfaPending(true);
        setSession(null);
        setData(EMPTY_DATA);
        setLoaded(true);
        setCloudStatus('cloud');
        return;
      }
      setMfaPending(false);

      // 読み取りは employees_visible に統一している（基の表は個人情報の列を
      // 返さない）。自分の行なので、ここでは全項目がそのまま返る。
      const { data: empRow, error: empErr } = await supabase
        .from('employees_visible')
        .select('*')
        .eq('id', authUser.id)
        .single();
      if (empErr || !empRow) {
        // employeesテーブルに行が無い＝プロビジョニング未完了のアカウント
        await supabase.auth.signOut();
        setSession(null);
        setData(EMPTY_DATA);
        setLoaded(true);
        setCloudStatus('cloud');
        return;
      }
      if (empRow.resignation_date && empRow.resignation_date <= todayKey()) {
        // 退職日を過ぎているアカウントはログインさせない
        await supabase.auth.signOut();
        setSession(null);
        setData(EMPTY_DATA);
        setLoaded(true);
        setCloudStatus('cloud');
        show('退職日を過ぎているため、このアカウントではログインできません', 'warn');
        return;
      }
      setSession(rowToAccount(empRow));
      // 管理者がログインしたら、退職日を過ぎたスタッフのログインを止める。
      // 将来の日付で登録した分を、その日が来たら確実に止めるため。
      if (empRow.role === 'admin' || empRow.role === 'master_admin') {
        syncResignedAuth();
      }
      const fresh = await fetchAllData();
      setData(fresh);
      setLoaded(true);
      setCloudStatus('cloud');
    } catch (e) {
      console.error('データ読み込みに失敗しました', e);
      setLoaded(true);
      setCloudStatus('error');
      show('クラウドからの読み込みに失敗しました', 'warn');
    }
  }, []);

  // メールのリンクから戻ってきたときの処理。起動時に一度だけ見る。
  //
  // ① リンクが期限切れ・使用済みのとき、Supabase は #error=... を付けて
  //    戻してくるが、以前はこれを拾っておらず、理由の分からないまま
  //    ただのログイン画面が出ていた。画面に理由を出す。
  // ② 再設定モードへの切り替えを onAuthStateChange の通知だけに頼ると、
  //    画面の準備が整う前に通知が飛んだ場合に取りこぼす。
  //    URL を直接見ても判断するようにして、二重に拾う。
  useEffect(() => {
    if (typeof window === 'undefined') return;
    // supabase-js に消される前に控えておいたURLを使う（supabaseClient.ts 参照）
    const url = new URL(INITIAL_URL || window.location.href);
    const hash = new URLSearchParams(url.hash.replace(/^#/, ''));
    const query = url.searchParams;
    const pick = (key) => hash.get(key) || query.get(key);
    const errorCode = pick('error_code');
    const errorText = pick('error_description');
    if (errorCode || errorText) {
      const joined = `${errorCode || ''} ${errorText || ''}`;
      // 3秒で消えるトーストではなく、ログイン画面に残る案内として出す。
      // 再設定に失敗したことは、読み飛ばされては困るため。
      setLinkError(
        /expired|invalid/i.test(joined)
          ? 'このリンクは期限切れか、すでに使用済みです。お手数ですが、もう一度「パスワードをお忘れですか？」からやり直してください。'
          : `リンクの確認に失敗しました（${errorText || errorCode}）。総務担当へご連絡ください。`
      );
      // URL に残したままだと再読み込みのたびに同じ表示が出るため消す
      window.history.replaceState(null, '', window.location.pathname);
      return;
    }
    if (pick('type') === 'recovery') {
      setPasswordRecoveryMode(true);
    }
    // 起動時の1回だけ。show と setPasswordRecoveryMode は初回のもので足りる
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    loadSessionAndData();
    if (!CLOUD_ENABLED) return;
    const { data: sub } = supabase.auth.onAuthStateChange((event) => {
      if (event === 'SIGNED_OUT') {
        setSession(null);
        setData(EMPTY_DATA);
      }
      if (event === 'PASSWORD_RECOVERY') {
        setPasswordRecoveryMode(true);
      }
    });
    return () => sub?.subscription?.unsubscribe();
  }, [loadSessionAndData]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const media = window.matchMedia('(min-width: 1024px)');
    const syncViewMode = (event) => setViewMode(event.matches ? 'desktop' : 'mobile');
    setViewMode(media.matches ? 'desktop' : 'mobile');
    media.addEventListener?.('change', syncViewMode);
    return () => media.removeEventListener?.('change', syncViewMode);
  }, []);

  // 個々のミューテーションの後、DBの最新状態を再取得してUIへ反映する。
  // （旧app_state方式のように巨大JSONを毎回書き戻すのではなく、
  //   テーブル単位の差分更新＋再読み込みに変更）
  const refreshData = async (opts = {}) => {
    if (opts.showIndicator) setCloudStatus('connecting');
    try {
      const fresh = await fetchAllData();
      setData(fresh);
      setCloudStatus('cloud');
    } catch (e) {
      console.error('再読み込みに失敗しました', e);
      setCloudStatus('error');
    }
  };

  // 管理者への通知（アプリ内通知＋実メール、メールはResend設定済みの場合のみ実際に届く）
  // 管理者への通知。メールは個人情報の変更申請と年末調整のときだけ送る
  // （それ以外はアプリ内の通知とベルのお知らせでご確認いただく）
  const notifyAdmin = async (subject, body, relatedId, options = {}) => {
    await notify(subject, body, relatedId, null, 'admin');
    if (!options.email) return;
    const addresses = resolveAdminNotifyAddresses(data);
    if (addresses.length === 0) {
      console.warn('通知メールの送信先が見つかりませんでした');
      return;
    }
    for (const address of addresses) {
      await sendEmailBestEffort(address, subject, body);
    }
  };

  // 特定スタッフへの通知（アプリ内通知＋実メール）
  // mailLines を渡すと、宛名と署名を付けたメール本文を組み立てて送る
  const notifyEmployeeUser = async (targetEmployeeId, subject, body, relatedId, mailLines) => {
    await notify(subject, body, relatedId, targetEmployeeId, 'employee');
    const emp = data.accounts.find((a) => a.id === targetEmployeeId);
    if (!emp?.contactEmail) return;
    const text = mailLines ? buildStaffMailText(emp.name, mailLines) : body;
    await sendEmailBestEffort(emp.contactEmail, subject, text);
  };

  // 特定スタッフへの通知（アプリ内のお知らせのみ。メールは送らない）
  // 月次勤怠・交通費・個人情報変更の結果は、件数が多くなるためメールを送らない
  const notifyEmployeeInApp = async (targetEmployeeId, subject, body, relatedId) => {
    await notify(subject, body, relatedId, targetEmployeeId, 'employee');
  };

  const handleLogin = async (username, password) => {
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: usernameToEmail(username),
        password,
      });
      if (error) {
        // 失敗を記録する（管理画面の監査ログで確認できる）。
        // パスワードは送らない。記録に失敗してもログイン画面の動きは変えない。
        supabase.functions
          .invoke('record-login-attempt', {
            body: { username, reason: 'ユーザー名またはパスワードが違います' },
          })
          .catch(() => undefined);
        show('ユーザー名またはパスワードが違います', 'warn');
        return false;
      }
      // 2段階認証を設定している場合、ここではまだ aal1。
      // コードを入れて aal2 になるまでデータを読み込まない。
      if (await needsMfaChallenge()) {
        setMfaPending(true);
        return 'mfa';
      }
      await loadSessionAndData();
      show('おかえりなさい', 'success');
      return true;
    } catch (e) {
      show('ログインに失敗しました', 'warn');
      return false;
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setData(EMPTY_DATA);
  };

  const handleAddAccount = async (payload) => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const accessToken = sessionData?.session?.access_token;
      const { data: fnData, error } = await supabase.functions.invoke('create-employee', {
        body: {
          username: payload.username,
          password: payload.password,
          name: payload.name,
          furigana: payload.furigana,
          hireDate: payload.hireDate,
          role: payload.role,
          adminPermissions: payload.adminPermissions,
          contactEmail: payload.contactEmail,
        },
        headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined,
      });
      if (error || fnData?.error) {
        let detail = fnData?.error;
        if (!detail && error?.context) {
          try {
            const body = await error.context.json();
            detail = body?.error || body?.message;
          } catch (_) {
            try { detail = await error.context.text(); } catch (__) { /* noop */ }
          }
        }
        console.error('アカウント作成エラー詳細:', detail || error);
        show(detail || 'アカウント作成に失敗しました', 'warn');
        return false;
      }
      // 初回ログイン時のパスワード変更と、個人情報入力の案内を有効にする
      const newId = fnData?.id || null;
      if (newId) {
        await supabase
          .from('employees')
          .update({
            must_change_password: true,
            // 登録情報（住所・口座など）の入力を求めるかどうか。
            // 既定は従来どおり求める。作成画面で外すと、初回ログインでは
            // パスワードの変更だけになる（既存スタッフの登録などで使う）。
            profile_setup_completed: payload.requireProfileSetup === false,
            invited_at: new Date().toISOString(),
          })
          .eq('id', newId);
      }

      // ログイン案内メールを送る（SMTP未設定の場合は届かないが、作成自体は成功扱い）
      // CSVでの一括登録では送らない
      if (!payload.skipInvite) {
        const mail = buildInviteMail({
          name: payload.name,
          email: payload.username,
          tempPassword: payload.password,
          requireProfileSetup: payload.requireProfileSetup !== false,
        });
        await sendEmailBestEffort(payload.username, mail.subject, mail.text);
      }

      await refreshData();
      await logAudit(session, 'スタッフアカウントを作成', `username: ${payload.username}`, newId, payload.name);
      if (!payload.skipInvite) {
        show(`${payload.name}さんのアカウントを作成し、ログイン案内を送信しました`, 'success');
      }
      return true;
    } catch (e) {
      console.error('アカウント作成エラー:', e);
      show('アカウント作成に失敗しました', 'warn');
      return false;
    }
  };

  const handleDeleteAccount = async (account) => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const accessToken = sessionData?.session?.access_token;
      const { data: fnData, error } = await supabase.functions.invoke('delete-employee', {
        body: { employeeId: account.id },
        headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined,
      });
      if (error || fnData?.error) {
        show(fnData?.error || '削除に失敗しました', 'warn');
        return false;
      }
      await refreshData();
      await logAudit(session, 'スタッフアカウントを削除', `username: ${account.username}`, null, account.name);
      show(`${account.name}さんのアカウントを削除しました`, 'success');
      return true;
    } catch (e) {
      show('削除に失敗しました', 'warn');
      return false;
    }
  };

  const handleResetPassword = async (account, newPassword) => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const accessToken = sessionData?.session?.access_token;
      const { data: fnData, error } = await supabase.functions.invoke('reset-password', {
        body: { employeeId: account.id, newPassword },
        headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined,
      });
      if (error || fnData?.error) {
        show(fnData?.error || 'パスワードのリセットに失敗しました', 'warn');
        return false;
      }
      // リセット後は本人に変更してもらう
      await supabase.from('employees').update({ must_change_password: true }).eq('id', account.id);
      await refreshData();
      await logAudit(session, 'パスワードをリセット', `対象: ${account.username}`, account.id, account.name);
      show(`${account.name}さんのパスワードをリセットしました`, 'success');
      return true;
    } catch (e) {
      show('パスワードのリセットに失敗しました', 'warn');
      return false;
    }
  };

  const updateAdminAccess = async (targetEmployeeId, patch) => {
    const ok = await updateEmployeeProfile(targetEmployeeId, patch);
    if (ok) await logAudit(session, '管理者権限を変更', JSON.stringify(patch), targetEmployeeId);
    return ok;
  };

  // マイナンバーは別テーブル・マスター管理者のみアクセス可。
  // 一覧に含めず、開いたときだけ都度取得する（不要な露出を減らすため）。
  const fetchMyNumber = async (targetEmployeeId) => {
    const res = await callMyNumberFunction({ action: 'read', employeeId: targetEmployeeId });
    if (res.error) {
      show(res.error, 'warn');
      return null;
    }
    return { number: res.number || '', purposes: res.purposes || [] };
  };

  // 誰の番号が保存されているかの一覧（番号そのものは返らない）
  const listMyNumbers = async () => {
    const res = await callMyNumberFunction({ action: 'list' });
    if (res.error) {
      show(res.error, 'warn');
      return null;
    }
    return res.items || [];
  };

  // 保存期間を過ぎたマイナンバーを廃棄する（番号法の廃棄義務への対応）
  const deleteMyNumber = async (targetEmployeeId) => {
    const res = await callMyNumberFunction({ action: 'delete', employeeId: targetEmployeeId });
    if (res.error) {
      show(res.error, 'warn');
      return false;
    }
    return true;
  };

  const saveMyNumber = async (targetEmployeeId, { number, purposes }) => {
    const res = await callMyNumberFunction({
      action: 'save', employeeId: targetEmployeeId, number, purposes,
    });
    if (res.error) {
      show(res.error, 'warn');
      return false;
    }
    show('マイナンバーを保存しました', 'success');
    return true;
  };

  // ログインID（メールアドレス）を変更する（マスター管理者のみ）
  const handleChangeLoginEmail = async (account, newEmail, options = {}) => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const accessToken = sessionData?.session?.access_token;
      const { data: fnData, error } = await supabase.functions.invoke('update-employee-email', {
        body: {
          employeeId: account.id,
          newEmail,
          updateContactEmail: !!options.updateContactEmail,
        },
        headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined,
      });
      if (error || fnData?.error) {
        let detail = fnData?.error;
        if (!detail && error?.context) {
          try {
            const body = await error.context.json();
            detail = body?.error || body?.message;
          } catch (_) {
            try { detail = await error.context.text(); } catch (__) { /* noop */ }
          }
        }
        show(detail || 'ログインIDの変更に失敗しました', 'warn');
        return false;
      }
      if (options.notify) {
        const subject = '【Brown Work】ログインIDの変更について';
        const text = [
          `${account.name} 様`,
          '',
          'お疲れさまです。',
          '勤怠管理システム「Brown Work」のログインIDを下記のとおり変更しました。',
          '',
          '────────────────────',
          `ログインURL： ${APP_LOGIN_URL}`,
          `新しいログインID： ${newEmail}`,
          '────────────────────',
          '',
          'パスワードはこれまでどおりです。',
          'ご不明な点がありましたら、担当者までお問い合わせください。',
          '',
          '株式会社Brown',
        ].join('\n');
        await sendEmailBestEffort(newEmail, subject, text);
      }
      await refreshData();
      await logAudit(session, 'ログインIDを変更', `${account.username} → ${newEmail}`, account.id, account.name);
      show('ログインIDを変更しました', 'success');
      return true;
    } catch (e) {
      console.error('ログインIDの変更に失敗しました', e);
      show('ログインIDの変更に失敗しました', 'warn');
      return false;
    }
  };

  // グループごとの入力フォーマットを保存する（マスター管理者のみ）
  const saveGroupFormats = async (map) => {
    const value = JSON.stringify(map || {});
    const { error } = await supabase.from('app_settings').upsert(
      {
        key: SETTING_GROUP_FORMATS,
        value,
        updated_by: session.id,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'key' }
    );
    if (error) {
      console.error('フォーマット設定の保存に失敗しました', error);
      show('フォーマット設定の保存に失敗しました', 'warn');
      return false;
    }
    await logAudit(session, 'グループごとの入力フォーマットを変更', Object.keys(map || {}).join('、') || '（なし）');
    await refreshData();
    show('フォーマット設定を保存しました');
    return true;
  };

  // ZTV業務のインセンティブの単価を保存する（マスター管理者のみ。
  // app_settings の書き込みは 27番のポリシーでマスター管理者に限られている）
  const saveZtvRates = async (map) => {
    const { error } = await supabase.from('app_settings').upsert(
      {
        key: SETTING_ZTV_RATES,
        value: JSON.stringify(map || {}),
        updated_by: session.id,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'key' }
    );
    if (error) {
      console.error('ZTVインセンティブの単価の保存に失敗しました', error);
      show('単価の保存に失敗しました', 'warn');
      return false;
    }
    const before = parseZtvRates(data.settings);
    const changed = PRODUCT_ITEMS
      .filter((it) => Number(before[it.key]) !== Number(map[it.key]))
      .map((it) => `${it.label}：${before[it.key]} → ${map[it.key]}`);
    await logAudit(session, 'ZTVインセンティブの単価を変更', changed.join(' / ') || '（変更なし）');
    await refreshData();
    show('単価を保存しました');
    return true;
  };

  // スタッフが実績を入力できる期限（翌月の何日まで）を保存する（マスター管理者のみ）
  //   group が null … 全業務に共通の既定（app_settings）
  //   group が業務名 … その業務だけの設定（group_formats）
  // 値の意味：'' は「既定に従う」（業務ごとの設定のみ）、'0' は「締切を設けない」
  const savePerfDeadlineDay = async (value, group = null) => {
    const label = (v) => (v === '' ? '既定に従う' : v === '0' ? '締切なし' : `翌月${v}日まで`);
    const normalized = value === '' ? '' : String(normalizePerfDeadlineDay(value) ?? 0);

    if (group) {
      const saved = parseGroupFormats(data.settings);
      const next = { ...saved, [group]: { ...(saved[group] || {}) } };
      if (normalized === '') delete next[group].perfDeadline;
      else next[group].perfDeadline = Number(normalized);
      const { error } = await supabase.from('app_settings').upsert(
        {
          key: SETTING_GROUP_FORMATS,
          value: JSON.stringify(next),
          updated_by: session.id,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'key' }
      );
      if (error) {
        console.error('業務ごとの入力期限の保存に失敗しました', error);
        show('入力期限の保存に失敗しました', 'warn');
        return false;
      }
      await logAudit(session, '実績の入力期限を変更', `${group}：${label(normalized)}`);
      await refreshData();
      show(`「${group}」の入力期限を${label(normalized)}に設定しました`);
      return true;
    }

    const day = normalized === '' ? '0' : normalized;
    const { error } = await supabase.from('app_settings').upsert(
      {
        key: SETTING_PERF_DEADLINE_DAY,
        value: day,
        updated_by: session.id,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'key' }
    );
    if (error) {
      console.error('実績の入力期限の保存に失敗しました', error);
      show('入力期限の保存に失敗しました', 'warn');
      return false;
    }
    await logAudit(session, '実績の入力期限を変更（既定）', label(day));
    await refreshData();
    show(day === '0' ? '締切を設けない設定にしました（既定）' : `既定の入力期限を翌月${day}日に設定しました`);
    return true;
  };

  // ---- シフト連携 ----
  // スプレッドシート上の氏名とスタッフを結びつける
  const saveShiftNameAlias = async (sheetName, targetEmployeeId) => {
    const { error } = await supabase.from('shift_name_aliases').upsert(
      { sheet_name: sheetName, employee_id: targetEmployeeId, created_by: session.id },
      { onConflict: 'sheet_name' }
    );
    if (error) {
      console.error('氏名の対応表の保存に失敗しました', error);
      show('氏名の対応表の保存に失敗しました', 'warn');
      return false;
    }
    const name = employeeAccounts.find((a) => a.id === targetEmployeeId)?.name || '';
    await logAudit(session, 'シフトの氏名対応を登録', `${sheetName} → ${name}`, targetEmployeeId, name);
    await refreshData();
    show(`「${sheetName}」を ${name} さんに結びつけました。次の取り込みから反映されます。`);
    return true;
  };

  const deleteShiftNameAlias = async (sheetName) => {
    const { error } = await supabase.from('shift_name_aliases').delete().eq('sheet_name', sheetName);
    if (error) {
      console.error('氏名の対応表の削除に失敗しました', error);
      show('氏名の対応表の削除に失敗しました', 'warn');
      return;
    }
    await refreshData();
    show('対応を解除しました');
  };

  // シフトの公開をスタッフへ知らせる
  const announceShift = async (targetMonth, targetIds, changesByEmployee) => {
    if (!targetIds || targetIds.length === 0) return false;
    const label = monthKeyLabel(targetMonth);
    for (const id of targetIds) {
      const changes = (changesByEmployee && changesByEmployee[id]) || [];
      const lines = changes.slice(0, 10).map((c) => {
        const before = c.beforeKind == null ? '未定'
          : c.beforeKind === 'work' ? (c.beforePlace || '出勤')
          : c.beforeKind === 'paid' ? '有給' : '休み';
        const after = c.afterKind == null ? '未定'
          : c.afterKind === 'work' ? (c.afterPlace || '出勤')
          : c.afterKind === 'paid' ? '有給' : '休み';
        return `${dateLabel(c.date)}　${before} → ${after}`;
      });
      const body = changes.length > 0
        ? `${label}のシフトが変更されました。\n${lines.join('\n')}${changes.length > 10 ? `\nほか${changes.length - 10}件` : ''}\n「勤怠」→「シフト」からご確認ください。`
        : `${label}のシフトが公開されました。「勤怠」→「シフト」からご確認ください。`;
      // eslint-disable-next-line no-await-in-loop
      await notifyEmployeeInApp(id, `【シフト】${label}${changes.length > 0 ? 'の変更' : 'のシフトを公開しました'}`, body);
    }
    await logAudit(session, 'シフトの公開を通知', `${label}・${targetIds.length}名`);
    await refreshData();
    show(`${targetIds.length}名にお知らせを送りました`);
    return true;
  };

  // ---- 賞与明細 ----
  const saveBonus = async (payload) => {
    // 公開済みの明細は上書きしない。給与明細と同じ扱いで、
    // 直すときは先に公開を取り消す（マスター管理者のみ）
    const already = (data.bonusRecords || []).find(
      (b) => b.employeeId === payload.employeeId && b.year === payload.year && b.seq === payload.seq
    );
    if (already && already.status === 'published') {
      show('この賞与明細は公開済みです。直すには先に公開を取り消してください', 'warn');
      return false;
    }
    const changes = [];
    if (already) {
      if (Number(already.totalAmount) !== Number(payload.totalAmount)) {
        changes.push(`差引支給額：${formatYen(already.totalAmount)} → ${formatYen(payload.totalAmount)}`);
      }
      changes.push(...diffAmountItems(already.paymentItems, payload.paymentItems, '支給'));
      changes.push(...diffAmountItems(already.deductionItems, payload.deductionItems, '控除'));
      if ((already.title || '') !== (payload.title || '')) changes.push(`名称：「${already.title}」→「${payload.title}」`);
      if ((already.paymentDate || '') !== (payload.paymentDate || '')) changes.push(`支給日：${already.paymentDate || '未設定'} → ${payload.paymentDate || '未設定'}`);
      if ((already.notes || '') !== (payload.notes || '')) changes.push('備考を変更');
    }
    const entry = makeHistoryEntry(session, already ? '金額を変更' : '明細を作成', changes);
    const nextHistory = already && changes.length === 0
      ? (already.editHistory || [])
      : appendHistory(already?.editHistory, entry);

    const { error } = await supabase.from('bonus_records').upsert(
      {
        employee_id: payload.employeeId,
        year: payload.year,
        seq: payload.seq,
        title: payload.title || null,
        payment_date: payload.paymentDate,
        payment_items: payload.paymentItems,
        deduction_items: payload.deductionItems,
        total_amount: payload.totalAmount,
        notes: payload.notes || null,
        updated_at: new Date().toISOString(),
        edit_history: nextHistory,
      },
      { onConflict: 'employee_id,year,seq' }
    );
    if (error) {
      console.error('賞与明細の保存に失敗しました', error);
      show('賞与明細の保存に失敗しました', 'warn');
      return false;
    }
    await refreshData();
    const bonusLabel = payload.title || bonusDefaultTitle(payload.year, payload.seq);
    await logAudit(
      session,
      already ? '賞与明細を変更' : '賞与明細を作成',
      `${bonusLabel}${changes.length ? `／${changes.join('／')}` : ''}`,
      payload.employeeId
    );
    show(
      changes.length > 0
        ? `賞与明細を保存しました（${changes.length}件の変更を履歴に記録しました）`
        : '賞与明細を保存しました'
    );
    return true;
  };

  const publishBonus = async (id) => {
    const target = (data.bonusRecords || []).find((b) => b.id === id);
    const { error } = await supabase
      .from('bonus_records')
      .update({
        status: 'published',
        published_at: new Date().toISOString(),
        edit_history: appendHistory(target?.editHistory, makeHistoryEntry(session, '公開')),
      })
      .eq('id', id);
    if (error) {
      console.error('賞与明細の公開に失敗しました', error);
      show('賞与明細の公開に失敗しました', 'warn');
      return false;
    }
    const record = (data.bonusRecords || []).find((b) => b.id === id);
    if (record) {
      const label = record.title || bonusDefaultTitle(record.year, record.seq);
      await notifyEmployeeUser(
        record.employeeId,
        `【賞与明細】${label}`,
        `${label}の明細が公開されました。「給与」タブからご確認ください。`,
        null,
        [`${label}の明細を公開しました。`, '下記よりご確認ください。']
      );
      await logAudit(session, '賞与明細を公開', label, record.employeeId, record.employeeName);
    }
    await refreshData();
    show('賞与明細を公開しました');
    return true;
  };

  // 公開済みの賞与明細を下書きに戻す（マスター管理者のみ）。
  // 給与明細の unpublishPayroll と同じ扱い
  const unpublishBonus = async (id) => {
    if (session.role !== 'master_admin') {
      show('公開を取り消せるのはマスター管理者のみです', 'warn');
      return false;
    }
    const record = (data.bonusRecords || []).find((b) => b.id === id);
    const { error } = await supabase
      .from('bonus_records')
      .update({
        status: 'draft',
        published_at: null,
        edit_history: appendHistory(record?.editHistory, makeHistoryEntry(session, '公開を取り消し')),
      })
      .eq('id', id);
    if (error) {
      console.error('公開の取り消しに失敗しました', error);
      show(`公開の取り消しに失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    if (record) {
      const label = record.title || bonusDefaultTitle(record.year, record.seq);
      await notifyEmployeeInApp(
        record.employeeId,
        `【賞与明細・一時非公開】${label}`,
        `${label}の明細を、内容の確認のため一時的に非公開にしました。`
          + '\n確認が終わりしだい、あらためて公開しお知らせします。',
        null
      );
      await logAudit(session, '賞与明細の公開を取り消し', label, record.employeeId, record.employeeName);
    }
    await refreshData();
    show('公開を取り消しました。内容を直したうえで再度公開してください', 'warn');
    return true;
  };

  const deleteBonus = async (record) => {
    const label = record.title || bonusDefaultTitle(record.year, record.seq);
    if (!window.confirm(`${record.employeeName}さんの「${label}」を削除します。よろしいですか。`)) return;
    const { error } = await supabase.from('bonus_records').delete().eq('id', record.id);
    if (error) {
      console.error('賞与明細の削除に失敗しました', error);
      show('賞与明細の削除に失敗しました', 'warn');
      return;
    }
    await refreshData();
    show('賞与明細を削除しました');
  };

  // 管理者宛の通知メールの送信先を保存する（マスター管理者のみ）
  const saveAdminNotifyEmail = async (value) => {
    const trimmed = String(value || '').trim();
    const { error } = await supabase.from('app_settings').upsert(
      {
        key: SETTING_ADMIN_NOTIFY_EMAIL,
        value: trimmed,
        updated_by: session.id,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'key' }
    );
    if (error) {
      console.error('通知先の保存に失敗しました', error);
      show('通知先の保存に失敗しました', 'warn');
      return false;
    }
    await logAudit(session, '通知メールの送信先を変更', trimmed || '（未設定）');
    await refreshData();
    show('通知メールの送信先を保存しました', 'success');
    return true;
  };

  // 初回ログイン時に、ご本人がご自身のマイナンバーを登録する。
  // 本人による登録のみ許可（他人の番号は登録できない）。
  // 登録後の閲覧はマスター管理者のみ。
  const saveOwnMyNumber = async (number) => {
    const res = await callMyNumberFunction({
      action: 'save', employeeId: session.id, number, purposes: MY_NUMBER_PURPOSES,
    });
    if (res.error) {
      console.error('マイナンバーの保存に失敗しました', res.error);
      return false;
    }
    return true;
  };

  const today = todayKey();
  const employeeId = session?.id;
  const employeeRecords = (employeeId && data.records[employeeId]) || {};
  const todayRecord = employeeRecords[today];

  const activePattern = schedulePatterns.find((p) => p.patternNo === activePatternNo) || schedulePatterns[0] || null;

  // 交通費精算：前月分を毎月1日までに申請できているか（未提出・却下のままなら出勤時にリマインド）
  const commuteClaimTargetMonthKey = prevMonthKey(now);
  const hasSubmittedCommuteClaim = (data.commuteExpenseClaims || []).some(
    (c) => c.employeeId === employeeId && c.targetMonth === commuteClaimTargetMonthKey
      && c.status !== 'rejected' && c.status !== 'draft'
  );
  // 交通費申請の対象でない方には、打刻時のリマインドも出さない（77番）
  const needsCommuteClaimReminder = !hasSubmittedCommuteClaim
    && requiresRequest('commute', session, data.settings);

  const handleClockIn = async (confirm = {}) => {
    const loc = await geo.capture();
    const actualNow = new Date();
    const clockInDate = confirm.clockInTime || actualNow;
    const { error } = await supabase.from('attendance_records').upsert(
      {
        employee_id: employeeId,
        date: today,
        clock_in: clockInDate.toISOString(),
        clock_in_actual: actualNow.toISOString(),
        clock_in_status: confirm.status || null,
        clock_in_note: confirm.note || null,
        clock_in_approval: NEEDS_APPROVAL_STATUSES.includes(confirm.status) ? 'pending' : null,
        clock_out: null,
        break_periods: [],
        break_started_at: null,
        scheduled_start: activePattern?.startTime || SCHEDULED_START,
        scheduled_end: activePattern?.endTime || SCHEDULED_END,
        clock_in_location: loc,
        clock_out_location: null,
        off_shift: confirm.offShift ? true : null,
        off_shift_note: confirm.offShift ? (confirm.offShiftNote || '') : null,
      },
      { onConflict: 'employee_id,date' }
    );
    if (error) {
      show('出勤の記録に失敗しました', 'warn');
      return;
    }
    await refreshData();
    if (confirm.offShift) {
      await notifyAdmin(
        `【シフト外の出勤】${session.name}さん`,
        `${session.name}さんが、シフト上は休みの日に出勤しました（${confirm.offShiftNote ? `理由：${confirm.offShiftNote}` : '理由の記入なし'}）。`,
        today
      );
    }
    const needsApproval = NEEDS_APPROVAL_STATUSES.includes(confirm.status);
    if (needsApproval) {
      const reasonLabel = CLOCK_IN_STATUS_LABEL[confirm.status] || confirm.status;
      await notifyAdmin(
        `【出勤確認】${session.name} - ${reasonLabel}の承認待ち`,
        `${session.name}さんが「${reasonLabel}」として出勤を記録しました（${confirm.note ? `メモ：${confirm.note}` : 'メモなし'}）。内容をご確認のうえ、勤怠一覧上部の「承認待ちの出勤」から承認してください。`,
        today
      );
    }
    show(
      needsApproval
        ? '出勤を記録しました（管理者の承認待ちです）'
        : (loc ? '出勤を記録しました（位置情報を取得）' : '出勤を記録しました（位置情報の取得に失敗）'),
      needsApproval ? 'warn' : (loc ? 'success' : 'warn')
    );
  };

  const handleClockOut = async (confirm = {}) => {
    const loc = await geo.capture();
    const existing = employeeRecords[today] || { breakPeriods: [] };
    const actualNow = new Date();
    const clockOutDate = confirm.clockOutTime || actualNow;
    const nowIso = actualNow.toISOString();
    let breakPeriods = existing.breakPeriods || [];
    if (existing.breakStartedAt) {
      breakPeriods = [...breakPeriods, { start: existing.breakStartedAt, end: nowIso }];
    }
    const { error } = await supabase.from('attendance_records').upsert(
      {
        employee_id: employeeId,
        date: today,
        break_periods: breakPeriods,
        break_started_at: null,
        clock_out: clockOutDate.toISOString(),
        clock_out_actual: nowIso,
        clock_out_status: confirm.status || null,
        clock_out_note: confirm.note || null,
        clock_out_approval: CLOCK_OUT_NEEDS_APPROVAL_STATUSES.includes(confirm.status) ? 'pending' : null,
        clock_out_location: loc,
      },
      { onConflict: 'employee_id,date' }
    );
    if (error) {
      show('退勤の記録に失敗しました', 'warn');
      return;
    }
    await refreshData();
    const needsApproval = CLOCK_OUT_NEEDS_APPROVAL_STATUSES.includes(confirm.status);
    if (needsApproval) {
      const reasonLabel = CLOCK_OUT_STATUS_LABEL[confirm.status] || confirm.status;
      await notifyAdmin(
        `【退勤確認】${session.name} - ${reasonLabel}の承認待ち`,
        `${session.name}さんが「${reasonLabel}」として退勤を記録しました（${confirm.note ? `メモ：${confirm.note}` : 'メモなし'}）。内容をご確認のうえ承認してください。`,
        today
      );
    }
    show(
      needsApproval ? '退勤を記録しました（管理者の承認待ちです）' : (loc ? '退勤を記録しました（位置情報を取得）' : '退勤を記録しました（位置情報の取得に失敗）'),
      needsApproval ? 'warn' : (loc ? 'success' : 'warn')
    );
  };

  const handleBreakStart = async () => {
    const existing = employeeRecords[today];
    if (!existing?.clockIn || existing.clockOut || existing.breakStartedAt) return;
    const { error } = await supabase.from('attendance_records').upsert(
      {
        employee_id: employeeId,
        date: today,
        break_periods: existing.breakPeriods || [],
        break_started_at: new Date().toISOString(),
      },
      { onConflict: 'employee_id,date' }
    );
    if (error) {
      show('休憩開始の記録に失敗しました', 'warn');
      return;
    }
    await refreshData();
    show('休憩を開始しました', 'success');
  };

  const handleBreakEnd = async () => {
    const existing = employeeRecords[today];
    if (!existing?.breakStartedAt || existing.clockOut) return;
    const end = new Date().toISOString();
    const { error } = await supabase.from('attendance_records').upsert(
      {
        employee_id: employeeId,
        date: today,
        break_periods: [...(existing.breakPeriods || []), { start: existing.breakStartedAt, end }],
        break_started_at: null,
      },
      { onConflict: 'employee_id,date' }
    );
    if (error) {
      show('休憩終了の記録に失敗しました', 'warn');
      return;
    }
    await refreshData();
    show('休憩を終了しました', 'success');
  };

  const submitCorrection = async (payload) => {
    // 同じ日の未処理の申請があれば、新しく作らずその申請を書き換える。
    // 送信ボタンを連打したときに同じ内容の申請が並ぶのを防ぐため
    // （交通費精算の申請と同じ扱い）
    const pending = (data.corrections || []).find(
      (c) => c.employeeId === employeeId && c.date === payload.date && c.status === 'pending'
    );
    const row = {
      employee_id: employeeId,
      date: payload.date,
      original: employeeRecords[payload.date] || null,
      requested: payload,
      reason: payload.reason,
      status: 'pending',
    };
    const { data: saved, error } = pending
      ? await supabase.from('corrections').update(row).eq('id', pending.id).select().single()
      : await supabase.from('corrections').insert(row).select().single();
    if (error) {
      console.error('修正申請の送信に失敗しました', error);
      show('修正申請の送信に失敗しました', 'warn');
      return false;
    }
    // 書き換えで中身が変わっていないときは、管理者に同じ通知を重ねて送らない
    const sameAsBefore = pending && JSON.stringify(pending.requested || {}) === JSON.stringify(payload);
    if (!sameAsBefore) {
      await notifyAdmin(
        `【勤怠修正申請${pending ? '・修正' : ''}】${session.name} - ${dateLabel(payload.date)}`,
        `${session.name}さんより ${dateLabel(payload.date)} の勤怠修正申請が${pending ? '修正されました' : '届きました'}。内容をご確認のうえ承認してください。`,
        saved?.id
      );
    }
    await refreshData();
    setCorrectionModal(null);
    show(
      pending
        ? (sameAsBefore ? 'この日の修正申請はすでに送信済みです' : '修正申請の内容を更新しました。管理者に通知しました')
        : '修正申請を送信しました。管理者に通知しました',
      pending && sameAsBefore ? 'warn' : 'success'
    );
    return true;
  };

  // 管理者が勤怠一覧から直接、出退勤時刻を修正する（承認フローを介さず即時反映）
  const adminUpdateAttendance = async (targetEmployeeId, dateStr, patch, opts = {}) => {
    const existing = data.records[targetEmployeeId]?.[dateStr] || null;
    const toIso = (hhmmStr) => {
      if (!hhmmStr) return null;
      const [h, m] = hhmmStr.split(':').map(Number);
      return new Date(`${dateStr}T${pad(h)}:${pad(m)}:00`).toISOString();
    };
    const clockInCleared = patch.clockIn === '';
    const clockOutCleared = patch.clockOut === '';
    const { error } = await supabase.from('attendance_records').upsert(
      {
        employee_id: targetEmployeeId,
        date: dateStr,
        clock_in: patch.clockIn ? toIso(patch.clockIn) : (clockInCleared ? null : existing?.clockIn || null),
        clock_out: patch.clockOut ? toIso(patch.clockOut) : (clockOutCleared ? null : existing?.clockOut || null),
        break_periods: existing?.breakPeriods || [],
        break_started_at: existing?.breakStartedAt || null,
        break_minutes_override: patch.breakMinutes != null ? Number(patch.breakMinutes) : existing?.breakMinutesOverride ?? null,
        scheduled_start: existing?.scheduledStart || SCHEDULED_START,
        scheduled_end: existing?.scheduledEnd || SCHEDULED_END,
        clock_in_location: clockInCleared ? null : (existing?.clockInLocation || null),
        clock_out_location: clockOutCleared ? null : (existing?.clockOutLocation || null),
        clock_in_actual: clockInCleared ? null : (existing?.clockInActual || null),
        clock_in_status: clockInCleared ? null : (existing?.clockInStatus || null),
        clock_in_note: clockInCleared ? null : (existing?.clockInNote || null),
        clock_in_approval: clockInCleared
          ? null
          : ((patch.kind ? patch.kind === 'in' : true) && patch.approve != null
              ? (patch.approve === true ? (existing?.clockInApproval === 'pending' ? 'approved' : existing?.clockInApproval || null) : (existing?.clockInApproval === 'pending' ? 'rejected' : existing?.clockInApproval || null))
              : (existing?.clockInApproval || null)),
        clock_out_actual: clockOutCleared ? null : (existing?.clockOutActual || null),
        clock_out_status: clockOutCleared ? null : (existing?.clockOutStatus || null),
        clock_out_note: clockOutCleared ? null : (existing?.clockOutNote || null),
        clock_out_approval: clockOutCleared
          ? null
          : ((patch.kind ? patch.kind === 'out' : true) && patch.approve != null
              ? (patch.approve === true ? (existing?.clockOutApproval === 'pending' ? 'approved' : existing?.clockOutApproval || null) : (existing?.clockOutApproval === 'pending' ? 'rejected' : existing?.clockOutApproval || null))
              : (existing?.clockOutApproval || null)),
        clock_in_pay_deduction: clockInCleared
          ? null
          : ((patch.kind === 'in' && patch.approve != null) ? !!patch.deduction : (existing?.clockInPayDeduction ?? null)),
        clock_in_pay_deduction_note: clockInCleared
          ? null
          : ((patch.kind === 'in' && patch.approve != null) ? (patch.deductionNote || null) : (existing?.clockInPayDeductionNote || null)),
        clock_out_pay_deduction: clockOutCleared
          ? null
          : ((patch.kind === 'out' && patch.approve != null) ? !!patch.deduction : (existing?.clockOutPayDeduction ?? null)),
        clock_out_pay_deduction_note: clockOutCleared
          ? null
          : ((patch.kind === 'out' && patch.approve != null) ? (patch.deductionNote || null) : (existing?.clockOutPayDeductionNote || null)),
      },
      { onConflict: 'employee_id,date' }
    );
    if (error) {
      if (!opts.silent) show('勤怠の修正に失敗しました', 'warn');
      return false;
    }
    if (!opts.silent) {
      await refreshData();
      const target = data.accounts.find((a) => a.id === targetEmployeeId);
      await logAudit(session, '管理者が勤怠を修正', `${dateStr}（${patch.clockIn || '--'} - ${patch.clockOut || '--'}）`, targetEmployeeId, target?.name || '');
      show('勤怠を修正しました', 'success');
    }
    return true;
  };

  // 管理者が複数行をまとめて修正（1件ずつ保存し、最後にまとめて反映・通知）
  const adminUpdateAttendanceBatch = async (changes) => {
    let okCount = 0;
    for (const { employeeId: targetEmployeeId, date: dateStr, patch } of changes) {
      const ok = await adminUpdateAttendance(targetEmployeeId, dateStr, patch, { silent: true });
      if (ok) okCount++;
    }
    await refreshData();
    if (okCount > 0) {
      await logAudit(session, '管理者が勤怠をまとめて修正', `${okCount}件`);
      show(`${okCount}件の勤怠を更新しました`, 'success');
    }
    if (okCount < changes.length) {
      show(`${changes.length - okCount}件の更新に失敗しました`, 'warn');
    }
    return okCount;
  };

  // 打刻そのものを削除する（マスター管理者のみ）。
  // 休みの日に誤って打刻したときなど、その日の記録を丸ごと消すために使う。
  // 月次勤怠が確定済み、またはその月の給与明細が公開済みの場合は、
  // データベース側（67番）でも拒否される。
  const adminDeleteAttendance = async (targetEmployeeId, dateStr, { notify = false, reason = '' } = {}) => {
    if (session.role !== 'master_admin') {
      show('打刻を削除できるのはマスター管理者のみです', 'warn');
      return false;
    }
    const target = data.accounts.find((a) => a.id === targetEmployeeId);
    const targetName = target?.name || '';

    // 画面側でも先に確認して、分かりやすい案内を出す
    const confirmation = (data.monthlyConfirmations || []).find(
      (c) => c.employeeId === targetEmployeeId && c.targetMonth === dateStr.slice(0, 7) && c.status === 'confirmed'
    );
    if (confirmation) {
      show(`${monthKeyLabel(dateStr.slice(0, 7))}分の月次勤怠は確定済みのため、打刻を削除できません。先に確定を取り消してください`, 'warn');
      return false;
    }
    const [dy, dm] = dateStr.split('-').map(Number);
    const payroll = (data.payrollRecords || []).find(
      (p) => p.employeeId === targetEmployeeId && p.year === dy && p.month === dm
    );
    if (payroll && payroll.status === 'published') {
      show(`${dy}年${dm}月分の給与明細は公開済みのため、打刻を削除できません。先に明細の公開を取り消してください`, 'warn');
      return false;
    }

    const { error } = await supabase
      .from('attendance_records')
      .delete()
      .eq('employee_id', targetEmployeeId)
      .eq('date', dateStr);
    if (error) {
      console.error('打刻の削除に失敗しました', error);
      show(`打刻の削除に失敗しました：${error.message || ''}`, 'warn');
      return false;
    }

    if (notify) {
      await notifyEmployeeInApp(
        targetEmployeeId,
        `【打刻の削除】${dateLabel(dateStr)}`,
        `${dateLabel(dateStr)} の打刻を管理者が削除しました。${reason ? `理由：${reason}` : ''}`
          + '\n心当たりがない場合は管理者にご連絡ください。',
        null
      );
    }
    await refreshData();
    await logAudit(
      session,
      '管理者が打刻を削除',
      `${dateStr}${reason ? `／理由：${reason}` : ''}${notify ? '／スタッフへ通知' : '／通知なし'}`,
      targetEmployeeId,
      targetName
    );
    show(`${dateLabel(dateStr)} の打刻を削除しました`, 'warn');
    return true;
  };

  const decideCorrection = async (id, decision) => {
    const correction = data.corrections.find((c) => c.id === id);
    if (!correction) return;
    const { error } = await supabase
      .from('corrections')
      .update({ status: decision, decided_at: new Date().toISOString() })
      .eq('id', id);
    if (error) {
      show('処理に失敗しました', 'warn');
      return;
    }
    if (decision === 'approved') {
      const req = correction.requested;
      const base = new Date(correction.date + 'T00:00:00');
      const buildIso = (hhmmStr) => {
        if (!hhmmStr) return null;
        const [h, m] = hhmmStr.split(':').map(Number);
        const d = new Date(base);
        d.setHours(h, m, 0, 0);
        return d.toISOString();
      };
      const existing = (data.records[correction.employeeId] || {})[correction.date] || {};
      await supabase.from('attendance_records').upsert(
        {
          employee_id: correction.employeeId,
          date: correction.date,
          clock_in: req.clockIn ? buildIso(req.clockIn) : existing.clockIn,
          clock_out: req.clockOut ? buildIso(req.clockOut) : existing.clockOut,
          break_minutes_override: req.breakMinutes != null ? Number(req.breakMinutes) : existing.breakMinutesOverride,
        },
        { onConflict: 'employee_id,date' }
      );
    }
    await refreshData();
    await logAudit(session, decision === 'approved' ? '勤怠修正申請を承認' : '勤怠修正申請を却下', `${dateLabel(correction.date)}分の勤怠修正申請`, correction.employeeId, correction.employeeName);
    show(decision === 'approved' ? '修正申請を承認しました' : '修正申請を却下しました', decision === 'approved' ? 'success' : 'warn');
  };

  const submitLeaveRequest = async (payload) => {
    const days = payload.halfDay ? 0.5 : daysBetweenInclusive(payload.startDate, payload.endDate);
    // まったく同じ内容の未処理の申請があれば、重ねて作らない（連打対策）
    const duplicate = (data.leaveRequests || []).find(
      (l) => l.employeeId === employeeId
        && l.status === 'pending'
        && l.type === payload.type
        && !!l.halfDay === !!payload.halfDay
        && l.startDate === payload.startDate
        && l.endDate === payload.endDate
    );
    if (duplicate) {
      setLeaveModalOpen(false);
      show('同じ内容の休暇申請がすでに送信済みです', 'warn');
      return false;
    }
    const { data: inserted, error } = await supabase
      .from('leave_requests')
      .insert({
        employee_id: employeeId,
        type: payload.type,
        half_day: !!payload.halfDay,
        start_date: payload.startDate,
        end_date: payload.endDate,
        days,
        reason: payload.reason,
        status: 'pending',
      })
      .select()
      .single();
    if (error) {
      console.error('休暇申請の送信に失敗しました', error);
      show('休暇申請の送信に失敗しました', 'warn');
      return false;
    }
    const rangeLabel = payload.startDate === payload.endDate ? dateLabel(payload.startDate) : `${dateLabel(payload.startDate)}〜${dateLabel(payload.endDate)}`;
    const typeLabel = payload.halfDay ? `${payload.type}（半休）` : payload.type;
    await notifyAdmin(
      `【休暇申請】${session.name} - ${typeLabel}（${rangeLabel}）`,
      `${session.name}さんより ${typeLabel} の休暇申請（${rangeLabel}／${days}日間）が届きました。内容をご確認のうえ承認してください。`,
      inserted?.id
    );
    await refreshData();
    setLeaveModalOpen(false);
    show('休暇申請を送信しました。管理者に通知しました', 'success');
    return true;
  };

  const decideLeaveRequest = async (id, decision) => {
    const leave = data.leaveRequests.find((l) => l.id === id);
    const { error } = await supabase
      .from('leave_requests')
      .update({ status: decision, decided_at: new Date().toISOString() })
      .eq('id', id);
    if (error) {
      show('処理に失敗しました', 'warn');
      return;
    }
    await refreshData();
    if (leave) await logAudit(session, decision === 'approved' ? '休暇申請を承認' : '休暇申請を却下', `${leave.type}（${dateLabel(leave.startDate)}〜${dateLabel(leave.endDate)}）`, leave.employeeId, leave.employeeName);
    show(decision === 'approved' ? '休暇申請を承認しました' : '休暇申請を却下しました', decision === 'approved' ? 'success' : 'warn');
  };

  const updateEmployeeProfile = async (targetEmployeeId, patch) => {
    const colMap = {
      name: 'name',
      hireDate: 'hire_date',
      resignationDate: 'resignation_date',
      furigana: 'furigana',
      role: 'role',
      adminPermissions: 'admin_permissions',
      contactEmail: 'contact_email',
      staffNumber: 'staff_number',
      postalCode: 'postal_code',
      address: 'address',
      residentAddress: 'resident_address',
      phone: 'phone',
      emergencyContactName: 'emergency_contact_name',
      emergencyContactFurigana: 'emergency_contact_furigana',
      emergencyContactRelation: 'emergency_contact_relation',
      emergencyContactPhone: 'emergency_contact_phone',
      emergencyContactAddress: 'emergency_contact_address',
      wageType: 'wage_type',
      hourlyWage: 'hourly_wage',
      monthlySalary: 'monthly_salary',
      birthDate: 'birth_date',
      staffType: 'staff_type',
      mainGroup: 'main_group',
      subGroup: 'sub_group',
      commuteAllowance: 'commute_allowance',
      deemedOvertimeHours: 'deemed_overtime_hours',
      nearestStation: 'nearest_station',
      staffNote1: 'staff_note1',
      staffNote2: 'staff_note2',
      staffNote3: 'staff_note3',
      leaveAdjustment: 'leave_adjustment',
      scheduledWeeklyDays: 'scheduled_weekly_days',
      jobTitle: 'job_title',
      gender: 'gender',
      contractStart: 'contract_start',
      contractEnd: 'contract_end',
      mustChangePassword: 'must_change_password',
      profileSetupCompleted: 'profile_setup_completed',
      resignationReasonId: 'resignation_reason_id',
      resignationNote: 'resignation_note',
      bankCode: 'bank_code',
      bankName: 'bank_name',
      branchCode: 'branch_code',
      branchName: 'branch_name',
      accountType: 'account_type',
      accountHolder: 'account_holder',
      accountNumber: 'account_number',
      standardRemunerationHealth: 'standard_remuneration_health',
      standardRemunerationPension: 'standard_remuneration_pension',
      healthInsuranceStatus: 'health_insurance_status',
      healthInsuranceNumber: 'health_insurance_number',
      healthInsuranceAcquiredDate: 'health_insurance_acquired_date',
      healthInsuranceLostDate: 'health_insurance_lost_date',
      pensionStatus: 'pension_status',
      pensionBasicNumber: 'pension_basic_number',
      pensionAcquiredDate: 'pension_acquired_date',
      pensionLostDate: 'pension_lost_date',
      employmentInsuranceStatus: 'employment_insurance_status',
      employmentInsuranceNumber: 'employment_insurance_number',
      employmentInsuranceAcquiredDate: 'employment_insurance_acquired_date',
      employmentInsuranceLostDate: 'employment_insurance_lost_date',
      spouseStatus: 'spouse_status',
      householderName: 'householder_name',
      commuteClaimMode: 'commute_claim_mode',
      shiftRequestRequirement: 'shift_request_requirement',
      performanceRequirement: 'performance_requirement',
      commuteClaimRequirement: 'commute_claim_requirement',
      householderRelation: 'householder_relation',
      spouseAnnualIncome: 'spouse_annual_income',
      spouseMonthlyIncome: 'spouse_monthly_income',
      familyMembers: 'family_members',
      residentTaxMunicipalityCode: 'resident_tax_municipality_code',
      residentTaxMunicipality: 'resident_tax_municipality',
      residentTaxCollectionMethod: 'resident_tax_collection_method',
      taxTableType: 'tax_table_type',
      isNonResident: 'is_non_resident',
      disabilityClassification: 'disability_classification',
      isWorkingStudent: 'is_working_student',
      singleParentClassification: 'single_parent_classification',
    };
    const dbPatch = {};
    Object.entries(patch).forEach(([key, value]) => {
      if (value !== undefined && colMap[key]) dbPatch[colMap[key]] = value;
    });
    // 個人情報（住所・口座・賃金など）は本人とマスター管理者にしか届かない。
    // それ以外の管理者の画面では空欄になっているため、そのまま送ると
    // 「中身を空にする更新」になってしまう。送らずに取り除く。
    // データベース側でも 71b のトリガーが拒むが、ここで落として
    // 「更新に失敗しました」と出ないようにする。
    const canEditDetail = session.role === 'master_admin' || session.id === targetEmployeeId;
    if (!canEditDetail) {
      EMPLOYEE_SENSITIVE_COLUMNS.forEach((col) => { delete dbPatch[col]; });
    }
    // 申請の対象かどうか（シフト希望・実績入力・交通費申請）はマスター管理者だけが変えられる。
    // 画面では選べないようにしてあり、データベース側でも 77番のトリガーが拒むが、
    // ここで落として「更新に失敗しました」と出ないようにする。
    const REQUIREMENT_DB_COLUMNS = [
      'shift_request_requirement', 'performance_requirement', 'commute_claim_requirement',
    ];
    REQUIREMENT_DB_COLUMNS.forEach((col) => {
      if (session.role !== 'master_admin') { delete dbPatch[col]; return; }
      // 「グループの設定に従う」は選択欄では空文字になる。列の制限に合わせて null に直す
      if (dbPatch[col] === '') dbPatch[col] = null;
    });
    if (Object.keys(dbPatch).length === 0) {
      show('変更できる項目がありませんでした', 'warn');
      return false;
    }
    const { error } = await supabase.from('employees').update(dbPatch).eq('id', targetEmployeeId);
    if (error) {
      show('スタッフ情報の更新に失敗しました', 'warn');
      return false;
    }
    await refreshData();
    // 退職日を変更したら、その場でログインの可否をそろえる
    // （退職日が今日以前なら停止、取り消したなら解除）
    if (Object.prototype.hasOwnProperty.call(patch, 'resignationDate')) {
      const result = await syncResignedAuth();
      if (result?.banned?.length) {
        show(`${result.banned.join('、')}さんのログインを停止しました`, 'success');
      } else if (result?.unbanned?.length) {
        show(`${result.unbanned.join('、')}さんのログインを再開しました`, 'success');
      }
    }
    if (session && session.id === targetEmployeeId) {
      setSession((prev) => ({ ...prev, ...patch }));
    }
    show('スタッフ情報を更新しました', 'success');
    return true;
  };
  // 過去の呼び出し名との互換用エイリアス
  const updateEmployeeDates = updateEmployeeProfile;

  const submitProfileUpdateRequest = async (changes, reason) => {
    const originalValues = {};
    PROFILE_EDITABLE_FIELDS.forEach(({ key }) => { originalValues[key] = session[key] || ''; });
    const { data: inserted, error } = await supabase
      .from('profile_update_requests')
      .insert({
        employee_id: employeeId,
        requested_changes: changes,
        original_values: originalValues,
        reason: reason || null,
        status: 'pending',
      })
      .select()
      .single();
    if (error) {
      show('変更申請の送信に失敗しました', 'warn');
      return;
    }
    const changedLabels = Object.keys(changes).map((k) => PROFILE_EDITABLE_FIELDS.find((f) => f.key === k)?.label || k).join('、');
    await notifyAdmin(
      `【個人情報変更申請】${session.name}`,
      `${session.name}さんより個人情報の変更申請（${changedLabels}）が届きました。内容をご確認のうえ承認してください。`,
      inserted?.id,
      { email: true }
    );
    await refreshData();
    show('変更を申請しました。管理者に通知しました', 'success');
  };

  const decideProfileUpdateRequest = async (id, decision, memo) => {
    const request = data.profileUpdateRequests.find((r) => r.id === id);
    if (!request) return;
    const { error } = await supabase
      .from('profile_update_requests')
      .update({ status: decision, admin_memo: memo || '', decided_at: new Date().toISOString() })
      .eq('id', id);
    if (error) {
      show('処理に失敗しました', 'warn');
      return;
    }
    if (decision === 'approved') {
      await updateEmployeeProfile(request.employeeId, request.requestedChanges);
    }
    await notifyEmployeeInApp(
      request.employeeId,
      `【個人情報変更${decision === 'approved' ? '承認' : '却下'}】`,
      `個人情報の変更申請が${decision === 'approved' ? '承認され、反映されました' : '却下されました'}。画面右上のアイコン →「登録情報の閲覧・変更」からご確認いただけます。${memo ? `管理者コメント：${memo}` : ''}`,
      id
    );
    await refreshData();
    await logAudit(session, decision === 'approved' ? '個人情報変更を承認' : '個人情報変更を却下', Object.keys(request.requestedChanges).join('、'), request.employeeId, request.employeeName);
    show(decision === 'approved' ? '変更申請を承認しました' : '変更申請を却下しました', decision === 'approved' ? 'success' : 'warn');
  };

  // 年末調整の申告を提出（対象年ごとに1件、既にあれば上書き）
  const submitYearEndAdjustment = async (payload) => {
    const { data: inserted, error } = await supabase
      .from('year_end_adjustments')
      .upsert(
        {
          employee_id: employeeId,
          year: payload.year,
          spouse_status: payload.spouseStatus,
          spouse_income: payload.spouseStatus === '有' ? Number(payload.spouseIncome) || 0 : null,
          dependents_count: Number(payload.dependentsCount) || 0,
          life_insurance_premium: Number(payload.lifeInsurancePremium) || 0,
          earthquake_insurance_premium: Number(payload.earthquakeInsurancePremium) || 0,
          social_insurance_premium_paid: Number(payload.socialInsurancePremiumPaid) || 0,
          has_mortgage_deduction: !!payload.hasMortgageDeduction,
          mortgage_deduction_amount: payload.hasMortgageDeduction ? Number(payload.mortgageDeductionAmount) || 0 : null,
          notes: payload.notes || null,
          status: 'pending',
          admin_comment: null,
          decided_at: null,
        },
        { onConflict: 'employee_id,year' }
      )
      .select()
      .single();
    if (error) {
      show('年末調整の申告に失敗しました', 'warn');
      return;
    }
    await notifyAdmin(
      `【年末調整】${session.name} - ${payload.year}年分`,
      `${session.name}さんより ${payload.year}年分の年末調整申告が届きました。内容をご確認のうえ承認してください。`,
      inserted?.id,
      { email: true }
    );
    await refreshData();
    show(`${payload.year}年分の年末調整を申告しました`, 'success');
  };

  const decideYearEndAdjustment = async (id, decision, comment) => {
    const request = data.yearEndAdjustments.find((r) => r.id === id);
    if (!request) return;
    const { error } = await supabase
      .from('year_end_adjustments')
      .update({ status: decision, admin_comment: comment || null, decided_at: new Date().toISOString() })
      .eq('id', id);
    if (error) {
      show('処理に失敗しました', 'warn');
      return;
    }
    // 承認のお知らせはアプリ内のみ。差し戻しは再提出が必要なためメールでも知らせる
    const yearEndSubject = `【年末調整${decision === 'approved' ? '承認' : '差し戻し'}】${request.year}年分`;
    const yearEndBody = `${request.year}年分の年末調整申告が${decision === 'approved' ? '承認されました' : '差し戻されました'}。${comment ? `管理者コメント：${comment}` : ''}`;
    if (decision === 'approved') {
      await notifyEmployeeInApp(request.employeeId, yearEndSubject, yearEndBody, id);
    } else {
      await notifyEmployeeUser(request.employeeId, yearEndSubject, yearEndBody, id, [
        `${request.year}年分の年末調整申告が差し戻されました。`,
        ...(comment ? ['', `管理者コメント：${comment}`] : []),
        '',
        '内容をご確認のうえ、修正して再度ご提出ください。',
      ]);
    }
    await refreshData();
    await logAudit(session, decision === 'approved' ? '年末調整を承認' : '年末調整を差し戻し', `${request.year}年分`, request.employeeId, request.employeeName);
    show(decision === 'approved' ? '承認しました' : '差し戻しました', decision === 'approved' ? 'success' : 'warn');
  };

  // ---- 月次勤怠の確定フロー ----
  // スタッフが前月分を確定申請 → 管理者が承認 → マスター管理者が最終承認
  const submitMonthlyAttendanceConfirmation = async (targetMonth, summary, staffNote) => {
    const existing = (data.monthlyConfirmations || []).find(
      (c) => c.employeeId === employeeId && c.targetMonth === targetMonth
    );
    if (existing && existing.status === 'confirmed') {
      show('この月の勤怠はすでに確定しています', 'warn');
      return false;
    }
    const payload = {
      employee_id: employeeId,
      target_month: targetMonth,
      status: 'pending',
      summary,
      staff_note: staffNote || null,
      admin_comment: null,
      admin_decided_at: null,
      master_comment: null,
      master_decided_at: null,
      submitted_at: new Date().toISOString(),
    };
    const { data: saved, error } = existing
      ? await supabase.from('monthly_attendance_confirmations').update(payload).eq('id', existing.id).select().single()
      : await supabase.from('monthly_attendance_confirmations').insert(payload).select().single();
    if (error) {
      console.error('勤怠の確定申請に失敗しました', error);
      show(`勤怠の確定申請に失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    const subject = `【勤怠確定申請】${session.name} - ${monthKeyLabel(targetMonth)}分`;
    const body = `${session.name}さんより ${monthKeyLabel(targetMonth)}分の勤怠確定申請が届きました。内容をご確認のうえ承認してください。`;
    if (session.role === 'admin' || session.role === 'master_admin') {
      // 管理者ご本人の申請は、マスター管理者の承認のみで確定する
      await notify(subject, body, saved?.id, null, 'master_admin');
    } else {
      await notifyAdmin(subject, body, saved?.id);
    }
    await refreshData();
    show(`${monthKeyLabel(targetMonth)}分の勤怠を確定申請しました`, 'success');
    return true;
  };

  // 勤怠の一時保存（申請はせず、あとから続きを入力できる）
  const saveMonthlyAttendanceDraft = async (targetMonth, summary, staffNote) => {
    const existing = (data.monthlyConfirmations || []).find(
      (c) => c.employeeId === employeeId && c.targetMonth === targetMonth
    );
    if (existing && existing.status === 'confirmed') {
      show('この月の勤怠はすでに確定しています', 'warn');
      return false;
    }
    const payload = {
      employee_id: employeeId,
      target_month: targetMonth,
      status: 'draft',
      summary,
      staff_note: staffNote || null,
      submitted_at: new Date().toISOString(),
    };
    const { error } = existing
      ? await supabase.from('monthly_attendance_confirmations').update(payload).eq('id', existing.id)
      : await supabase.from('monthly_attendance_confirmations').insert(payload);
    if (error) {
      console.error('勤怠の一時保存に失敗しました', error);
      show(`一時保存に失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    await refreshData();
    show('勤怠の内容を保存しました。あとから申請できます', 'success');
    return true;
  };

  // 管理者による1次承認（stage: 'admin'）とマスター管理者による最終承認（stage: 'master'）
  const decideMonthlyAttendanceConfirmation = async (id, stage, decision, comment) => {
    const target = (data.monthlyConfirmations || []).find((c) => c.id === id);
    if (!target) return false;
    const now = new Date().toISOString();
    // マスター管理者が確認した時点で確定とする（管理者の承認は1次確認のみ）
    const isFinal = stage === 'master' || session.role === 'master_admin';
    const patch = decision === 'rejected'
      ? { status: 'rejected' }
      : { status: isFinal ? 'confirmed' : 'admin_approved' };
    if (isFinal) {
      patch.master_comment = comment || null;
      patch.master_decided_by = session.id;
      patch.master_decided_at = now;
      // 管理者の確認を経ずにマスター管理者が確定した場合も、確認日時を残す
      if (stage === 'admin') {
        patch.admin_comment = comment || null;
        patch.admin_decided_by = session.id;
        patch.admin_decided_at = now;
      }
    } else {
      patch.admin_comment = comment || null;
      patch.admin_decided_by = session.id;
      patch.admin_decided_at = now;
    }
    const { error } = await supabase.from('monthly_attendance_confirmations').update(patch).eq('id', id);
    if (error) {
      console.error('勤怠確定の処理に失敗しました', error);
      show(`処理に失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    const monthLabel = monthKeyLabel(target.targetMonth);
    if (decision === 'rejected') {
      await notifyEmployeeInApp(
        target.employeeId,
        `【勤怠確定・差し戻し】${monthLabel}分`,
        `${monthLabel}分の勤怠確定申請が差し戻されました。${comment ? `コメント：${comment}` : ''}内容をご確認のうえ、修正して再度ご提出ください。`,
        id
      );
      show('差し戻しました', 'warn');
    } else if (!isFinal) {
      // マスター管理者へ最終承認を依頼する
      await notify(
        `【最終承認のお願い】${target.employeeName} - ${monthLabel}分`,
        `${target.employeeName}さんの ${monthLabel}分の勤怠について、管理者の確認が完了しました。最終承認をお願いします。`,
        id,
        null,
        'master_admin'
      );
      show('承認しました。マスター管理者へ最終承認を依頼しました', 'success');
    } else {
      await notifyEmployeeInApp(
        target.employeeId,
        `【勤怠確定】${monthLabel}分`,
        `${monthLabel}分の勤怠が確定しました。この内容をもとに給与計算を行います。`,
        id
      );
      show('最終承認しました。給与計算に進めます', 'success');
    }
    await refreshData();
    await logAudit(
      session,
      decision === 'rejected' ? '勤怠確定を差し戻し' : isFinal ? '勤怠を最終承認' : '勤怠確定を承認',
      monthLabel,
      target.employeeId,
      target.employeeName
    );
    return true;
  };

  // 確定した勤怠の取り消し（マスター管理者のみ）。差し戻し扱いに戻す
  const cancelMonthlyAttendanceConfirmation = async (id, reason) => {
    if (session.role !== 'master_admin') {
      show('確定を取り消せるのはマスター管理者のみです', 'warn');
      return false;
    }
    const target = (data.monthlyConfirmations || []).find((c) => c.id === id);
    if (!target) return false;

    // その月の給与明細が公開済みなら、確定を取り消せない。
    // 取り消すと「確定していない勤怠にもとづく公開済み明細」が残ってしまうため、
    // 先に明細の公開を取り消してもらう
    const [cy, cm] = String(target.targetMonth || '').split('-').map(Number);
    const payroll = (data.payrollRecords || []).find(
      (p) => p.employeeId === target.employeeId && p.year === cy && p.month === cm
    );
    if (payroll && payroll.status === 'published') {
      show(
        `${monthKeyLabel(target.targetMonth)}分の給与明細が公開済みのため、勤怠の確定を取り消せません。先に給与タブで明細の公開を取り消してください`,
        'warn'
      );
      return false;
    }

    const { error } = await supabase
      .from('monthly_attendance_confirmations')
      .update({
        status: 'rejected',
        master_comment: reason ? `確定を取り消しました：${reason}` : '確定を取り消しました',
        master_decided_by: session.id,
        master_decided_at: new Date().toISOString(),
        admin_decided_by: null,
        admin_decided_at: null,
        admin_comment: null,
      })
      .eq('id', id);
    if (error) {
      console.error('確定の取り消しに失敗しました', error);
      show(`確定の取り消しに失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    const monthLabel = monthKeyLabel(target.targetMonth);
    await notifyEmployeeInApp(
      target.employeeId,
      `【勤怠確定の取り消し】${monthLabel}分`,
      `${monthLabel}分の勤怠の確定が取り消されました。${reason ? `理由：${reason}` : ''}内容をご確認のうえ、修正して再度ご提出ください。`,
      id
    );
    await refreshData();
    await logAudit(session, '勤怠の確定を取り消し', `${monthLabel}${reason ? `／理由：${reason}` : ''}`, target.employeeId, target.employeeName);
    if (payroll) {
      // 下書きの明細は古い勤怠のままなので、作り直しが必要なことを伝える
      show(
        `確定を取り消しました。${monthLabel}分の給与明細（下書き）は取り消し前の勤怠で計算されています。勤怠を直したあとに再計算してください`,
        'warn'
      );
    } else {
      show('確定を取り消しました。スタッフへ通知しています', 'warn');
    }
    return true;
  };

  // 交通費精算書の申請を提出
  const submitCommuteExpenseClaim = async (payload) => {
    // 同じ対象月に未承認の申請があれば、新規作成せず修正として扱う
    const existing = (data.commuteExpenseClaims || []).find(
      (c) => c.employeeId === employeeId && c.targetMonth === payload.targetMonth && c.status !== 'approved'
    );
    if (existing) return updateCommuteExpenseClaim(existing.id, payload);
    const { data: inserted, error } = await supabase
      .from('commute_expense_claims')
      .insert({
        employee_id: employeeId,
        target_month: payload.targetMonth,
        submitted_date: payload.submittedDate,
        items: payload.items,
        total_amount: payload.totalAmount,
        status: 'pending',
      })
      .select()
      .single();
    if (error) {
      console.error('交通費精算書の提出に失敗しました', error);
      show(`交通費精算書の提出に失敗しました：${error.message || error.code || ''}`, 'warn');
      return false;
    }
    await notifyAdmin(
      `【交通費精算】${session.name} - ${formatYen(payload.totalAmount)}`,
      `${session.name}さんより交通費精算書（合計 ${formatYen(payload.totalAmount)}・${payload.items.length}件）が届きました。内容をご確認のうえ承認してください。`,
      inserted?.id
    );
    await refreshData();
    show('交通費精算書を提出しました', 'success');
    return true;
  };

  // 交通費精算書の一時保存（申請はせず、あとから続きを入力できる）
  const saveCommuteExpenseDraft = async (payload) => {
    const existing = (data.commuteExpenseClaims || []).find(
      (c) => c.employeeId === employeeId && c.targetMonth === payload.targetMonth
    );
    if (existing && existing.status === 'approved') {
      show('承認済みの月は保存できません', 'warn');
      return false;
    }
    const row = {
      employee_id: employeeId,
      target_month: payload.targetMonth,
      submitted_date: payload.submittedDate,
      items: payload.items,
      total_amount: payload.totalAmount,
      status: 'draft',
      admin_comment: null,
      decided_at: null,
    };
    const { error } = existing
      ? await supabase.from('commute_expense_claims').update(row).eq('id', existing.id)
      : await supabase.from('commute_expense_claims').insert(row);
    if (error) {
      console.error('交通費の一時保存に失敗しました', error);
      show(`一時保存に失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    await refreshData();
    show('入力内容を保存しました。あとから続きを入力できます', 'success');
    return true;
  };

  // 交通費精算書の修正（承認待ち・差し戻しのものだけ本人が直せる）
  const updateCommuteExpenseClaim = async (id, payload) => {
    const claim = (data.commuteExpenseClaims || []).find((c) => c.id === id);
    if (!claim || claim.employeeId !== employeeId) return false;
    if (claim.status === 'approved') {
      show('承認済みの申請は修正できません', 'warn');
      return false;
    }
    const { error } = await supabase
      .from('commute_expense_claims')
      .update({
        target_month: payload.targetMonth,
        submitted_date: payload.submittedDate,
        items: payload.items,
        total_amount: payload.totalAmount,
        status: 'pending',
        admin_comment: null,
        decided_at: null,
      })
      .eq('id', id);
    if (error) {
      console.error('交通費精算書の修正に失敗しました', error);
      show(`交通費精算書の修正に失敗しました：${error.message || error.code || ''}`, 'warn');
      return false;
    }
    await notifyAdmin(
      `【交通費精算・修正】${session.name} - ${formatYen(payload.totalAmount)}`,
      `${session.name}さんが交通費精算書を修正しました（合計 ${formatYen(payload.totalAmount)}・${payload.items.length}件）。内容をご確認のうえ承認してください。`,
      id
    );
    await refreshData();
    show('交通費精算書を修正しました', 'success');
    return true;
  };

  // ---- シフト希望 ----
  // スタッフが1日ごとの希望（ok／off／paid）を提出する
  const submitShiftRequest = async (targetMonth, answers, note) => {
    const existing = (data.shiftRequests || []).find(
      (r) => r.employeeId === employeeId && r.targetMonth === targetMonth
    );
    const row = {
      employee_id: employeeId,
      target_month: targetMonth,
      answers,
      note: note || null,
      submitted_at: new Date().toISOString(),
    };
    // 同じ月の行がすでにあっても確実に書き込めるよう、まとめて upsert する
    const { error } = await supabase
      .from('shift_request_answers')
      .upsert(row, { onConflict: 'employee_id,target_month' });
    if (error) {
      console.error('シフト希望の提出に失敗しました', error);
      const detail = [error.message, error.details, error.hint, error.code].filter(Boolean).join(' / ');
      show(`提出に失敗しました：${detail || '原因不明'}`, 'warn');
      return false;
    }
    await notifyAdmin(
      `【シフト希望】${session.name} - ${monthKeyLabel(targetMonth)}分`,
      `${session.name}さんが${monthKeyLabel(targetMonth)}分のシフト希望を提出しました。`,
      null
    );
    await refreshData();
    show(existing ? 'シフト希望を出し直しました' : 'シフト希望を提出しました', 'success');
    return true;
  };

  // 管理者が対象月の受付設定（受付中・締切・出勤依頼日）を保存する
  const saveShiftPeriod = async (targetMonth, patch) => {
    const existing = (data.shiftPeriods || []).find((p) => p.targetMonth === targetMonth);
    const row = {
      target_month: targetMonth,
      is_open: patch.isOpen != null ? patch.isOpen : (existing ? existing.isOpen : true),
      deadline: patch.deadline !== undefined ? (patch.deadline || null) : (existing?.deadline || null),
      request_days: patch.requestDays || existing?.requestDays || [],
      target_employee_ids: patch.targetEmployeeIds !== undefined
        ? (patch.targetEmployeeIds && patch.targetEmployeeIds.length > 0 ? patch.targetEmployeeIds : null)
        : (existing?.targetEmployeeIds || null),
      note: patch.note !== undefined ? (patch.note || null) : (existing?.note || null),
      opened_by: session.id,
    };
    const { error } = existing
      ? await supabase.from('shift_request_periods').update(row).eq('target_month', targetMonth)
      : await supabase.from('shift_request_periods').insert(row);
    if (error) {
      console.error('シフト受付の保存に失敗しました', error);
      show(`保存に失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    await refreshData();
    return true;
  };

  // 交通費の承認内容が変わったとき、作成済みの給与明細の「交通費精算」も合わせる
  // 戻り値：'changed'（更新した）／'none'（更新の必要がなかった）
  //         'blocked'（公開済みのため更新しなかった）／'failed'（更新に失敗）
  const syncCommuteAmountInPayroll = async (targetEmployeeId, targetMonth, newAmount) => {
    if (!targetMonth) return 'none';
    const [y, m] = targetMonth.split('-').map(Number);
    const record = (data.payrollRecords || []).find(
      (r) => r.employeeId === targetEmployeeId && r.year === y && r.month === m
    );
    if (!record || !Array.isArray(record.paymentItems)) return 'none';
    const label = `交通費精算（${m}月分）`;
    const without = record.paymentItems.filter((it) => !String(it.label || '').startsWith('交通費精算'));
    const nextItems = newAmount > 0 ? [...without, { label, amount: newAmount }] : without;
    const before = record.paymentItems.reduce((sum, it) => sum + (Number(it.amount) || 0), 0);
    const after = nextItems.reduce((sum, it) => sum + (Number(it.amount) || 0), 0);
    if (before === after && nextItems.length === record.paymentItems.length) return 'none';
    // 公開済みの明細は書き換えない。スタッフが受け取った明細があとから変わると
    // 手元の控えと食い違うため、管理者に知らせて判断してもらう
    if (record.status === 'published') return 'blocked';
    const deductionTotal = (record.deductionItems || []).reduce((sum, it) => sum + (Number(it.amount) || 0), 0);
    const previousCommute = Number(record.paymentItems.find((it) => String(it.label || '').startsWith('交通費精算'))?.amount) || 0;
    const { error } = await supabase
      .from('payroll_records')
      .update({
        payment_items: nextItems,
        base_amount: after,
        total_amount: after - deductionTotal,
        edit_history: appendHistory(record.editHistory, makeHistoryEntry(session, '交通費を反映', [
          `交通費精算：${formatYen(previousCommute)} → ${formatYen(newAmount)}`,
        ])),
      })
      .eq('id', record.id);
    if (error) {
      console.error('給与明細の交通費の更新に失敗しました', error);
      return 'failed';
    }
    await logAudit(
      session,
      '給与明細の交通費を更新',
      `${y}年${m}月：${formatYen(previousCommute)} → ${formatYen(newAmount)}`,
      targetEmployeeId
    );
    return 'changed';
  };

  // 公開済みで反映できなかったときに、管理者へ出す案内
  const warnCommuteSyncBlocked = (targetMonth) => {
    const [y, m] = String(targetMonth || '').split('-').map(Number);
    const when = y && m ? `${y}年${m}月分` : '対象月';
    show(
      `${when}の給与明細は公開済みのため、交通費を反映しませんでした。翌月で調整するか、公開を取り消してから反映してください`,
      'warn'
    );
  };

  // 承認済みの交通費精算の取り消し（マスター管理者のみ）。差し戻し扱いに戻す
  const cancelCommuteExpenseApproval = async (id, reason) => {
    if (session.role !== 'master_admin') {
      show('承認を取り消せるのはマスター管理者のみです', 'warn');
      return false;
    }
    const claim = (data.commuteExpenseClaims || []).find((c) => c.id === id);
    if (!claim) return false;
    const { error } = await supabase
      .from('commute_expense_claims')
      .update({
        status: 'rejected',
        admin_comment: reason ? `承認を取り消しました：${reason}` : '承認を取り消しました',
        decided_at: new Date().toISOString(),
      })
      .eq('id', id);
    if (error) {
      console.error('承認の取り消しに失敗しました', error);
      show(`承認の取り消しに失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    const payrollSync = await syncCommuteAmountInPayroll(claim.employeeId, claim.targetMonth, 0);
    await notifyEmployeeInApp(
      claim.employeeId,
      '【交通費精算・承認の取り消し】',
      `交通費精算書（合計 ${formatYen(claim.totalAmount)}）の承認が取り消されました。${reason ? `理由：${reason}` : ''}${payrollSync === 'changed' ? '給与明細の交通費も取り下げました。' : ''}内容をご確認のうえ、修正して再度ご提出ください。`,
      id
    );
    await refreshData();
    await logAudit(session, '交通費精算の承認を取り消し', `${formatYen(claim.totalAmount)}${reason ? `／理由：${reason}` : ''}`, claim.employeeId, claim.employeeName);
    if (payrollSync === 'blocked') {
      warnCommuteSyncBlocked(claim.targetMonth);
    } else {
      show('承認を取り消しました。スタッフへ通知しています', 'warn');
    }
    return true;
  };

  // editedItems を渡すと、その内容に直してから承認する（マスター管理者の修正承認）
  const decideCommuteExpenseClaim = async (id, decision, comment, editedItems) => {
    const claim = data.commuteExpenseClaims.find((c) => c.id === id);
    if (!claim) return;
    const useEdited = decision === 'approved' && Array.isArray(editedItems);
    const nextItems = useEdited ? editedItems : claim.items;
    const nextTotal = useEdited
      ? editedItems.reduce((sum, r) => sum + (Number(r.subtotal) || 0), 0)
      : claim.totalAmount;
    const changes = useEdited ? describeCommuteItemChanges(claim.items, editedItems) : [];

    const patch = { status: decision, admin_comment: comment || null, decided_at: new Date().toISOString() };
    if (useEdited) {
      patch.items = editedItems;
      patch.total_amount = nextTotal;
    }
    const { error } = await supabase.from('commute_expense_claims').update(patch).eq('id', id);
    if (error) {
      console.error('交通費精算の処理に失敗しました', error);
      show(`処理に失敗しました：${error.message || ''}`, 'warn');
      return;
    }

    // 承認・差し戻しに合わせて、作成済みの給与明細の交通費も更新する
    // （公開済みの明細は書き換えない。そのときは下で管理者に案内を出す）
    const payrollSync = await syncCommuteAmountInPayroll(
      claim.employeeId,
      claim.targetMonth,
      decision === 'approved' ? nextTotal : 0
    );

    const lines = [
      `交通費精算書（合計 ${formatYen(nextTotal)}）が${decision === 'approved' ? '承認されました' : '差し戻されました'}。`,
    ];
    if (changes.length > 0) {
      lines.push('', '【管理者による修正箇所】', ...changes.map((t) => `・${t}`));
    }
    if (comment) lines.push('', `管理者コメント：${comment}`);
    if (payrollSync === 'changed') lines.push('', '給与明細の交通費も更新しました。');

    await notifyEmployeeInApp(
      claim.employeeId,
      `【交通費精算${decision === 'approved' ? (changes.length > 0 ? '修正のうえ承認' : '承認') : '差し戻し'}】`,
      lines.join('\n'),
      id
    );
    await refreshData();
    await logAudit(
      session,
      decision === 'approved' ? (changes.length > 0 ? '交通費精算を修正して承認' : '交通費精算を承認') : '交通費精算を差し戻し',
      `${formatYen(nextTotal)}${changes.length > 0 ? `／修正 ${changes.length}件` : ''}`,
      claim.employeeId,
      claim.employeeName
    );
    if (payrollSync === 'blocked') {
      warnCommuteSyncBlocked(claim.targetMonth);
    } else {
      show(decision === 'approved' ? (changes.length > 0 ? '修正して承認しました' : '承認しました') : '差し戻しました', decision === 'approved' ? 'success' : 'warn');
    }
  };

  // monthlyDays は { 'YYYY-M': 日数 } の形（年度の12か月ぶん）
  const saveGroupLeaveSchedule = async (groupName, monthlyDays, fiscalYear) => {
    const rows = Object.entries(monthlyDays).map(([key, days]) => {
      const [yy, mm] = String(key).split('-').map(Number);
      return { group_name: groupName, year: yy, month: mm, days: Number(days) || 0 };
    });
    const { error } = await supabase.from('group_attendance_schedules').upsert(rows, { onConflict: 'group_name,year,month' });
    if (error) {
      console.error('グループの出勤規定日数の保存に失敗しました', error);
      show('グループの出勤規定日数の保存に失敗しました', 'warn');
      return;
    }
    await refreshData();
    await logAudit(session, 'グループ別出勤規定日数を更新', `${groupName}／${fiscalYear}年度`);
    show(`「${groupName}」の${fiscalYear}年度の出勤規定日数を保存しました`, 'success');
  };

  // グループ未設定のスタッフ向け：個人別の出勤規定日数（月ごと）を保存
  const saveEmployeeAttendanceSchedule = async (employeeId, monthlyDays, fiscalYear) => {
    const rows = Object.entries(monthlyDays).map(([key, days]) => {
      const [yy, mm] = String(key).split('-').map(Number);
      return { employee_id: employeeId, year: yy, month: mm, days: Number(days) || 0 };
    });
    const { error } = await supabase.from('employee_attendance_schedules').upsert(rows, { onConflict: 'employee_id,year,month' });
    if (error) {
      console.error('個人別の出勤規定日数の保存に失敗しました', error);
      show('個人別の出勤規定日数の保存に失敗しました', 'warn');
      return;
    }
    await refreshData();
    const target = data.accounts.find((a) => a.id === employeeId);
    await logAudit(session, '個人別出勤規定日数を更新', `${target?.name || ''}／${fiscalYear}年度`, employeeId, target?.name || '');
    show(`${fiscalYear}年度の出勤規定日数を保存しました`, 'success');
  };

  const submitAnnouncement = async ({ title, category, body, file, isPinned }) => {
    let filePath = null;
    let fileName = null;
    if (file) {
      // ストレージのキーは日本語や記号を含められないため、拡張子だけ残してASCIIのみのキーにする
      // （画面に表示する元のファイル名は fileName 側にそのまま保持）
      const extMatch = file.name.match(/\.[a-zA-Z0-9]+$/);
      const ext = extMatch ? extMatch[0] : '';
      const randomPart = Math.random().toString(36).slice(2, 8);
      filePath = `${Date.now()}_${randomPart}${ext}`;
      const { error: uploadError } = await supabase.storage.from('announcements').upload(filePath, file);
      if (uploadError) {
        show(`ファイルのアップロードに失敗しました: ${uploadError.message}`, 'warn');
        return false;
      }
      fileName = file.name;
    }
    const { error } = await supabase.from('announcements').insert({
      title,
      category,
      body: body || null,
      file_path: filePath,
      file_name: fileName,
      created_by: session.id,
      created_by_name: session.name,
      is_pinned: !!isPinned,
    });
    if (error) {
      show('お知らせの投稿に失敗しました', 'warn');
      return false;
    }
    await refreshData();
    await logAudit(session, 'お知らせを配信', `${category}：${title}`);
    show('お知らせを配信しました', 'success');
    return true;
  };

  const deleteAnnouncement = async (announcement) => {
    if (announcement.filePath) {
      await supabase.storage.from('announcements').remove([announcement.filePath]);
    }
    const { error } = await supabase.from('announcements').delete().eq('id', announcement.id);
    if (error) {
      show('削除に失敗しました', 'warn');
      return;
    }
    await refreshData();
    show('お知らせを削除しました', 'success');
  };

  const getAnnouncementFileUrl = async (filePath) => {
    const { data: signed, error } = await supabase.storage.from('announcements').createSignedUrl(filePath, 60 * 10);
    if (error || !signed) {
      show('ファイルの取得に失敗しました', 'warn');
      return null;
    }
    return signed.signedUrl;
  };

  const savePayrollDraft = async (payload) => {
    // 公開済みの明細は上書きしない。
    // 以前は status: 'draft' を固定で書いていたため、保存するだけで公開が
    // 取り消され、スタッフの画面から明細が消えていた
    const already = (data.payrollRecords || []).find(
      (r) => r.employeeId === payload.employeeId && r.year === payload.year && r.month === payload.month
    );
    if (already && already.status === 'published') {
      show('この月の給与明細は公開済みです。直すには先に公開を取り消してください', 'warn');
      return;
    }
    // 修正履歴に残す差分を作る（新規作成のときは「作成」の1件だけ）
    const changes = [];
    if (already) {
      const yenFields = [
        ['base_amount', '支給合計', already.baseAmount, payload.baseAmount],
        ['total_amount', '差引支給額', already.totalAmount, payload.totalAmount],
        ['overtime_amount', '残業手当', already.overtimeAmount, payload.overtimeAmount],
      ];
      yenFields.forEach(([, label, before, after]) => {
        if (Number(before) !== Number(after)) changes.push(`${label}：${formatYen(before)} → ${formatYen(after)}`);
      });
      if (Number(already.workedMinutes) !== Number(payload.workedMinutes)) {
        changes.push(`実働：${minutesToHHMM(already.workedMinutes)} → ${minutesToHHMM(payload.workedMinutes)}`);
      }
      if (Number(already.overtimeMinutes) !== Number(payload.overtimeMinutes)) {
        changes.push(`残業：${minutesToHHMM(already.overtimeMinutes)} → ${minutesToHHMM(payload.overtimeMinutes)}`);
      }
      changes.push(...diffAmountItems(already.paymentItems, payload.paymentItems, '支給'));
      changes.push(...diffAmountItems(already.deductionItems, payload.deductionItems, '控除'));
      if ((already.notes || '') !== (payload.notes || '')) changes.push('備考を変更');
    }
    const entry = makeHistoryEntry(session, already ? '金額を変更' : '明細を作成', changes);
    const nextHistory = already && changes.length === 0
      ? (already.editHistory || [])            // 中身が変わっていなければ履歴は増やさない
      : appendHistory(already?.editHistory, entry);

    const { error } = await supabase.from('payroll_records').upsert(
      {
        employee_id: payload.employeeId,
        year: payload.year,
        month: payload.month,
        wage_type: payload.wageType,
        wage_rate: payload.wageRate,
        worked_minutes: payload.workedMinutes,
        overtime_minutes: payload.overtimeMinutes,
        base_amount: payload.baseAmount,
        overtime_amount: payload.overtimeAmount,
        total_amount: payload.totalAmount,
        status: 'draft',
        notes: payload.notes || null,
        payment_items: payload.paymentItems || null,
        deduction_items: payload.deductionItems || null,
        attendance_extra: payload.attendanceExtra || null,
        edit_history: nextHistory,
      },
      { onConflict: 'employee_id,year,month' }
    );
    if (error) {
      show('給与明細の保存に失敗しました', 'warn');
      return;
    }
    await refreshData();
    if (already) {
      await logAudit(
        session,
        '給与明細を変更',
        `${payload.year}年${payload.month}月分${changes.length ? `／${changes.join('／')}` : '（変更なし）'}`,
        payload.employeeId
      );
    } else {
      await logAudit(session, '給与明細を作成', `${payload.year}年${payload.month}月分`, payload.employeeId);
    }
    show(
      changes.length > 0
        ? `給与明細を下書き保存しました（${changes.length}件の変更を履歴に記録しました）`
        : '給与明細を下書き保存しました',
      'success'
    );
  };

  const publishPayroll = async (id) => {
    const target = data.payrollRecords.find((p) => p.id === id);
    const { error } = await supabase.from('payroll_records').update({
      status: 'published',
      published_at: new Date().toISOString(),
      edit_history: appendHistory(target?.editHistory, makeHistoryEntry(session, '公開')),
    }).eq('id', id);
    if (error) {
      show('公開に失敗しました', 'warn');
      return;
    }
    const record = data.payrollRecords.find((p) => p.id === id);
    if (record) {
      await notifyEmployeeUser(
        record.employeeId,
        `【給与明細】${record.year}年${record.month}月分`,
        `${record.year}年${record.month}月分の給与明細が公開されました。ご確認ください。`,
        id,
        [
          `${record.year}年${record.month}月分の給与明細を公開しました。`,
          '下記よりご確認ください。',
        ]
      );
    }
    await refreshData();
    await logAudit(session, '給与明細を公開', record ? `${record.year}年${record.month}月分` : '', record?.employeeId, record?.employeeName);
    show('給与明細を公開しました', 'success');
  };

  // 公開済みの給与明細を下書きに戻す（マスター管理者のみ）。
  // 公開済みは直接直せないため、直したいときはこれで下書きに戻してから修正する
  const unpublishPayroll = async (id) => {
    if (session.role !== 'master_admin') {
      show('公開を取り消せるのはマスター管理者のみです', 'warn');
      return false;
    }
    const record = data.payrollRecords.find((p) => p.id === id);
    const { error } = await supabase
      .from('payroll_records')
      .update({
        status: 'draft',
        published_at: null,
        edit_history: appendHistory(record?.editHistory, makeHistoryEntry(session, '公開を取り消し')),
      })
      .eq('id', id);
    if (error) {
      console.error('公開の取り消しに失敗しました', error);
      show(`公開の取り消しに失敗しました：${error.message || ''}`, 'warn');
      return false;
    }
    if (record) {
      await notifyEmployeeInApp(
        record.employeeId,
        `【給与明細・一時非公開】${record.year}年${record.month}月分`,
        `${record.year}年${record.month}月分の給与明細を、内容の確認のため一時的に非公開にしました。`
          + '\n確認が終わりしだい、あらためて公開しお知らせします。',
        id
      );
    }
    await refreshData();
    await logAudit(
      session,
      '給与明細の公開を取り消し',
      record ? `${record.year}年${record.month}月分` : '',
      record?.employeeId,
      record?.employeeName
    );
    show('公開を取り消しました。内容を直したうえで再度公開してください', 'warn');
    return true;
  };


  const cloudStatusLabel = cloudStatus === 'cloud' ? 'クラウド同期' : cloudStatus === 'connecting' ? '接続中' : cloudStatus === 'error' ? '同期エラー' : '端末保存';
  const cloudStatusClass = cloudStatus === 'cloud' ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : cloudStatus === 'error' ? 'bg-rose-50 text-rose-700 border-rose-200' : 'bg-slate-50 text-slate-600 border-slate-200';
  if (!loaded) {
    return <div className="min-h-screen flex items-center justify-center bg-slate-50 text-slate-400 font-sans text-sm">読み込み中…</div>;
  }

  if (passwordRecoveryMode) {
    return (
      <ResetPasswordRecoveryScreen
        toast={toast}
        onDone={async () => {
          setPasswordRecoveryMode(false);
          await supabase.auth.signOut();
        }}
      />
    );
  }

  // 初回ログイン：仮パスワードのままならパスワード変更を必須にする
  if (session && session.mustChangePassword) {
    return (
      <FirstLoginPasswordScreen
        session={session}
        toast={toast}
        onDone={async () => {
          // 保存されている内容を読み直して、次に表示する画面を判定する
          const { data: row } = await supabase.from('employees_visible').select('*').eq('id', session.id).maybeSingle();
          if (row) setSession({ ...rowToAccount(row), mustChangePassword: false });
          else setSession((prev) => ({ ...prev, mustChangePassword: false }));
          await refreshData();
          show('パスワードを変更しました', 'success');
        }}
        onLogout={handleLogout}
      />
    );
  }

  // パスワード変更後、個人情報の入力をご案内する
  if (session && session.profileSetupCompleted === false) {
    return (
      <ProfileSetupScreen
        session={session}
        toast={toast}
        onSave={async ({ profile, myNumber }) => {
          const savedNumber = await saveOwnMyNumber(myNumber);
          if (!savedNumber) return 'マイナンバーの保存に失敗しました。お手数ですが管理者までご連絡ください。';
          const ok = await updateEmployeeProfile(session.id, profile);
          if (!ok) return 'ご登録情報の保存に失敗しました。時間をおいて再度お試しください。';
          show('ご登録ありがとうございます', 'success');
          return true;
        }}
        onLogout={handleLogout}
      />
    );
  }

  // パスワードは通ったが、まだ2段階認証のコードを入れていない状態
  if (!session && mfaPending) {
    return (
      <MfaChallengeScreen
        onVerify={async (code) => {
          await verifyMfaCode(code);
          setMfaPending(false);
          await loadSessionAndData();
          show('おかえりなさい', 'success');
        }}
        onCancel={async () => {
          setMfaPending(false);
          await supabase.auth.signOut();
        }}
        toast={toast}
      />
    );
  }

  if (!session) {
    return <LoginScreen onLogin={handleLogin} toast={toast} linkError={linkError} onClearLinkError={() => setLinkError('')} />;
  }

  const isDesktop = viewMode === 'desktop';

  const historyDates = Array.from(new Set([...Object.keys(employeeRecords), today])).sort((a, b) => (a < b ? 1 : -1));
  const myCorrections = data.corrections.filter((c) => c.employeeId === employeeId);
  const myLeaveRequests = data.leaveRequests.filter((l) => l.employeeId === employeeId);
  // 有休の残日数。繰越・2年時効・繰越分優先の消化を含めて出します。
  // 以前は「今年度の付与日数 − 入社以来の消化日数」で出していたため、
  // 勤続1年を超えると残日数がマイナスになり、有休の申請ができなくなっていました。
  const myLeaveBalance = computePaidLeaveBalance({
    employee: session,
    grantRows: data.leaveGrants,
    leaveRequests: myLeaveRequests,
    settings: data.settings,
    asOf: now,
  });
  const myLeaveTotal = myLeaveBalance.granted;
  const myLeaveUsed = myLeaveBalance.usedFromLive;

  // 管理者・マスター管理者も「働く人」として勤怠・給与の対象に含める
  const employeeAccounts = data.accounts;
  // 管理者は「管理画面」と「自分の画面（打刻・申請）」を切り替えて使う
  const isAdminRole = session.role === 'admin' || session.role === 'master_admin';
  const showStaffScreens = !isAdminRole || personalMode;
  // 各種申請（スタッフ画面）の未提出の目印
  const myMonthlyConfirm = (data.monthlyConfirmations || []).find(
    (c) => c.employeeId === employeeId && c.targetMonth === commuteClaimTargetMonthKey
  );
  const needsMonthlyConfirm = !myMonthlyConfirm || myMonthlyConfirm.status === 'draft' || myMonthlyConfirm.status === 'rejected';
  // シフト希望：受付中の月があるときだけ各種申請に出す
  // シフト希望の入力の型は、所属するメイングループの設定で決まる
  const myShiftFormatKey = shiftFormatKeyFor(session.mainGroup, data.settings);
  // この方がシフト希望の対象か（グループの設定 ＋ ご本人の例外。77番）
  const myShiftRequired = requiresRequest('shift', session, data.settings);
  const openShiftPeriod = (myShiftFormatKey === 'none' || !myShiftRequired) ? null : ((data.shiftPeriods || []).find(
    (p) => p.isOpen && (!p.targetEmployeeIds || p.targetEmployeeIds.length === 0 || p.targetEmployeeIds.includes(employeeId))
  ) || null);
  const myShiftRequest = openShiftPeriod
    ? (data.shiftRequests || []).find((r) => r.employeeId === employeeId && r.targetMonth === openShiftPeriod.targetMonth) || null
    : null;
  const requestBadges = {
    monthly: needsMonthlyConfirm ? '未提出' : null,
    commute: needsCommuteClaimReminder ? '未提出' : null,
    shift: openShiftPeriod && !myShiftRequest ? '未提出' : null,
  };
  // 実績入力は、所属している業務（メイングループ）の入力フォーマットを自動で出す。
  // 定義がない業務の方、およびご本人が「不要」に設定されている方には「実績入力」自体を出さない。
  const perfFormat = requiresRequest('performance', session, data.settings)
    ? PERFORMANCE_FORMATS[performanceFormatKeyFor(session.mainGroup, data.settings)] || null
    : null;
  const PerformanceFormatSection = perfFormat?.Component || null;
  // 交通費申請も、グループの設定とご本人の例外で出し分ける（77番）
  const myCommuteRequired = requiresRequest('commute', session, data.settings);
  const staffRequestItems = STAFF_REQUEST_ITEMS
    .filter((it) => (!it.byGroup || !!perfFormat) && (!it.shiftOnly || !!openShiftPeriod)
      && (it.key !== 'commute' || myCommuteRequired))
    .map((it) => {
      if (it.byGroup && perfFormat) return { ...it, label: perfFormat.label, desc: perfFormat.desc };
      if (it.shiftOnly && openShiftPeriod) {
        return { ...it, desc: `${monthKeyLabel(openShiftPeriod.targetMonth)}分${openShiftPeriod.deadline ? `（締切 ${dateLabel(openShiftPeriod.deadline)}）` : ''}` };
      }
      // 交通費申請の対象外の方には「交通費とまとめて提出」と書かない（77番）
      if (it.key === 'monthly' && !myCommuteRequired) {
        return { ...it, desc: '前月分の勤怠を確認して提出' };
      }
      return it;
    });
  const openRequest = (key) => {
    setTopTab('requests');
    setRequestTab(key);
  };
  // 「勤怠」タブのサブタブ。実績入力は、その業務に入力フォーマットがある方にだけ出す
  const employeeTabItems = [
    { key: 'attendance', label: '勤怠', icon: Clock },
    { key: 'shifttable', label: 'シフト', icon: ListChecks },
    ...(PerformanceFormatSection ? [{ key: 'performance', label: '実績', icon: BarChart3 }] : []),
  ];
  // 入力フォーマットの設定が外れた場合など、出せないサブタブを選んだままにしない
  const activeEmployeeTab = employeeTabItems.some((t) => t.key === employeeTab) ? employeeTab : 'attendance';
  // スタッフ画面には「人材」タブがなく、管理画面には「各種申請」タブがないため、行き先を読み替える
  const effectiveTopTab = showStaffScreens
    ? (topTab === 'hr' ? 'requests' : topTab)
    : (topTab === 'requests' ? 'hr' : topTab);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900">
      <div ref={appHeaderRef} className="sticky top-0 z-20">
        <div style={{ paddingTop: 'env(safe-area-inset-top)' }} className="bg-slate-950">
          <GlobalTopTabs
            topTab={effectiveTopTab}
            setTopTab={setTopTab}
            staffMode={showStaffScreens}
            onOpenProfile={() => setTopTab('profile')}
            wide={isDesktop && !showStaffScreens}
            requestItems={staffRequestItems}
            requestBadges={requestBadges}
            onSelectRequest={(key) => setRequestTab(key)}
            session={session}
            personalMode={personalMode}
            setPersonalMode={setPersonalMode}
            onLogout={handleLogout}
            viewMode={viewMode}
            onToggleViewMode={() => setViewMode((v) => (v === 'desktop' ? 'mobile' : 'desktop'))}
            cloudStatusLabel={cloudStatusLabel}
            cloudStatusClass={cloudStatusClass}
          />
        </div>
      </div>
      <main className={isDesktop ? `${showStaffScreens ? 'max-w-6xl' : 'max-w-[1400px]'} mx-auto px-6 pb-16 pt-8` : 'max-w-3xl mx-auto px-4 pt-6 pb-10'}>
        {effectiveTopTab === 'labor' && (
          <div className="space-y-5">
            {!showStaffScreens && session.role === 'master_admin' && (
              <ProfileChangeNoticeCard
                requests={data.profileUpdateRequests}
                accounts={data.accounts}
                onOpen={() => setTopTab('hr')}
              />
            )}
            {showStaffScreens && (
              <MyRequestStatusCard
                items={buildMyRequests({
                  corrections: myCorrections,
                  leaveRequests: myLeaveRequests,
                  monthlyConfirmations: (data.monthlyConfirmations || []).filter((c) => c.employeeId === employeeId),
                  commuteClaims: data.commuteExpenseClaims.filter((c) => c.employeeId === employeeId),
                  yearEndAdjustments: data.yearEndAdjustments.filter((r) => r.employeeId === employeeId),
                  profileRequests: data.profileUpdateRequests.filter((r) => r.employeeId === employeeId),
                  shiftRequests: (data.shiftRequests || []).filter((r) => r.employeeId === employeeId),
                })}
                onOpen={(key) => (key === 'profile' ? setTopTab('profile') : openRequest(key))}
              />
            )}
            {/* 配信・削除のボタンは管理画面のときだけ。スタッフ画面では閲覧のみ */}
            <AnnouncementsView
              announcements={data.announcements}
              isAdmin={!showStaffScreens && (session.role === 'admin' || session.role === 'master_admin')}
              onSubmit={submitAnnouncement}
              onDelete={deleteAnnouncement}
              onGetFileUrl={getAnnouncementFileUrl}
              isDesktop={isDesktop}
            />
            {!showStaffScreens && (
              <PaidLeaveSummaryTab
                employeeAccounts={employeeAccounts}
                leaveRequests={data.leaveRequests}
                isDesktop={isDesktop}
              />
            )}
            {!showStaffScreens && (
              <PaidLeaveLedgerTab
                employeeAccounts={employeeAccounts}
                leaveGrants={data.leaveGrants}
                leaveRequests={data.leaveRequests}
                settings={data.settings}
                isDesktop={isDesktop}
              />
            )}
            {!showStaffScreens && (
              <AttendanceLedgerTab
                employeeAccounts={employeeAccounts}
                records={data.records}
                isDesktop={isDesktop}
              />
            )}
            {!showStaffScreens && (
              <TurnoverAnalysisTab
                employeeAccounts={employeeAccounts}
                resignationReasons={data.resignationReasons}
                isDesktop={isDesktop}
              />
            )}
          </div>
        )}
        {effectiveTopTab === 'help' && (
          <HelpTab session={session} isDesktop={isDesktop} />
        )}
        {/* 登録情報の閲覧・変更。右上のメニューから開く */}
        {effectiveTopTab === 'profile' && (
          <div className="space-y-5">
            <button
              onClick={() => setTopTab('attendance')}
              className="flex items-center gap-1 text-[12.5px] font-bold text-slate-500 hover:text-slate-800"
            >
              <ChevronLeft size={14} /> 勤怠の画面へ戻る
            </button>
            <ProfileRequestView
              session={session}
              requests={data.profileUpdateRequests.filter((r) => r.employeeId === employeeId)}
              onSubmit={submitProfileUpdateRequest}
            />
            {(session.role === 'admin' || session.role === 'master_admin') && (
              <TwoFactorCard session={session} />
            )}
          </div>
        )}
        {effectiveTopTab === 'requests' && showStaffScreens && (
          <div className="space-y-5">
            <StaffRequestNav active={requestTab} onSelect={setRequestTab} badges={requestBadges} items={staffRequestItems} />
            {requestTab === 'shift' && (
              <ShiftRequestSection
                session={session}
                period={openShiftPeriod}
                request={myShiftRequest}
                onSubmit={submitShiftRequest}
                formatKey={myShiftFormatKey}
                groupAttendanceSchedules={data.groupLeaveSchedules}
                employeeAttendanceSchedules={data.employeeAttendanceSchedules}
              />
            )}
            {requestTab === 'leave' && (
              <LeaveView
                leaveRequests={myLeaveRequests}
                leaveTotal={myLeaveTotal}
                leaveUsed={myLeaveUsed}
                balance={myLeaveBalance}
                hireDate={session.hireDate}
                onOpenLeaveModal={() => setLeaveModalOpen(true)}
                isDesktop={isDesktop}
              />
            )}
            {requestTab === 'monthly' && (
              <MonthlyAttendanceConfirmSection
                session={session}
                records={employeeRecords}
                confirmations={(data.monthlyConfirmations || []).filter((c) => c.employeeId === employeeId)}
                commuteClaims={data.commuteExpenseClaims.filter((c) => c.employeeId === employeeId)}
                onSubmit={submitMonthlyAttendanceConfirmation}
                onSubmitCommute={submitCommuteExpenseClaim}
                onUpdateCommute={updateCommuteExpenseClaim}
                onSaveAttendanceDraft={saveMonthlyAttendanceDraft}
                onGoToCommute={() => openRequest('commute')}
                commuteRequired={myCommuteRequired}
              />
            )}
            {requestTab === 'commute' && myCommuteRequired && (
              <CommuteExpenseClaimSection
                session={session}
                claims={data.commuteExpenseClaims.filter((c) => c.employeeId === employeeId)}
                onSubmit={submitCommuteExpenseClaim}
                onUpdate={updateCommuteExpenseClaim}
                onSaveDraft={saveCommuteExpenseDraft}
              />
            )}
            {requestTab === 'yearend' && (
              <YearEndAdjustmentSection
                session={session}
                requests={data.yearEndAdjustments.filter((r) => r.employeeId === employeeId)}
                onSubmit={submitYearEndAdjustment}
              />
            )}
          </div>
        )}
        {effectiveTopTab === 'hr' && !showStaffScreens && (
          <div className="space-y-5">
              {/* 年末調整はマスター管理者だけが扱う
                  （supabase/78_year_end_master_only.sql）。
                  配偶者の所得・保険料・住宅ローン控除額が入っているため、
                  給与明細と同じ扱いにした。
                  データベース側で読めなくなるので、ここで出し分けないと
                  管理者には「0名」の空の一覧が出て混乱する。 */}
              {session.role !== 'master_admin' ? (
                <div className="rounded-2xl border border-amber-200 bg-amber-50 px-5 py-4 text-[12px] text-amber-800">
                  <div className="font-bold mb-1">年末調整はマスター管理者が扱います</div>
                  配偶者の所得や保険料など、給与明細と同じ扱いの情報が含まれるためです。
                  内容の確認が必要なときは、総務担当へご依頼ください。ご自身の年末調整は
                  「自分の勤怠」に切り替えて「各種申請」からご提出いただけます。
                </div>
              ) : (
                <AdminYearEndAdjustmentTab
                  requests={data.yearEndAdjustments}
                  onDecide={decideYearEndAdjustment}
                  employeeAccounts={employeeAccounts}
                  onNotifyEmployee={notifyEmployeeUser}
                  isMasterAdmin={session.role === 'master_admin'}
                  isDesktop={isDesktop}
                />
              )}
              <AdminProfileRequestsTab
                requests={data.profileUpdateRequests}
                onDecide={decideProfileUpdateRequest}
                isDesktop={isDesktop}
              />
          </div>
        )}
        {effectiveTopTab === 'payroll' && (
          showStaffScreens ? (
            <div className="space-y-5">
              <PayslipView records={data.payrollRecords.filter((p) => p.employeeId === employeeId && p.status === 'published')} employeeName={session.name} />
              <BonusSlipView records={(data.bonusRecords || []).filter((b) => b.employeeId === employeeId && b.status === 'published')} employeeName={session.name} />
            </div>
          ) : (
            <div className="space-y-5">
              {/* 給与明細・賞与明細はマスター管理者だけが扱う
                  （supabase/72_payslip_master_only.sql）。
                  それ以外の管理者には交通費精算だけを出す。 */}
              {session.role !== 'master_admin' && (
                <div className="rounded-2xl border border-amber-200 bg-amber-50 px-5 py-4 text-[12px] text-amber-800">
                  <div className="font-bold mb-1">給与明細・賞与明細はマスター管理者が扱います</div>
                  この画面では交通費精算の確認のみ行えます。給与・賞与の内容について確認が必要なときは、
                  総務担当へご依頼ください。ご自身の明細は「自分の勤怠」に切り替えるとご覧になれます。
                </div>
              )}
              {session.role === 'master_admin' && (
              <PayrollAdminTab
                employeeAccounts={employeeAccounts}
                records={data.records}
                payrollRecords={data.payrollRecords}
                commuteExpenseClaims={data.commuteExpenseClaims}
                monthlyConfirmations={data.monthlyConfirmations}
                groupAttendanceSchedules={data.groupLeaveSchedules}
                employeeAttendanceSchedules={data.employeeAttendanceSchedules}
                leaveRequests={data.leaveRequests}
                settings={data.settings}
                session={session}
                onRefresh={refreshData}
                onSaveDraft={savePayrollDraft}
                onPublish={publishPayroll}
                onUnpublish={unpublishPayroll}
                isMasterAdmin={session.role === 'master_admin'}
                onUpdateWage={updateEmployeeProfile}
                isDesktop={isDesktop}
              />
              )}
              {session.role === 'master_admin' && (
              <BonusAdminTab
                employeeAccounts={employeeAccounts}
                bonusRecords={data.bonusRecords || []}
                tableReady={data.bonusTableReady !== false}
                session={session}
                onSave={saveBonus}
                onPublish={publishBonus}
                onUnpublish={unpublishBonus}
                isMasterAdmin={session.role === 'master_admin'}
                onDelete={deleteBonus}
                isDesktop={isDesktop}
              />
              )}
              <AdminCommuteExpenseClaimsTab
                isMasterAdmin={session.role === 'master_admin'}
                claims={data.commuteExpenseClaims}
                onCancelApproval={cancelCommuteExpenseApproval}
                onDecide={decideCommuteExpenseClaim}
                isDesktop={isDesktop}
              />
            </div>
          )
        )}
        {effectiveTopTab === 'attendance' && (showStaffScreens ? (
          <div className="space-y-5">
            <div className={`flex items-center bg-white rounded-2xl border border-slate-200 p-1.5 text-[12.5px] font-bold shadow-sm ${isDesktop ? 'max-w-md' : ''}`}>
              {employeeTabItems.map((t) => {
                const Icon = t.icon;
                return (
                  <button
                    key={t.key}
                    onClick={() => setEmployeeTab(t.key)}
                    className={`flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-xl transition-colors ${
                      activeEmployeeTab === t.key ? 'bg-slate-950 text-white' : 'text-slate-500 hover:bg-slate-50'
                    }`}
                  >
                    <Icon size={14} className={activeEmployeeTab === t.key ? 'text-white' : 'text-slate-400'} />
                    {t.label}
                  </button>
                );
              })}
            </div>

            {activeEmployeeTab === 'performance' && PerformanceFormatSection && (
              <PerformanceFormatSection
                employeeId={employeeId}
                session={session}
                settings={data.settings}
                onNotifyAdmin={notifyAdmin}
                isDesktop={isDesktop}
              />
            )}

            {activeEmployeeTab === 'shifttable' && (
              <MyShiftCalendar
                employeeId={employeeId}
                assignments={(data.shiftAssignments || []).filter((a) => a.employeeId === employeeId)}
                shiftRequests={(data.shiftRequests || []).filter((r) => r.employeeId === employeeId)}
                isDesktop={isDesktop}
              />
            )}

            {activeEmployeeTab === 'attendance' && needsMonthlyConfirm && (
              <MonthlyConfirmReminderCard
                targetMonth={commuteClaimTargetMonthKey}
                onOpen={() => openRequest('monthly')}
              />
            )}
            {activeEmployeeTab === 'attendance' && (
              <EmployeeView
                now={now}
                todayRecord={todayRecord}
                onClockIn={handleClockIn}
                todayShift={shiftForDate(data.shiftRequests, employeeId, today, data.shiftAssignments)}
                onClockOut={handleClockOut}
                onBreakStart={handleBreakStart}
                onBreakEnd={handleBreakEnd}
                geoStatus={geo.status}
                historyDates={historyDates}
                records={employeeRecords}
                corrections={myCorrections}
                onOpenCorrection={(dateKey) => setCorrectionModal(dateKey)}
                notifications={data.notifications.filter((n) => n.toEmployeeId === employeeId)}
                onMarkNotificationRead={async (id) => { await markNotificationRead(id); await refreshData(); }}
                onMarkAllNotificationsRead={async (ids) => { await markNotificationsRead(ids); await refreshData(); }}
                schedulePatterns={schedulePatterns}
                activePatternNo={activePatternNo}
                onSetActivePattern={setActivePatternNo}
                onSavePatterns={savePatterns}
                needsCommuteClaimReminder={needsCommuteClaimReminder}
                commuteClaimTargetMonth={commuteClaimTargetMonthKey}
                onGoToCommuteClaim={() => openRequest('commute')}
                isDesktop={isDesktop}
              />
            )}
          </div>
        ) : (
          <AdminView
            data={data}
            employeeAccounts={employeeAccounts}
            session={session}
            onNavigateTop={setTopTab}
            requestedAdminTab={pendingAdminTab}
            onConsumeRequestedAdminTab={() => setPendingAdminTab(null)}
            onDecide={decideCorrection}
            onDecideLeave={decideLeaveRequest}
            onDecideCommute={decideCommuteExpenseClaim}
            onNotifyEmployee={notifyEmployeeUser}
            onSaveShiftPeriod={saveShiftPeriod}
            onAddAccount={handleAddAccount}
            onDeleteAccount={handleDeleteAccount}
            onResetPassword={handleResetPassword}
            onFetchMyNumber={fetchMyNumber}
            onListMyNumbers={listMyNumbers}
            onDeleteMyNumber={deleteMyNumber}
            onSaveMyNumber={saveMyNumber}
            onUpdateDates={updateEmployeeDates}
            onUpdateAdminAccess={updateAdminAccess}
            onSaveAdminNotifyEmail={saveAdminNotifyEmail}
            onSaveGroupFormats={saveGroupFormats}
            onSaveZtvRates={saveZtvRates}
            onSavePerfDeadline={savePerfDeadlineDay}
            onSaveShiftAlias={saveShiftNameAlias}
            onDeleteShiftAlias={deleteShiftNameAlias}
            onAnnounceShift={announceShift}
            onChangeLoginEmail={handleChangeLoginEmail}
            onDecideMonthlyConfirm={decideMonthlyAttendanceConfirmation}
            onCancelMonthlyConfirm={cancelMonthlyAttendanceConfirmation}
            onSaveGroupLeave={saveGroupLeaveSchedule}
            onSaveEmployeeAttendance={saveEmployeeAttendanceSchedule}
            onAdminUpdateAttendance={adminUpdateAttendance}
            onAdminUpdateAttendanceBatch={adminUpdateAttendanceBatch}
            onDeleteAttendance={adminDeleteAttendance}
            onRefresh={refreshData}
            isDesktop={isDesktop}
          />
        ))}
      </main>
      {correctionModal && (
        <CorrectionModal
          dateKey={correctionModal}
          record={employeeRecords[correctionModal]}
          onClose={() => setCorrectionModal(null)}
          onSubmit={submitCorrection}
        />
      )}
      {leaveModalOpen && (
        <LeaveRequestModal
          leaveRemaining={myLeaveBalance.remaining}
          balancePending={myLeaveBalance.pendingCarryover}
          onClose={() => setLeaveModalOpen(false)}
          onSubmit={submitLeaveRequest}
        />
      )}
      <ToastView toast={toast} />
    </div>
  );
}

// 2段階認証のコード入力画面。パスワードが通ったあとに出る。
function MfaChallengeScreen({ onVerify, onCancel, toast }) {
  const [code, setCode] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  const submit = async (e) => {
    e.preventDefault();
    const clean = code.replace(/\s/g, '');
    if (clean.length < 6) return;
    setBusy(true); setError('');
    try {
      await onVerify(clean);
    } catch (err) {
      setError('コードが正しくありません。アプリの表示をもう一度ご確認ください');
      setCode('');
      setBusy(false);
    }
  };

  return (
    <div className="min-h-[100dvh] bg-white flex items-center justify-center px-4 py-[max(1rem,env(safe-area-inset-top))] font-sans">
      <div className="w-full max-w-[360px]">
        <div className="text-center mb-8">
          <div className="w-14 h-14 rounded-2xl bg-slate-950 flex items-center justify-center mx-auto mb-4">
            <ShieldCheck size={26} className="text-white" strokeWidth={2.4} />
          </div>
          <h1 className="text-slate-800 font-bold text-[19px] tracking-tight">2段階認証</h1>
          <p className="text-slate-500 text-[13px] mt-1.5 leading-relaxed">
            スマートフォンのアプリに表示されている<br />6桁のコードを入力してください
          </p>
        </div>

        <form onSubmit={submit} className="space-y-3">
          <input
            value={code}
            onChange={(e) => setCode(e.target.value)}
            inputMode="numeric"
            autoComplete="one-time-code"
            autoFocus
            placeholder="000000"
            className="w-full border border-slate-200 rounded-xl px-3 py-3.5 font-mono text-center text-[22px] tracking-[0.3em]"
          />
          {error && <div className="rounded-lg bg-rose-50 px-3 py-2 text-[12px] text-rose-700">{error}</div>}
          <button
            type="submit"
            disabled={busy || code.replace(/\s/g, '').length < 6}
            className="w-full py-3 rounded-xl bg-slate-900 disabled:bg-slate-200 text-white text-[13.5px] font-bold"
          >
            {busy ? '確認中…' : 'ログイン'}
          </button>
          <button
            type="button"
            onClick={onCancel}
            className="w-full py-2.5 text-[12.5px] font-medium text-slate-400"
          >
            ログイン画面に戻る
          </button>
        </form>

        <p className="mt-6 text-[11.5px] leading-relaxed text-slate-400 text-center">
          スマートフォンを機種変更・紛失された場合は、マスター管理者にご連絡ください。
        </p>
      </div>
      {toast}
    </div>
  );
}

function LoginScreen({ onLogin, toast, linkError = '', onClearLinkError }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [forgotMode, setForgotMode] = useState(false);
  const [forgotInput, setForgotInput] = useState('');
  const [forgotSending, setForgotSending] = useState(false);
  const [forgotDone, setForgotDone] = useState(false);

  const submit = (e) => {
    e.preventDefault();
    if (username.trim().length > 0 && password.length > 0) {
      onLogin(username.trim(), password);
    }
  };

  const submitForgot = async (e) => {
    e.preventDefault();
    if (!forgotInput.trim()) return;
    setForgotSending(true);
    const email = usernameToEmail(forgotInput.trim());
    try {
      await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: typeof window !== 'undefined' ? window.location.origin : undefined,
      });
    } catch (e) {
      console.error('パスワード再設定メールの送信に失敗しました', e);
    }
    setForgotSending(false);
    setForgotDone(true);
  };

  return (
    <div className="min-h-[100dvh] bg-white flex items-center justify-center px-4 py-[max(1rem,env(safe-area-inset-top))] font-sans">
      <div className="w-full max-w-[360px]">
        <div className="text-center mb-8">
          <div className="w-14 h-14 rounded-2xl bg-slate-950 flex items-center justify-center mx-auto mb-4 shadow-lg shadow-amber-200">
            <Clock size={26} className="text-white" strokeWidth={2.4} />
          </div>
          <h1 className="text-slate-800 font-bold text-[21px] tracking-tight">Brown Work</h1>
          <p className="text-slate-500 text-[13px] mt-1.5">勤怠・シフト・申請をひとつに</p>
        </div>
        {/* メールのリンクから戻ってきて失敗していたときの案内。
            以前は何も出ず、理由の分からないままログイン画面になっていた */}
        {linkError && (
          <div className="mb-5 rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-left">
            <div className="text-[12.5px] font-bold text-rose-700 mb-1">パスワードの再設定ができませんでした</div>
            <div className="text-[11.5px] leading-relaxed text-rose-700">{linkError}</div>
            <button
              type="button"
              onClick={() => { onClearLinkError?.(); setForgotMode(true); }}
              className="mt-2 text-[11.5px] font-bold text-rose-700 underline"
            >
              もう一度やり直す
            </button>
          </div>
        )}
        <div className="hidden">
        </div>

        {!forgotMode ? (
          <>
            <form onSubmit={submit} className="bg-white rounded-2xl p-6 space-y-4 border-2 border-slate-200 shadow-lg">
              <div>
                <label className="block text-[12.5px] font-bold text-slate-800 mb-1.5">ユーザー名（メールアドレスでも可）</label>
                <div className="flex items-center border-2 border-slate-200 rounded-xl px-3.5 gap-2 focus-within:border-slate-900 transition-colors">
                  <User size={16} className="text-slate-400 shrink-0" />
                  <input
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="w-full py-3 text-[15px] outline-none bg-transparent text-slate-800"
                    placeholder="ユーザー名またはメールアドレス"
                    autoCapitalize="none"
                    autoFocus
                    required
                  />
                </div>
              </div>
              <div>
                <label className="block text-[12.5px] font-bold text-slate-800 mb-1.5">パスワード</label>
                <div className="flex items-center border-2 border-slate-200 rounded-xl px-3.5 gap-2 focus-within:border-slate-900 transition-colors">
                  <Lock size={16} className="text-slate-400 shrink-0" />
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full py-3 text-[15px] outline-none bg-transparent text-slate-800"
                    placeholder="パスワードを入力"
                    required
                  />
                </div>
              </div>
              <button
                type="submit"
                className="w-full py-3.5 rounded-xl bg-slate-950 text-white text-[15px] font-bold flex items-center justify-center gap-2 shadow-md shadow-amber-200 active:brightness-95 transition-all mt-2"
              >
                <LogIn size={17} strokeWidth={2.4} />
                ログイン
              </button>
            </form>
            <button
              onClick={() => { setForgotMode(true); setForgotDone(false); setForgotInput(''); }}
              className="w-full text-center mt-4 text-[12.5px] font-bold text-slate-500"
            >
              パスワードをお忘れですか？
            </button>
          </>
        ) : (
          <div className="bg-white rounded-2xl p-6 space-y-4 border-2 border-slate-200 shadow-lg">
            <h2 className="font-bold text-[15px] text-slate-800">パスワードの再設定</h2>
            {forgotDone ? (
              <>
                <div className="bg-emerald-50 border border-emerald-200 rounded-xl px-4 py-3 text-[12.5px] text-emerald-700">
                  登録されているメールアドレス宛に、パスワード再設定用のメールをお送りしました（届くまで数分かかる場合があります）。
                </div>
                <div className="text-[11px] text-slate-400">
                  ※ユーザー名がメールアドレス形式で登録されている場合のみ届きます。短いID（例：tanaka）で登録されている場合は、管理者にパスワードのリセットを依頼してください。
                </div>
                <button onClick={() => setForgotMode(false)} className="w-full py-2.5 rounded-lg border-2 border-slate-200 text-[13.5px] font-bold text-slate-600">
                  ログイン画面に戻る
                </button>
              </>
            ) : (
              <form onSubmit={submitForgot} className="space-y-4">
                <div>
                  <label className="block text-[12.5px] font-bold text-slate-800 mb-1.5">ユーザー名またはメールアドレス</label>
                  <input
                    value={forgotInput}
                    onChange={(e) => setForgotInput(e.target.value)}
                    className="w-full border-2 border-slate-200 rounded-xl px-3.5 py-3 text-[15px] outline-none focus:border-slate-900"
                    placeholder="ユーザー名またはメールアドレス"
                    autoCapitalize="none"
                    autoFocus
                    required
                  />
                </div>
                <div className="text-[11px] text-slate-400">メールアドレスでご登録の方のみご利用いただけます。</div>
                <button type="submit" disabled={forgotSending} className="w-full py-3 rounded-xl bg-slate-950 disabled:bg-slate-300 text-white text-[14px] font-bold">
                  {forgotSending ? '送信中…' : '再設定メールを送る'}
                </button>
                <button type="button" onClick={() => setForgotMode(false)} className="w-full text-center text-[12.5px] font-bold text-slate-500">
                  ログイン画面に戻る
                </button>
              </form>
            )}
          </div>
        )}
      </div>
      <ToastView toast={toast} />
    </div>
  );
}

