// パスワード入力欄。
// type="password" は日本語入力と相性が悪く、スマートフォンによっては
// 1文字ごとにキーボードが閉じてしまう。そのため通常のテキスト欄として扱い、
// CSSで伏せ字にする（対応していない端末では従来どおり type="password"）。
const SUPPORTS_TEXT_SECURITY =
  typeof CSS !== 'undefined' &&
  typeof CSS.supports === 'function' &&
  (CSS.supports('-webkit-text-security', 'disc') || CSS.supports('text-security', 'disc'));

function PasswordInput({ inputRef, id, name, className, autoFocus }) {
  const [shown, setShown] = useState(false);
  const masked = !shown && SUPPORTS_TEXT_SECURITY;
  return (
    <div className="flex items-center gap-2">
      <input
        ref={inputRef}
        id={id}
        name={name}
        type={SUPPORTS_TEXT_SECURITY || shown ? 'text' : 'password'}
        autoComplete="off"
        autoCapitalize="off"
        autoCorrect="off"
        spellCheck={false}
        defaultValue=""
        autoFocus={autoFocus}
        style={masked ? { WebkitTextSecurity: 'disc', textSecurity: 'disc' } : undefined}
        className={className}
        required
      />
      <button
        type="button"
        onClick={() => setShown((v) => !v)}
        className="shrink-0 text-[11px] font-bold text-slate-500 border border-slate-200 rounded-xl px-3 py-3"
      >
        {shown ? '隠す' : '表示'}
      </button>
    </div>
  );
}

// パスワードは半角の英数字・記号のみ受け付ける
// （日本語入力のまま打つと全角文字が混ざり、次回ログインできなくなるため）
const isHalfWidthPassword = (v) => /^[\x21-\x7e]+$/.test(String(v || ''));

// ---- パスワードの決まり ----
// Supabase側の設定（Authentication のパスワード設定）と必ず揃えること。
// 片方だけ変えると、画面では通るのにサーバーで弾かれ、分かりにくいエラーになる。
//   最低文字数：8
//   必要な文字：数字・英大文字・英小文字
const PASSWORD_MIN_LENGTH = 8;
const PASSWORD_RULE_TEXT = '8文字以上・数字と英大小文字';
const PASSWORD_RULE_HINT = `パスワードは${PASSWORD_MIN_LENGTH}文字以上で、数字・英大文字・英小文字をそれぞれ1つ以上入れてください。`;

// 問題があればその理由を返す。問題なければ null。
function passwordProblem(value) {
  const v = String(value || '');
  if (v.length < PASSWORD_MIN_LENGTH) return `パスワードは${PASSWORD_MIN_LENGTH}文字以上にしてください`;
  if (!/[0-9]/.test(v)) return 'パスワードに数字を1つ以上入れてください';
  if (!/[A-Z]/.test(v)) return 'パスワードに英大文字（A〜Z）を1つ以上入れてください';
  if (!/[a-z]/.test(v)) return 'パスワードに英小文字（a〜z）を1つ以上入れてください';
  return null;
}
const isPasswordOk = (v) => passwordProblem(v) === null;

// ---- 初回ログイン：パスワード変更（必須） ----
function FirstLoginPasswordScreen({ session, toast, onDone, onLogout }) {
  // 入力欄はReactで値を持たない（非制御）。
  // 1文字ごとに再描画すると、スマートフォンでキーボードが閉じてしまうため。
  const passwordRef = useRef(null);
  const confirmRef = useRef(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const submit = async (e) => {
    e.preventDefault();
    setError('');
    const password = passwordRef.current?.value || '';
    const confirmPassword = confirmRef.current?.value || '';
    const pwProblem = passwordProblem(password);
    if (pwProblem) {
      setError(pwProblem);
      return;
    }
    if (!isHalfWidthPassword(password)) {
      setError('パスワードは半角の英数字・記号でご入力ください（日本語入力をオフにしてください）');
      return;
    }
    if (password !== confirmPassword) {
      setError('確認用のパスワードが一致しません');
      return;
    }
    setSaving(true);
    const { error: updateError } = await supabase.auth.updateUser({ password });
    if (updateError) {
      setError('パスワードの変更に失敗しました。時間をおいて再度お試しください。');
      setSaving(false);
      return;
    }
    const { error: flagError } = await supabase
      .from('employees')
      .update({ must_change_password: false })
      .eq('id', session.id);
    setSaving(false);
    if (flagError) {
      console.error('must_change_password の更新に失敗しました', flagError);
      setError(`パスワードは変更できましたが、設定の保存に失敗しました：${flagError.message}`);
      return;
    }
    await onDone();
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans flex items-start justify-center px-4 py-8">
      <div className="w-full max-w-[400px]">
        <div className="bg-white rounded-[24px] border border-slate-200 shadow-sm p-7 space-y-5">
          <div className="flex items-center gap-2.5">
            <div className="w-10 h-10 rounded-xl bg-slate-900 flex items-center justify-center shrink-0">
              <Lock size={18} className="text-white" />
            </div>
            <div>
              <h1 className="font-bold text-[16px] leading-tight">パスワードの設定</h1>
              <div className="text-[11.5px] text-slate-400">{session.name} 様</div>
            </div>
          </div>

          <div className="bg-amber-50 border border-amber-200 rounded-xl px-3.5 py-3 text-[12px] text-amber-800">
            仮パスワードでログインしています。安全にご利用いただくため、ご自身のパスワードを設定してください。<br />
            半角の英数字でご入力ください（日本語入力はオフにしてください）。
          </div>

          <form onSubmit={submit} className="space-y-4">
            <Field label={`新しいパスワード（${PASSWORD_RULE_TEXT}）`}>
              <PasswordInput
                inputRef={passwordRef}
                id="new-password"
                name="new-password"
                className="w-full border-2 border-slate-200 rounded-xl px-3.5 py-3 text-[16px] outline-none focus:border-slate-900"
              />
            </Field>
            <Field label="新しいパスワード（確認）">
              <PasswordInput
                inputRef={confirmRef}
                id="new-password-confirm"
                name="new-password-confirm"
                className="w-full border-2 border-slate-200 rounded-xl px-3.5 py-3 text-[16px] outline-none focus:border-slate-900"
              />
            </Field>
            {error && <div className="text-[12.5px] text-rose-600">{error}</div>}
            <button type="submit" disabled={saving} className="w-full py-3 rounded-xl bg-slate-950 disabled:bg-slate-300 text-white text-[14px] font-bold">
              {saving ? '設定中…' : 'このパスワードに変更する'}
            </button>
          </form>

          <button onClick={onLogout} className="w-full text-[11.5px] text-slate-400">
            ログアウトする
          </button>
        </div>
      </div>
      <ToastView toast={toast} />
    </div>
  );
}

// ---- 初回ログイン：個人情報の入力依頼 ----
function onlyDigits(v) { return String(v || '').replace(/[^0-9]/g, ''); }
function isEmailLike(v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v || '').trim()); }
function toKatakana(v) { return String(v || '').replace(/[ぁ-ゖ]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) + 0x60)); }

