// 口座情報は専用の入力欄（銀行コードと銀行名を相互に補完する）で扱う
const BANK_ACCOUNT_FIELDS = [
  { key: 'bankName', label: '銀行名' },
  { key: 'branchName', label: '支店名' },
  { key: 'accountType', label: '預金種別' },
  { key: 'accountNumber', label: '口座番号' },
  { key: 'accountHolder', label: '口座名義（カナ）' },
];

const PROFILE_SETUP_ALL_FIELDS = PROFILE_SETUP_SECTIONS.flatMap((s) => s.fields);

// 日本語入力の変換中に値を書き換えると、文字が二重に入力されてしまう。
// 変換が終わってから整形する入力欄。
function FormattedInput({ value, onValueChange, format, blurFormat, ...rest }) {
  const composing = useRef(false);
  const apply = (raw, fn) => onValueChange(fn ? fn(raw) : raw);
  return (
    <input
      {...rest}
      value={value}
      onChange={(e) => {
        const raw = e.target.value;
        if (composing.current) onValueChange(raw);
        else apply(raw, format);
      }}
      onCompositionStart={() => { composing.current = true; }}
      onCompositionEnd={(e) => { composing.current = false; apply(e.target.value, format); }}
      onBlur={(e) => { composing.current = false; apply(e.target.value, blurFormat || format); }}
    />
  );
}

// 電話番号にハイフンを入れる。
// 市外局番は桁数が地域ごとに異なるため、区切りが明らかな番号だけ自動で整える。
// すでにハイフンが入っている場合は、そのままの入力を尊重する。
function formatPhone(v) {
  const raw = String(v || '');
  if (raw.includes('-')) return raw;
  const d = onlyDigits(raw);
  if (/^0[5789]0\d{8}$/.test(d)) return `${d.slice(0, 3)}-${d.slice(3, 7)}-${d.slice(7)}`;
  if (/^(0120|0800|0570)\d{6}$/.test(d)) return `${d.slice(0, 4)}-${d.slice(4, 7)}-${d.slice(7)}`;
  if (/^0[36]\d{8}$/.test(d)) return `${d.slice(0, 2)}-${d.slice(2, 6)}-${d.slice(6)}`;
  return raw;
}

// ハイフン入りで入力されているかを確認する
function checkPhone(v) {
  if (onlyDigits(v).length < 10) return '電話番号をご確認ください';
  if (!String(v).includes('-')) return 'ハイフンを入れてご入力ください（例）090-1234-5678）';
  return '';
}

// 郵便番号を 123-4567 の形にそろえる
function formatPostalCode(v) {
  const d = onlyDigits(v).slice(0, 7);
  return d.length > 3 ? `${d.slice(0, 3)}-${d.slice(3)}` : d;
}

// ---- 郵便番号から住所を自動で入力する ----
// public/zip/ に置いた一覧（先頭2桁ごとに分割）を、必要な分だけ読み込む。
// 外部のサービスへは送信しないため、住所の情報が社外に出ることはない。
const zipChunkCache = {};

const loadZipChunk = (prefix) => {
  if (!zipChunkCache[prefix]) {
    zipChunkCache[prefix] = fetch(`/zip/${prefix}.json`)
      .then((r) => (r.ok ? r.json() : {}))
      .catch(() => ({}));
  }
  return zipChunkCache[prefix];
};

// 郵便番号が7桁になったら、住所欄に「都道府県＋市区町村＋町名」を入れる。
// 番地などを入力済みの場合は、先頭の住所だけを差し替えて残りを保つ。
function usePostalAutoFill(postalCode, setForm, addressKey = 'address') {
  const lastBase = useRef('');
  const [notice, setNotice] = useState('');

  useEffect(() => {
    const digits = onlyDigits(postalCode);
    if (digits.length !== 7) { setNotice(''); return; }
    let cancelled = false;
    loadZipChunk(digits.slice(0, 2)).then((map) => {
      if (cancelled) return;
      const base = map ? map[digits] : '';
      if (!base) { setNotice('この郵便番号に該当する住所が見つかりませんでした。住所は手入力してください。'); return; }
      setNotice('');
      setForm((prev) => {
        const current = String(prev[addressKey] || '').trim();
        const prevBase = lastBase.current;
        let next;
        if (!current) next = base;
        else if (prevBase && current.startsWith(prevBase)) next = base + current.slice(prevBase.length);
        else return prev; // 手入力済みの住所は書き換えない
        lastBase.current = base;
        return next === prev[addressKey] ? prev : { ...prev, [addressKey]: next };
      });
      lastBase.current = base;
    });
    return () => { cancelled = true; };
  }, [postalCode, setForm, addressKey]);

  return notice;
}

// ---- 金融機関マスター（全国銀行協会のコード表）----
// public/zengin/ に置いた一覧を、必要になった時だけ読み込む。
const zenginCache = { banks: null, branches: null, banksPromise: null, branchesPromise: null };

const loadZenginBanks = () => {
  if (zenginCache.banks) return Promise.resolve(zenginCache.banks);
  if (!zenginCache.banksPromise) {
    zenginCache.banksPromise = fetch('/zengin/banks.json')
      .then((r) => r.json())
      .then((j) => { zenginCache.banks = j; return j; })
      .catch(() => ({}));
  }
  return zenginCache.banksPromise;
};

const loadZenginBranches = () => {
  if (zenginCache.branches) return Promise.resolve(zenginCache.branches);
  if (!zenginCache.branchesPromise) {
    zenginCache.branchesPromise = fetch('/zengin/branches.json')
      .then((r) => r.json())
      .then((j) => { zenginCache.branches = j; return j; })
      .catch(() => ({}));
  }
  return zenginCache.branchesPromise;
};

// 表記ゆれを吸収して比較するためのキー（全角半角・空白・株式会社の有無）
const bankKey = (v) => String(v || '').normalize('NFKC').replace(/[\s　]/g, '').replace(/^株式会社/, '').replace(/株式会社$/, '').toLowerCase();
// 「京都銀行」→「京都」のように、種別を外した短い名前
const bankShortKey = (v) => bankKey(v).replace(/(銀行|信用金庫|信用組合|農業協同組合連合会|農業協同組合|労働金庫|漁業協同組合連合会|漁業協同組合|中央金庫)$/, '');
const branchShortKey = (v) => bankKey(v).replace(/(支店|出張所|営業部|営業所|支所|本所|代理店)$/, '');

// 名前からコードを引く。候補が1つに絞れた時だけ返す。
function lookupCode(entries, input, shortKeyOf) {
  const key = bankKey(input);
  if (!key) return '';
  const exact = entries.filter(([, name]) => bankKey(name) === key);
  if (exact.length === 1) return exact[0][0];
  if (exact.length > 1) return '';
  const short = shortKeyOf(input);
  if (!short) return '';
  const loose = entries.filter(([, name]) => shortKeyOf(name) === short);
  return loose.length === 1 ? loose[0][0] : '';
}

function BankAccountFields({ form, setForm }) {
  const [banks, setBanks] = useState(null);
  const [branches, setBranches] = useState(null);

  useEffect(() => { loadZenginBanks().then(setBanks); }, []);
  useEffect(() => {
    if (!form.bankCode || branches) return;
    loadZenginBranches().then(setBranches);
  }, [form.bankCode, branches]);

  const bankEntries = useMemo(() => (banks ? Object.entries(banks) : []), [banks]);
  const branchEntries = useMemo(() => {
    const map = branches && form.bankCode ? branches[form.bankCode] : null;
    return map ? Object.entries(map) : [];
  }, [branches, form.bankCode]);

  const patch = (next) => setForm((prev) => ({ ...prev, ...next }));

  const onBankName = (raw) => {
    const code = bankEntries.length > 0 ? lookupCode(bankEntries, raw, bankShortKey) : '';
    const bankChanged = code && code !== form.bankCode;
    patch({
      bankName: raw,
      ...(code ? { bankCode: code } : {}),
      ...(bankChanged ? { branchCode: '', branchName: '' } : {}),
    });
    if (code) loadZenginBranches().then(setBranches);
  };

  // 値の整形は FormattedInput 側で行う（日本語入力の変換中は保留される）
  const onBranchCode = (value) => {
    const code = onlyDigits(value).slice(0, 3);
    const map = branches && form.bankCode ? branches[form.bankCode] : null;
    const name = map && map[code] ? map[code] : '';
    patch({ branchCode: value, ...(name ? { branchName: name } : {}) });
  };

  const onBranchName = (raw) => {
    const code = branchEntries.length > 0 ? lookupCode(branchEntries, raw, branchShortKey) : '';
    patch({ branchName: raw, ...(code ? { branchCode: code } : {}) });
  };

  const inputClass = 'w-full h-[44px] leading-[20px] border-2 border-slate-200 rounded-xl px-3.5 text-[14px] bg-white outline-none focus:border-slate-900';
  const monoClass = `${inputClass} font-mono`;
  const bankResolved = !!(form.bankCode && banks && banks[form.bankCode]);
  const branchResolved = !!(form.branchCode && branchEntries.some(([c]) => c === form.branchCode));

  return (
    <div className="space-y-3.5">
      <div className="text-[12px] font-bold text-slate-500 border-b border-slate-100 pb-2">口座情報（給与振込先）</div>
      <div className="text-[11.5px] text-slate-400 -mt-1">
        ご本人名義の口座をご登録ください。銀行名は候補から選べます。支店はコードと名称のどちらか一方を入力すると、もう一方が自動で入ります。
      </div>

      <Field label="銀行名">
        <FormattedInput
          name="bankName" autoComplete="off" list="zengin-banks"
          value={form.bankName} onValueChange={onBankName}
          placeholder="例）京都銀行" className={inputClass}
        />
      </Field>
      {form.bankName && !bankResolved && (
        <div className="text-[11.5px] text-amber-700">銀行が特定できませんでした。候補の一覧からお選びください。</div>
      )}

      <div className="grid grid-cols-[110px_1fr] gap-3">
        <Field label="支店コード">
          <FormattedInput
            name="branchCode" autoComplete="off" inputMode="numeric"
            value={form.branchCode} onValueChange={onBranchCode}
            format={(v) => onlyDigits(v).slice(0, 3)}
            placeholder="111" className={monoClass}
          />
        </Field>
        <Field label="支店名">
          <FormattedInput
            name="branchName" autoComplete="off" list="zengin-branches"
            value={form.branchName} onValueChange={onBranchName}
            placeholder={bankResolved ? '例）四条支店' : '先に銀行をご入力ください'}
            className={inputClass}
          />
        </Field>
      </div>
      {form.branchName && !branchResolved && (
        <div className="text-[11.5px] text-amber-700">支店が特定できませんでした。候補から選ぶか、支店コード（3桁）をご入力ください。</div>
      )}

      <datalist id="zengin-banks">
        {bankEntries.map(([code, name]) => <option key={code} value={name}>{code}</option>)}
      </datalist>
      <datalist id="zengin-branches">
        {branchEntries.map(([code, name]) => <option key={code} value={name}>{code}</option>)}
      </datalist>

      <Field label="預金種別">
        <select
          name="accountType" value={form.accountType}
          onChange={(e) => patch({ accountType: e.target.value })}
          className={inputClass}
        >
          <option value="普通">普通</option>
          <option value="当座">当座</option>
        </select>
      </Field>
      <Field label="口座番号">
        <FormattedInput
          name="accountNumber" autoComplete="off" inputMode="numeric"
          value={form.accountNumber}
          onValueChange={(v) => patch({ accountNumber: v })}
          format={(v) => onlyDigits(v).slice(0, 10)}
          placeholder="例）1234567" className={monoClass}
        />
      </Field>
      <Field label="口座名義（カナ）">
        <FormattedInput
          name="accountHolder" autoComplete="off"
          value={form.accountHolder}
          onValueChange={(v) => patch({ accountHolder: v })}
          blurFormat={toKatakana}
          placeholder="例）タナカ ハナコ" className={inputClass}
        />
      </Field>
    </div>
  );
}

function ProfileSetupScreen({ session, toast, onSave, onLogout }) {
  const [form, setForm] = useState(() => {
    const init = {};
    PROFILE_SETUP_ALL_FIELDS.forEach((f) => {
      init[f.key] = session[f.key] || (f.type === 'select' ? f.options[0] : '');
    });
    init.spouseStatus = session.spouseStatus || '無';
    init.householderRelation = session.householderRelation || '';
    init.bankCode = session.bankCode || '';
    init.bankName = session.bankName || '';
    init.branchCode = session.branchCode || '';
    init.branchName = session.branchName || '';
    init.accountType = session.accountType || '普通';
    init.accountNumber = session.accountNumber || '';
    init.accountHolder = session.accountHolder || '';
    return init;
  });
  const [myNumber, setMyNumber] = useState('');
  const [myNumberShown, setMyNumberShown] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  // ログイン案内を送ったアドレス（ログインID）
  const loginEmail = String(session.username || '').includes('@') ? session.username : '';
  const [useLoginEmail, setUseLoginEmail] = useState(() => !!loginEmail && session.contactEmail === loginEmail);
  const toggleLoginEmail = (checked) => {
    setUseLoginEmail(checked);
    setForm((prev) => ({ ...prev, contactEmail: checked ? loginEmail : '' }));
  };

  // 郵便番号を入れたら住所を自動で入力する
  const postalNotice = usePostalAutoFill(form.postalCode, setForm);

  // 世帯主がご本人かどうか
  const [householderIsSelf, setHouseholderIsSelf] = useState(
    () => !!session.name && session.householderName === session.name
  );
  const toggleHouseholderSelf = (checked) => {
    setHouseholderIsSelf(checked);
    setForm((prev) => ({
      ...prev,
      householderName: checked ? prev.name : '',
      householderRelation: checked ? '本人' : '',
    }));
  };
  // 「本人」にしている間は、お名前の変更を世帯主にも反映する
  useEffect(() => {
    if (!householderIsSelf) return;
    setForm((prev) => (prev.householderName === prev.name ? prev : { ...prev, householderName: prev.name }));
  }, [householderIsSelf, form.name]);

  // 緊急連絡先の方と同居しているかどうか
  const [livesTogether, setLivesTogether] = useState(
    () => !!session.address && session.emergencyContactAddress === session.address
  );
  const toggleLivesTogether = (checked) => {
    setLivesTogether(checked);
    setForm((prev) => ({ ...prev, emergencyContactAddress: checked ? prev.address : '' }));
  };
  // 同居にしている間は、現住所の変更を緊急連絡先の住所にも反映する
  useEffect(() => {
    if (!livesTogether) return;
    setForm((prev) => (prev.emergencyContactAddress === prev.address ? prev : { ...prev, emergencyContactAddress: prev.address }));
  }, [livesTogether, form.address]);

  // 住民票の住所を現住所と同じにするかどうか
  const [useSameAddress, setUseSameAddress] = useState(
    () => !!session.address && session.residentAddress === session.address
  );
  const toggleSameAddress = (checked) => {
    setUseSameAddress(checked);
    setForm((prev) => ({ ...prev, residentAddress: checked ? prev.address : '' }));
  };
  // 「現住所と同じ」にしている間は、現住所の変更を住民票の住所にも反映する
  useEffect(() => {
    if (!useSameAddress) return;
    setForm((prev) => (prev.residentAddress === prev.address ? prev : { ...prev, residentAddress: prev.address }));
  }, [useSameAddress, form.address]);

  // 入力中の整形（日本語入力の変換中は FormattedInput 側で保留される）
  const formatField = (f) => (raw) => {
    let v = raw;
    if (f.digitsOnly) v = onlyDigits(v).slice(0, f.maxLength || 20);
    if (f.postal) v = formatPostalCode(v);
    if (f.phone) v = formatPhone(v);
    return v;
  };
  // 入力が終わってからカタカナへ変換する
  const blurFormatField = (f) => (raw) => {
    const v = formatField(f)(raw);
    return f.katakana ? toKatakana(v) : v;
  };
  const setValue = (f) => (v) => setForm((prev) => ({ ...prev, [f.key]: v }));

  const submit = async (e) => {
    e.preventDefault();
    setError('');

    const missing = PROFILE_SETUP_ALL_FIELDS.filter((f) => f.required && !String(form[f.key] || '').trim());
    if (missing.length > 0) {
      setError(`${missing.map((f) => f.label).join('・')} を入力してください`);
      return;
    }
    for (const f of PROFILE_SETUP_ALL_FIELDS) {
      const v = String(form[f.key] || '').trim();
      if (!v || !f.check) continue;
      const msg = f.check(v);
      if (msg) { setError(`${f.label}：${msg}`); return; }
    }
    const missingBank = BANK_ACCOUNT_FIELDS.filter((f) => !String(form[f.key] || '').trim());
    if (missingBank.length > 0) {
      setError(`${missingBank.map((f) => f.label).join('・')} を入力してください`);
      return;
    }
    if (onlyDigits(form.accountNumber).length < 5) {
      setError('口座番号：口座番号をご確認ください');
      return;
    }
    if (onlyDigits(myNumber).length !== 12) {
      setError('マイナンバーは12桁の数字でご入力ください');
      return;
    }

    setSaving(true);
    const result = await onSave({
      profile: { ...form, birthDate: form.birthDate || null, profileSetupCompleted: true },
      myNumber: onlyDigits(myNumber),
    });
    setSaving(false);
    if (result !== true) {
      setError(typeof result === 'string' ? result : '保存に失敗しました。時間をおいて再度お試しください。');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans flex items-start justify-center px-4 py-8">
      <div className="w-full max-w-[560px]">
        <div className="bg-white rounded-[24px] border border-slate-200 shadow-sm p-7 space-y-5">
          <div className="flex items-center gap-2.5">
            <div className="w-10 h-10 rounded-xl bg-slate-900 flex items-center justify-center shrink-0">
              <User size={18} className="text-white" />
            </div>
            <div>
              <h1 className="font-bold text-[16px] leading-tight">ご登録情報の入力</h1>
              <div className="text-[11.5px] text-slate-400">{session.name} 様</div>
            </div>
          </div>

          <div className="bg-blue-50 border border-blue-200 rounded-xl px-3.5 py-3 text-[12px] text-blue-800">
            パスワードの設定が完了しました。続けて、ご本人の情報をご入力ください。<br />
            すべて入力いただくまで勤怠のご利用を開始できません。入力後の変更は、管理者へ変更申請ができます。
          </div>

          <form onSubmit={submit} className="space-y-6">
            {PROFILE_SETUP_SECTIONS.map((section) => (
              <div key={section.title} className="space-y-3.5">
                <div className="text-[12px] font-bold text-slate-500 border-b border-slate-100 pb-2">{section.title}</div>
                {section.note && <div className="text-[11.5px] text-slate-400 -mt-1">{section.note}</div>}
                {section.fields.map((f) => (
                  <Field key={f.key} label={`${f.label}${f.required || f.readOnly ? '' : '（任意）'}`}>
                    {f.type === 'select' ? (
                      <select
                        name={f.key}
                        value={form[f.key]}
                        onChange={(e) => setValue(f)(e.target.value)}
                        className="w-full h-[44px] border-2 border-slate-200 rounded-xl px-3.5 text-[14px] bg-white outline-none focus:border-slate-900"
                      >
                        {!form[f.key] && <option value="">選択してください</option>}
                        {f.options.map((o) => <option key={o} value={o}>{o}</option>)}
                      </select>
                    ) : (
                      <>
                        <FormattedInput
                          type={f.type || 'text'}
                          name={f.key}
                          autoComplete={f.autoComplete || 'off'}
                          inputMode={f.digitsOnly || f.postal ? 'numeric' : undefined}
                          value={form[f.key]}
                          onValueChange={setValue(f)}
                          format={formatField(f)}
                          blurFormat={blurFormatField(f)}
                          readOnly={f.readOnly || (f.sameAsLogin && useLoginEmail) || (f.sameAsAddress && useSameAddress) || ((f.sameAsSelf || f.lockedWhenSelf) && householderIsSelf) || (f.sameAsHome && livesTogether)}
                          placeholder={f.placeholder}
                          style={{ WebkitAppearance: 'none', appearance: 'none' }}
                          className={`w-full h-[44px] leading-[20px] border-2 border-slate-200 rounded-xl px-3.5 text-[14px] outline-none focus:border-slate-900 ${f.mono || f.type === 'date' ? 'font-mono' : ''} ${f.readOnly || (f.sameAsLogin && useLoginEmail) || (f.sameAsAddress && useSameAddress) || ((f.sameAsSelf || f.lockedWhenSelf) && householderIsSelf) || (f.sameAsHome && livesTogether) ? 'bg-slate-100 text-slate-500' : 'bg-white'}`}
                        />
                        {f.note && <div className="mt-1 text-[11px] text-slate-400">{f.note}</div>}
                        {f.postal && postalNotice && <div className="mt-1 text-[11.5px] text-amber-700">{postalNotice}</div>}
                        {f.sameAsHome && (
                          <label className="flex items-center gap-2 mt-2 text-[12px] text-slate-600 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={livesTogether}
                              onChange={(e) => toggleLivesTogether(e.target.checked)}
                            />
                            <span>同居（現住所と同じ）</span>
                          </label>
                        )}
                        {f.sameAsSelf && (
                          <label className="flex items-center gap-2 mt-2 text-[12px] text-slate-600 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={householderIsSelf}
                              onChange={(e) => toggleHouseholderSelf(e.target.checked)}
                            />
                            <span>ご本人が世帯主</span>
                          </label>
                        )}
                        {f.sameAsAddress && (
                          <label className="flex items-center gap-2 mt-2 text-[12px] text-slate-600 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={useSameAddress}
                              onChange={(e) => toggleSameAddress(e.target.checked)}
                            />
                            <span>現住所と同じ</span>
                          </label>
                        )}
                        {f.sameAsLogin && loginEmail && (
                          <label className="flex items-start gap-2 mt-2 text-[12px] text-slate-600 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={useLoginEmail}
                              onChange={(e) => toggleLoginEmail(e.target.checked)}
                              className="mt-0.5"
                            />
                            <span>
                              ログインID（この案内メールが届いたアドレス）と同じにする
                              <span className="block text-[11px] text-slate-400 font-mono break-all">{loginEmail}</span>
                            </span>
                          </label>
                        )}
                      </>
                    )}
                  </Field>
                ))}
              </div>
            ))}

            <BankAccountFields form={form} setForm={setForm} />

            <div className="space-y-3.5">
              <div className="text-[12px] font-bold text-slate-500 border-b border-slate-100 pb-2">マイナンバー</div>
              <div className="flex items-start gap-2 bg-rose-50 border border-rose-200 rounded-xl px-3.5 py-3 text-[11.5px] text-rose-700">
                <ShieldCheck size={14} className="mt-0.5 shrink-0" />
                <div>
                  <div className="font-bold mb-1">利用目的</div>
                  <ul className="list-disc pl-4 space-y-0.5">
                    {MY_NUMBER_PURPOSES.map((p) => <li key={p}>{p}</li>)}
                  </ul>
                  <div className="mt-1.5">上記の手続きのみに使用します。</div>
                </div>
              </div>
              <Field label="マイナンバー（12桁）">
                <div className="flex items-center gap-2">
                  <FormattedInput
                    type={myNumberShown ? 'text' : 'password'}
                    inputMode="numeric"
                    autoComplete="off"
                    value={myNumber}
                    onValueChange={setMyNumber}
                    format={(v) => onlyDigits(v).slice(0, 12)}
                    placeholder="123456789012"
                    className="flex-1 h-[44px] leading-[20px] border-2 border-slate-200 rounded-xl px-3.5 font-mono text-[14px] bg-white outline-none focus:border-slate-900"
                  />
                  <button
                    type="button"
                    onClick={() => setMyNumberShown((v) => !v)}
                    className="text-[11px] font-bold text-slate-500 border border-slate-200 rounded-xl px-3 h-[44px] shrink-0"
                  >
                    {myNumberShown ? '隠す' : '表示'}
                  </button>
                </div>
                {myNumber && onlyDigits(myNumber).length !== 12 && (
                  <div className="mt-1 text-[11.5px] text-amber-700">
                    12桁でご入力ください（現在 {onlyDigits(myNumber).length} 桁）
                  </div>
                )}
                {onlyDigits(myNumber).length === 12 && (
                  <div className="mt-1 text-[11.5px] text-emerald-700">12桁で入力されています</div>
                )}
              </Field>
            </div>

            {error && <div className="text-[12.5px] text-rose-600 bg-rose-50 border border-rose-200 rounded-xl px-3.5 py-2.5">{error}</div>}
            <button type="submit" disabled={saving} className="w-full py-3 rounded-xl bg-slate-950 disabled:bg-slate-300 text-white text-[14px] font-bold">
              {saving ? '保存中…' : '登録して利用を開始する'}
            </button>
          </form>

          <div className="flex items-center justify-end">
            <button onClick={onLogout} className="text-[11.5px] text-slate-400">ログアウト</button>
          </div>
        </div>
      </div>
      <ToastView toast={toast} />
    </div>
  );
}

function ResetPasswordRecoveryScreen({ toast, onDone }) {
  const passwordRef = useRef(null);
  const confirmRef = useRef(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setError('');
    const password = passwordRef.current?.value || '';
    const confirmPassword = confirmRef.current?.value || '';
    const pwProblem = passwordProblem(password);
    if (pwProblem) {
      setError(pwProblem);
      return;
    }
    if (!isHalfWidthPassword(password)) {
      setError('パスワードは半角の英数字・記号でご入力ください（日本語入力をオフにしてください）');
      return;
    }
    if (password !== confirmPassword) {
      setError('パスワードが一致しません');
      return;
    }
    setSaving(true);
    const { error: updateError } = await supabase.auth.updateUser({ password });
    setSaving(false);
    if (updateError) {
      setError('パスワードの更新に失敗しました。もう一度リンクを開き直してお試しください。');
      return;
    }
    setDone(true);
  };

  return (
    <div className="min-h-[100dvh] bg-white flex items-center justify-center px-4 py-[max(1rem,env(safe-area-inset-top))] font-sans">
      <div className="w-full max-w-[360px]">
        <div className="text-center mb-8">
          <div className="w-14 h-14 rounded-2xl bg-slate-950 flex items-center justify-center mx-auto mb-4 shadow-lg shadow-amber-200">
            <Lock size={24} className="text-white" strokeWidth={2.4} />
          </div>
          <h1 className="text-slate-800 font-bold text-[19px] tracking-tight">新しいパスワードを設定</h1>
        </div>
        <div className="bg-white rounded-2xl p-6 space-y-4 border-2 border-slate-200 shadow-lg">
          {done ? (
            <>
              <div className="bg-emerald-50 border border-emerald-200 rounded-xl px-4 py-3 text-[12.5px] text-emerald-700">
                パスワードを更新しました。もう一度ログインしてください。
              </div>
              <button onClick={onDone} className="w-full py-3 rounded-xl bg-slate-950 text-white text-[14px] font-bold">
                ログイン画面へ
              </button>
            </>
          ) : (
            <form onSubmit={submit} className="space-y-4">
              <div>
                <label className="block text-[12.5px] font-bold text-slate-800 mb-1.5">{`新しいパスワード（${PASSWORD_RULE_TEXT}）`}</label>
                <PasswordInput
                  inputRef={passwordRef}
                  id="recovery-password"
                  name="recovery-password"
                  className="w-full border-2 border-slate-200 rounded-xl px-3.5 py-3 text-[16px] outline-none focus:border-slate-900"
                />
              </div>
              <div>
                <label className="block text-[12.5px] font-bold text-slate-800 mb-1.5">新しいパスワード（確認）</label>
                <PasswordInput
                  inputRef={confirmRef}
                  id="recovery-password-confirm"
                  name="recovery-password-confirm"
                  className="w-full border-2 border-slate-200 rounded-xl px-3.5 py-3 text-[16px] outline-none focus:border-slate-900"
                />
              </div>
              {error && <div className="bg-rose-50 border border-rose-200 rounded-xl px-4 py-2.5 text-[12px] text-rose-700">{error}</div>}
              <button type="submit" disabled={saving} className="w-full py-3 rounded-xl bg-slate-950 disabled:bg-slate-300 text-white text-[14px] font-bold">
                {saving ? '更新中…' : 'パスワードを更新する'}
              </button>
            </form>
          )}
        </div>
      </div>
      <ToastView toast={toast} />
    </div>
  );
}

// 上部バー。タブ・表示モードの切り替え・利用者メニューを1段にまとめる。
function GlobalTopTabs({
  topTab, setTopTab, session, personalMode, setPersonalMode,
  onLogout, viewMode, onToggleViewMode, onOpenProfile,
  cloudStatusLabel, cloudStatusClass,
  staffMode = false, requestItems = [], requestBadges = {}, onSelectRequest, wide = false,
}) {
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef(null);

  useEffect(() => {
    const onClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) setMenuOpen(false);
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  // スタッフ画面は「各種申請」タブ、管理画面は「人材」タブ
  const allTabs = staffMode
    ? [
        { key: 'attendance', label: '勤怠', icon: <Clock size={14} /> },
        { key: 'labor', label: '労務', icon: <Briefcase size={14} /> },
        { key: 'requests', label: '各種申請', icon: <ClipboardList size={14} /> },
        { key: 'payroll', label: '給与', icon: <Wallet size={14} /> },
        { key: 'help', label: 'ヘルプ', icon: <HelpCircle size={14} /> },
      ]
    : [
        { key: 'attendance', label: '勤怠', icon: <Clock size={14} /> },
        { key: 'labor', label: '労務', icon: <Briefcase size={14} /> },
        { key: 'hr', label: '人材', icon: <UserCog size={14} /> },
        { key: 'payroll', label: '給与', icon: <Wallet size={14} /> },
        { key: 'help', label: 'ヘルプ', icon: <HelpCircle size={14} /> },
      ];
  const hasRequestBadge = requestItems.some((it) => requestBadges[it.key]);
  // 権限を制限された管理者は、許可されたタブのみ表示（スタッフ・マスター管理者は全タブ表示）。
  // ただし「自分の勤怠」表示中は本人の画面なので、タブ制限はかけない。
  const isRestrictedAdmin = session?.role === 'admin' && !personalMode;
  const tabs = isRestrictedAdmin
    ? allTabs.filter((t) => t.key === 'help' || (session.adminPermissions || []).includes(t.key))
    : allTabs;

  useEffect(() => {
    if (isRestrictedAdmin && tabs.length > 0 && !tabs.some((t) => t.key === topTab)) {
      setTopTab(tabs[0].key);
    }
  }, [isRestrictedAdmin, topTab, tabs.map((t) => t.key).join(',')]);

  const isAdminRole = session?.role === 'admin' || session?.role === 'master_admin';
  const roleLabel = session?.role === 'master_admin' ? 'マスター管理者' : session?.role === 'admin' ? '管理者' : 'スタッフ';
  const isDesktop = viewMode === 'desktop';

  // 管理画面／自分の勤怠 の切り替え（PCはバーの右側、スマホはタブの下に全幅で表示）
  const showToggle = isAdminRole && !!setPersonalMode;
  const modeToggle = (fullWidth) => (
    <div className={`flex items-center bg-white/10 rounded-lg p-0.5 text-[11px] font-bold ${fullWidth ? 'w-full' : ''}`}>
      <button
        onClick={() => setPersonalMode(false)}
        className={`px-2.5 py-1.5 rounded-md transition-colors whitespace-nowrap ${fullWidth ? 'flex-1' : ''} ${!personalMode ? 'bg-white text-slate-900' : 'text-slate-300'}`}
      >
        管理画面
      </button>
      <button
        onClick={() => setPersonalMode(true)}
        className={`px-2.5 py-1.5 rounded-md transition-colors whitespace-nowrap ${fullWidth ? 'flex-1' : ''} ${personalMode ? 'bg-white text-slate-900' : 'text-slate-300'}`}
      >
        自分の勤怠
      </button>
    </div>
  );

  return (
    <div className="relative bg-slate-950 text-slate-300">
      <div className={`${wide ? 'max-w-[1400px]' : 'max-w-6xl'} mx-auto px-4`}>
        <div className="flex items-center gap-2">
          <div className="hidden lg:flex items-center gap-2 shrink-0 pr-1">
            <div className="w-7 h-7 rounded-lg bg-amber-600 flex items-center justify-center">
              <Clock size={15} className="text-white" strokeWidth={2.4} />
            </div>
            <span className="text-white text-[13px] font-bold tracking-tight">Brown Work</span>
            <span className="w-px h-5 bg-white/20 ml-1" />
          </div>

          <div className="flex items-center gap-1 flex-1 min-w-0 overflow-x-auto">
            {tabs.map((t) => (
              <button
                key={t.key}
                onClick={() => {
                  setTopTab(t.key);
                  // 「各種申請」はいつでも候補の一覧から始める
                  if (t.key === 'requests' && onSelectRequest) onSelectRequest(null);
                }}
                className={`relative flex items-center gap-1.5 px-2.5 sm:px-3.5 py-3 text-[12.5px] font-bold border-b-2 transition-colors whitespace-nowrap shrink-0 ${
                  topTab === t.key ? 'text-white border-amber-500' : 'text-slate-400 border-transparent hover:text-slate-200'
                }`}
              >
                {t.icon}
                {t.label}
                {t.key === 'requests' && hasRequestBadge && (
                  <span className="absolute top-2 right-0 w-1.5 h-1.5 rounded-full bg-amber-500" />
                )}
              </button>
            ))}
          </div>

          {showToggle && <div className="hidden sm:block shrink-0">{modeToggle(false)}</div>}

          <div ref={menuRef} className="relative shrink-0">
            <button
              onClick={() => setMenuOpen((v) => !v)}
              className="flex items-center gap-1.5 rounded-lg bg-white/10 hover:bg-white/20 transition-colors px-2 py-1.5"
            >
              <span className="w-5 h-5 rounded-full bg-slate-600 text-white text-[10px] font-bold flex items-center justify-center">
                {(session?.name || '　').trim().charAt(0)}
              </span>
              <span className="hidden md:inline text-[11.5px] font-bold text-slate-200 max-w-[7rem] truncate">{session?.name}</span>
              <ChevronDown size={12} className="text-slate-400" />
            </button>
            {menuOpen && (
              <div className="absolute right-0 top-full mt-1.5 w-56 bg-white rounded-xl border border-slate-200 shadow-xl overflow-hidden z-50">
                <div className="px-4 py-3 border-b border-slate-100">
                  <div className="text-[13px] font-bold text-slate-800 truncate">{session?.name}</div>
                  <div className="text-[11px] text-slate-400">{roleLabel}</div>
                </div>
                {cloudStatusLabel && (
                  <div className="px-4 py-2.5 border-b border-slate-100 flex items-center justify-between">
                    <span className="text-[11.5px] text-slate-500">同期の状態</span>
                    <span className={`text-[10.5px] font-semibold rounded-full border px-2 py-0.5 ${cloudStatusClass}`}>{cloudStatusLabel}</span>
                  </div>
                )}
                {onOpenProfile && (
                  <button
                    onClick={() => { setMenuOpen(false); onOpenProfile(); }}
                    className="flex w-full items-center gap-2 px-4 py-2.5 text-[12.5px] font-medium text-slate-600 hover:bg-slate-50 border-b border-slate-100"
                  >
                    <UserCog size={14} className="text-slate-400" /> 登録情報の閲覧・変更
                  </button>
                )}
                <button
                  onClick={() => { setMenuOpen(false); if (onToggleViewMode) onToggleViewMode(); }}
                  className="hidden md:flex w-full items-center gap-2 px-4 py-2.5 text-[12.5px] text-slate-600 hover:bg-slate-50 border-b border-slate-100"
                >
                  {isDesktop ? <Smartphone size={14} className="text-slate-400" /> : <Monitor size={14} className="text-slate-400" />}
                  {isDesktop ? 'スマホ向けの表示に切り替える' : 'パソコン向けの表示に切り替える'}
                </button>
                <button
                  onClick={() => { setMenuOpen(false); if (onLogout) onLogout(); }}
                  className="flex w-full items-center gap-2 px-4 py-2.5 text-[12.5px] font-medium text-slate-600 hover:bg-slate-50"
                >
                  <LogoutIcon size={14} className="text-slate-400" /> ログアウト
                </button>
              </div>
            )}
          </div>
        </div>

        {showToggle && (
          <div className="sm:hidden pb-2">{modeToggle(true)}</div>
        )}
      </div>

    </div>
  );
}

// 各種申請の候補（スタッフ画面）
// 「実績入力」と「シフト表」は「勤怠」タブのサブタブ（実績・シフト）に移したため、
// ここには入れない。シフト希望の提出だけが各種申請に残る。
const STAFF_REQUEST_ITEMS = [
  { key: 'shift', label: 'シフト希望', desc: '翌月の出勤可能日を提出', icon: CalendarDays, shiftOnly: true },
  { key: 'leave', label: '休暇申請', desc: '有休・欠勤などの申請と残日数', icon: Palmtree },
  { key: 'monthly', label: '月次勤怠申請', desc: '前月分の勤怠（交通費とまとめて提出）', icon: CheckCircle2 },
  { key: 'commute', label: '交通費申請', desc: '立て替えた交通費の精算', icon: Wallet },
  { key: 'yearend', label: '年末調整', desc: '年末調整の書類を提出', icon: FileText },
];

// ---- シフト希望 ----
const SHIFT_ANSWERS = [
  { key: 'ok', label: '●', full: '出勤可能', cls: 'bg-amber-600 text-white border-amber-600' },
  { key: 'off', label: '×', full: '希望休', cls: 'bg-slate-700 text-white border-slate-700' },
  { key: 'paid', label: '有給', full: '有給（SV報告済）', cls: 'bg-teal-700 text-white border-teal-700' },
];
const SHIFT_ANSWER_LABEL = { ok: '●', off: '×', paid: '有給' };
// 活動場所を入力する型の選択肢（●のかわりに「出勤」を選んで場所を書く）
const SHIFT_PLACE_ANSWERS = [
  { key: 'ok', label: '出勤', full: '出勤可能', cls: 'bg-amber-600 text-white border-amber-600' },
  { key: 'off', label: '×', full: '希望休', cls: 'bg-slate-700 text-white border-slate-700' },
  { key: 'paid', label: '有給', full: '有給（SV報告済）', cls: 'bg-teal-700 text-white border-teal-700' },
];

// ある日のシフトを引く。
// スプレッドシートから取り込んだ確定シフトがあればそれを使い、
// 無ければスタッフが出したシフト希望を使う。
function shiftForDate(shiftRequests, employeeId, dateKey, shiftAssignments) {
  if (!dateKey) return null;

  // 確定シフトが優先
  const fixed = (shiftAssignments || []).find((a) => a.employeeId === employeeId && a.date === dateKey);
  if (fixed) {
    const kind = fixed.kind === 'work' ? 'ok' : fixed.kind;   // 'ok' | 'off' | 'paid'
    return {
      kind,
      place: fixed.place || '',
      text: fixed.place || (kind === 'off' ? '×' : kind === 'paid' ? '有給' : '●'),
      isRest: kind === 'off' || kind === 'paid',
      confirmed: true,
    };
  }

  const month = dateKey.slice(0, 7);
  const req = (shiftRequests || []).find((r) => r.employeeId === employeeId && r.targetMonth === month);
  if (!req) return null;
  const value = req.answers?.[dateKey];
  if (!value) return null;
  return {
    kind: shiftAnswerKind(value),   // 'ok' | 'off' | 'paid'
    place: shiftAnswerPlace(value).trim(),
    text: shiftAnswerText(value),
    // 休みとして出している日
    isRest: shiftAnswerKind(value) === 'off' || shiftAnswerKind(value) === 'paid',
    confirmed: false,
  };
}

// 対象月の日付を並べる（祝日と曜日の情報つき）
function shiftMonthDays(targetMonth) {
  const [y, m] = targetMonth.split('-').map(Number);
  if (!y || !m) return [];
  const lastDay = new Date(y, m, 0).getDate();
  const days = [];
  for (let d = 1; d <= lastDay; d++) {
    const key = `${targetMonth}-${pad(d)}`;
    const wd = new Date(key + 'T00:00:00').getDay();
    const holidayName = getHolidayName(key);
    days.push({
      key,
      day: d,
      weekday: ['日', '月', '火', '水', '木', '金', '土'][wd],
      isSunday: wd === 0,
      isSaturday: wd === 6,
      holidayName,
      isWeekendOrHoliday: wd === 0 || wd === 6 || !!holidayName,
    });
  }
  return days;
}

// 出勤依頼日の既定（土日祝）
function defaultRequestDays(targetMonth) {
  return shiftMonthDays(targetMonth).filter((d) => d.isWeekendOrHoliday).map((d) => d.key);
}

function ShiftRequestSection({ session, period, request, onSubmit, formatKey = 'symbol', groupAttendanceSchedules = {}, employeeAttendanceSchedules = {} }) {
  const targetMonth = period?.targetMonth || '';
  const days = useMemo(() => shiftMonthDays(targetMonth), [targetMonth]);
  // その月の出勤規定日数（給与の日割りに使う日数）。
  // 所属グループに登録があればその日数、グループ未設定なら個人別の登録を見る。
  // 登録が無い月は null。78番でスタッフ本人も自分の分を読めるようにしてある。
  const prescribedDays = useMemo(() => {
    const [y, m] = String(targetMonth).split('-').map(Number);
    if (!y || !m) return null;
    return getPrescribedAttendanceDays(session, y, m, groupAttendanceSchedules, employeeAttendanceSchedules);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetMonth, session?.id, session?.mainGroup, groupAttendanceSchedules, employeeAttendanceSchedules]);
  const [answers, setAnswers] = useState({});
  const [loadedFor, setLoadedFor] = useState(null);
  const [note, setNote] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (loadedFor === targetMonth) return;
    setAnswers(request?.answers || {});
    setNote(request?.note || '');
    setLoadedFor(targetMonth);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetMonth, request?.id]);

  if (!period) {
    return (
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm px-5 py-10 text-center">
        <CalendarDays size={22} className="mx-auto mb-2 text-slate-300" />
        <div className="text-[13px] font-bold text-slate-600">いまは受付中のシフト希望はありません</div>
        <div className="mt-1 text-[11.5px] text-slate-400">受付が始まると、お知らせでご連絡します。</div>
      </div>
    );
  }

  const requestDays = new Set(period.requestDays && period.requestDays.length > 0 ? period.requestDays : defaultRequestDays(targetMonth));
  const isPlaceFormat = formatKey === 'place';
  const filled = days.filter((d) => shiftAnswerFilled(answers[d.key])).length;
  const complete = filled === days.length && days.length > 0;
  const closed = !period.isOpen;

  // 残りをまとめて埋める。活動場所の型では場所を書いてもらう必要があるため「×」でまとめる
  const bulkValue = isPlaceFormat ? 'off' : 'ok';
  const bulkLabel = isPlaceFormat ? '残りを×にする' : '残りを●にする';
  const setAll = () => {
    const next = { ...answers };
    days.forEach((d) => { if (!shiftAnswerFilled(next[d.key])) next[d.key] = bulkValue; });
    setAnswers(next);
  };

  const submit = async () => {
    setSaving(true);
    const ok = await onSubmit(targetMonth, answers, note);
    setSaving(false);
    if (ok) setLoadedFor(null);
  };

  // 1日分の行。再描画で作り直されないよう関数として組み立てる
  const renderDay = (d) => {
    const picked = answers[d.key];
    const kind = shiftAnswerKind(picked);
    // 活動場所を入力する型では、出勤依頼日（★）の印はつけない
    const isRequest = !isPlaceFormat && requestDays.has(d.key);
    return (
      <div
        key={d.key}
        className={`rounded-2xl border px-3 py-2.5 ${isRequest ? 'border-amber-500 bg-white' : 'border-slate-200 bg-white'}`}
      >
        <div className="mb-2 flex items-center gap-1.5 flex-wrap">
          <span className={`text-[13.5px] font-bold ${d.isSunday || d.holidayName ? 'text-rose-600' : d.isSaturday ? 'text-sky-600' : 'text-slate-800'}`}>
            {d.day}日({d.weekday})
          </span>
          {isRequest && (
            <span className="rounded-full bg-amber-50 px-1.5 py-[1px] text-[10px] font-bold text-amber-700">★ 出勤依頼日</span>
          )}
          {d.holidayName && (
            <span className="rounded-full bg-rose-50 px-1.5 py-[1px] text-[10px] font-bold text-rose-600">{d.holidayName}</span>
          )}
        </div>
        <div className="flex gap-1.5">
          {(isPlaceFormat ? SHIFT_PLACE_ANSWERS : SHIFT_ANSWERS).map((a) => (
            <button
              key={a.key}
              type="button"
              disabled={closed}
              onClick={() => setAnswers((prev) => ({
                ...prev,
                // 活動場所の型で「出勤」を選んだときは、入力欄を出すために空の場所を入れる
                [d.key]: a.key === 'ok' && isPlaceFormat ? `${SHIFT_PLACE_PREFIX}${shiftAnswerPlace(prev[d.key])}` : a.key,
              }))}
              className={`flex-1 rounded-xl border py-2.5 text-[13px] font-bold transition-colors disabled:opacity-60 ${
                kind === a.key ? a.cls : 'border-slate-200 bg-white text-slate-500 hover:bg-slate-50'
              } ${a.key === 'paid' ? 'text-[11.5px]' : ''}`}
            >
              {a.label}
            </button>
          ))}
        </div>
        {isPlaceFormat && kind === 'ok' && (
          <input
            value={shiftAnswerPlace(picked)}
            onChange={(e) => setAnswers((prev) => ({ ...prev, [d.key]: `${SHIFT_PLACE_PREFIX}${e.target.value}` }))}
            disabled={closed}
            placeholder="活動場所（例：亀岡店）"
            className="mt-1.5 block w-full min-w-0 max-w-full box-border rounded-xl border border-slate-200 bg-white px-3 py-2 text-[16px] disabled:opacity-60"
          />
        )}
      </div>
    );
  };

  return (
    <div className="space-y-3">
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="px-5 py-3.5 border-b border-slate-100 flex items-center gap-2 flex-wrap">
          <CalendarDays size={15} className="text-slate-400" />
          <h2 className="font-bold text-[13.5px]">{monthKeyLabel(targetMonth)}のシフト希望</h2>
          {period.deadline && (
            <span className="rounded-full bg-rose-50 px-2 py-0.5 text-[10.5px] font-bold text-rose-700">締切 {dateLabel(period.deadline)}</span>
          )}
          {/* その月の出勤規定日数。登録が無い月は出さない */}
          {prescribedDays != null && (
            <span className="rounded-full bg-sky-50 px-2 py-0.5 text-[10.5px] font-bold text-sky-700">出勤規定日数 {prescribedDays}日</span>
          )}
          {request && (
            <span className="rounded-full bg-emerald-50 px-2 py-0.5 text-[10.5px] font-bold text-emerald-700">提出済み</span>
          )}
          {closed && (
            <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10.5px] font-bold text-slate-500">受付終了</span>
          )}
        </div>
        <div className="px-5 py-4 space-y-3">
          <div className="rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-2.5 text-[11.5px] leading-relaxed text-slate-600">
            {isPlaceFormat ? (
              <>
                出勤 ＝ 出勤できる日。活動場所を入力してください<br />
                × ＝ 希望休　／　有給 ＝ SVへ報告済みの有給
              </>
            ) : (
              <>
                ● ＝ 出勤可能　／　× ＝ 希望休<br />
                有給 ＝ SVへ報告済みの有給<br />
                <span className="font-bold text-amber-700">★</span> の日は出勤依頼日です（土日祝）
              </>
            )}
          </div>
          {period.note && (
            <div className="rounded-xl border border-amber-200 bg-amber-50 px-3.5 py-2.5 text-[11.5px] text-amber-800">{period.note}</div>
          )}
          <div className="flex items-center gap-3">
            <div className="flex-1">
              <div className="flex items-center justify-between">
                <span className="text-[11px] text-slate-400">入力済み</span>
                <span className="text-[11.5px] font-bold text-slate-800">{filled}／{days.length}日</span>
              </div>
              <div className="mt-1 h-1.5 rounded-full bg-slate-200 overflow-hidden">
                <div className="h-1.5 bg-amber-600" style={{ width: `${days.length ? Math.round((filled / days.length) * 100) : 0}%` }} />
              </div>
            </div>
            <button
              type="button"
              onClick={setAll}
              disabled={closed}
              className="shrink-0 rounded-lg border border-slate-300 px-3 py-2 text-[11.5px] font-bold text-slate-600 disabled:opacity-60"
            >
              {bulkLabel}
            </button>
          </div>
        </div>
      </div>

      <div className="space-y-2">{days.map((d) => renderDay(d))}</div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm px-5 py-4 space-y-3">
        <Field label="管理者へのメモ（任意）">
          <textarea
            value={note}
            onChange={(e) => setNote(e.target.value)}
            rows={2}
            placeholder="例）15日は午後から出られます"
            className="w-full border border-slate-200 rounded-lg px-3 py-2 text-[13px] resize-none"
          />
        </Field>
        <button
          onClick={submit}
          disabled={saving || !complete || closed}
          className="w-full rounded-xl bg-amber-600 py-3 text-[14px] font-bold text-white disabled:bg-slate-200"
        >
          {saving ? '送信中…' : request ? 'この内容で出し直す' : 'この内容で提出する'}
        </button>
        {!complete && !closed && (
          <div className="text-center text-[11px] text-slate-400">すべての日を選ぶと押せるようになります（残り{days.length - filled}日）</div>
        )}
        {closed && (
          <div className="text-center text-[11px] text-slate-400">受付が終了しているため提出できません。管理者にご相談ください。</div>
        )}
      </div>
    </div>
  );
}

// ---- 進行中の手続き（スタッフ）----
// 休暇・月次勤怠・交通費・年末調整・個人情報・勤怠修正・シフトの申請状況を、種類をまたいで1枚にまとめる
const MY_REQUEST_STATE = {
  draft: { label: '一時保存', cls: 'bg-slate-100 text-slate-500', open: true },
  pending: { label: '確認中', cls: 'bg-amber-50 text-amber-700', open: true },
  admin_approved: { label: '最終承認待ち', cls: 'bg-amber-50 text-amber-700', open: true },
  rejected: { label: '差し戻し', cls: 'bg-rose-50 text-rose-600', open: true },
  approved: { label: '完了', cls: 'bg-emerald-50 text-emerald-700', open: false },
  confirmed: { label: '確定済み', cls: 'bg-emerald-50 text-emerald-700', open: false },
  submitted: { label: '提出済み', cls: 'bg-emerald-50 text-emerald-700', open: false },
};

function buildMyRequests({ corrections = [], leaveRequests = [], monthlyConfirmations = [], commuteClaims = [], yearEndAdjustments = [], profileRequests = [], shiftRequests = [] }) {
  const out = [];
  corrections.forEach((c) => out.push({
    id: `cor-${c.id}`, kind: '勤怠修正', tab: null,
    title: `${dateLabel(c.date)}の打刻修正`, status: c.status, at: c.submittedAt, memo: '',
  }));
  leaveRequests.forEach((l) => out.push({
    id: `lv-${l.id}`, kind: '休暇申請', tab: 'leave',
    title: `${l.type || '休暇'} ${dateLabel(l.startDate)}${l.endDate && l.endDate !== l.startDate ? `〜${dateLabel(l.endDate)}` : ''}`,
    status: l.status, at: l.submittedAt, memo: '',
  }));
  monthlyConfirmations.forEach((m) => out.push({
    id: `mc-${m.id}`, kind: '月次勤怠申請', tab: 'monthly',
    title: `${monthKeyLabel(m.targetMonth)}分`, status: m.status, at: m.submittedAt,
    memo: m.masterComment || m.adminComment || '',
  }));
  commuteClaims.forEach((c) => out.push({
    id: `cm-${c.id}`, kind: '交通費申請', tab: 'commute',
    title: `${monthKeyLabel(c.targetMonth)}分 ${formatYen(c.totalAmount)}`, status: c.status,
    at: c.createdAt, memo: c.adminComment || '',
  }));
  yearEndAdjustments.forEach((y) => out.push({
    id: `ye-${y.id}`, kind: '年末調整', tab: 'yearend',
    title: `${y.year}年分`, status: y.status, at: y.submittedAt, memo: y.adminComment || '',
  }));
  profileRequests.forEach((r) => out.push({
    id: `pr-${r.id}`, kind: '個人情報の変更', tab: 'profile',
    title: Object.keys(r.requestedChanges || {})
      .map((k) => PROFILE_EDITABLE_FIELDS.find((f) => f.key === k)?.label.replace(/（.*）/, '') || k)
      .slice(0, 3).join('、') || '変更申請',
    status: r.status, at: r.submittedAt, memo: r.adminMemo || '',
  }));
  shiftRequests.forEach((r) => out.push({
    id: `sh-${r.id}`, kind: 'シフト希望', tab: 'shift',
    title: `${monthKeyLabel(r.targetMonth)}分`, status: 'submitted', at: r.submittedAt, memo: '',
  }));
  return out.sort((a, b) => String(b.at || '').localeCompare(String(a.at || '')));
}

function MyRequestStatusCard({ items, onOpen }) {
  const [showDone, setShowDone] = useState(false);
  const openItems = items.filter((it) => MY_REQUEST_STATE[it.status]?.open);
  const shown = (showDone ? items : openItems).slice(0, showDone ? 40 : 20);

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="px-5 py-3.5 border-b border-slate-100 flex items-center gap-2">
        <ListChecks size={15} className="text-slate-400" />
        <h2 className="font-bold text-[13.5px]">進行中の手続き</h2>
        {openItems.length > 0 && (
          <span className="text-[10.5px] font-bold text-white bg-amber-600 rounded-full px-2 py-0.5">{openItems.length}件</span>
        )}
        <button
          onClick={() => setShowDone((v) => !v)}
          className="ml-auto text-[11px] font-bold text-slate-400 hover:text-slate-700"
        >
          {showDone ? '進行中のみ' : '完了も見る'}
        </button>
      </div>
      {shown.length === 0 ? (
        <div className="px-5 py-8 text-center text-[12.5px] text-slate-300">
          {showDone ? '手続きの記録はありません' : '進行中の手続きはありません'}
        </div>
      ) : (
        <div className="divide-y divide-slate-100">
          {shown.map((it) => {
            const state = MY_REQUEST_STATE[it.status] || { label: it.status, cls: 'bg-slate-100 text-slate-500' };
            const body = (
              <>
                <div className="flex items-center justify-between gap-2">
                  <span className="text-[12.5px] font-bold text-slate-800">{it.kind}</span>
                  <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10.5px] font-bold ${state.cls}`}>{state.label}</span>
                </div>
                <div className="mt-0.5 flex items-center justify-between gap-2">
                  <span className="text-[12px] text-slate-500 truncate">{it.title}</span>
                  <span className="shrink-0 text-[10.5px] text-slate-300">
                    {it.at ? new Date(it.at).toLocaleDateString('ja-JP') : ''}
                  </span>
                </div>
                {it.memo && (
                  <div className="mt-1.5 rounded-lg bg-amber-50 border border-amber-100 px-2.5 py-1.5 text-[11px] text-amber-800">
                    管理者コメント：{it.memo}
                  </div>
                )}
              </>
            );
            return it.tab && onOpen ? (
              <button key={it.id} onClick={() => onOpen(it.tab)} className="w-full text-left px-5 py-3 hover:bg-slate-50">
                {body}
              </button>
            ) : (
              <div key={it.id} className="px-5 py-3">{body}</div>
            );
          })}
        </div>
      )}
    </div>
  );
}

