// スタッフ一覧の行末メニュー。その人の画面へ直接移動する
function StaffRowMenu({ account, info, onOpenProfile, onOpenAttendance, onOpenApprovals, onOpenPayroll }) {
  const [pos, setPos] = useState(null); // 開いている位置（画面基準）
  const btnRef = useRef(null);

  useEffect(() => {
    if (!pos) return undefined;
    const close = () => setPos(null);
    document.addEventListener('mousedown', close);
    window.addEventListener('scroll', close, true);
    window.addEventListener('resize', close);
    return () => {
      document.removeEventListener('mousedown', close);
      window.removeEventListener('scroll', close, true);
      window.removeEventListener('resize', close);
    };
  }, [pos]);

  const toggle = () => {
    if (pos) { setPos(null); return; }
    const r = btnRef.current?.getBoundingClientRect();
    if (!r) return;
    setPos({ top: r.bottom + 6, right: Math.max(8, window.innerWidth - r.right) });
  };

  const item = (label, fn, badge) => (
    <button
      onClick={() => { setPos(null); fn(); }}
      className="flex w-full items-center justify-between gap-3 px-4 py-2.5 text-left text-[12.5px] font-bold text-slate-800 hover:bg-slate-50"
    >
      <span>{label}</span>
      {badge ? <span className="text-amber-600">{badge}</span> : null}
    </button>
  );

  return (
    <>
      <button
        ref={btnRef}
        onMouseDown={(e) => e.stopPropagation()}
        onClick={toggle}
        aria-label={`${account.name}さんの操作メニュー`}
        className={`rounded-lg px-2.5 py-1 text-[13px] font-bold ${
          info?.pendingCount > 0 ? 'bg-slate-900 text-white' : 'border border-slate-200 text-slate-500 hover:bg-slate-50'
        }`}
      >
        ⋯
      </button>
      {pos && createPortal(
        <div
          onMouseDown={(e) => e.stopPropagation()}
          style={{ position: 'fixed', top: pos.top, right: pos.right, zIndex: 60 }}
          className="w-60 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-2xl"
        >
          <div className="px-4 pt-2.5 pb-1 text-[10.5px] font-bold text-slate-400">{account.name} さんの操作</div>
          {item('勤怠を見る・直す', () => onOpenAttendance(account.id))}
          {info?.pendingCount > 0 && item('未処理の申請を承認する', () => onOpenApprovals(account.id), info.pendingCount)}
          {item('給与を作成する', () => onOpenPayroll(account.id))}
          {item('登録情報を編集する', () => onOpenProfile(account))}
        </div>,
        document.body
      )}
    </>
  );
}

// ------------------------------------------------------------
// マイナンバーの保存期間と廃棄
//
// 番号法では、利用目的が終了して保存期間を過ぎたマイナンバーは
// 廃棄しなければならない。残し続けること自体が違反になりえる。
// 扶養控除等申告書は7年保存のため、ここでは退職日からの経過年数で
// 廃棄できるものを一覧にする（年数は変更できる）。
//
// 最終的な保存期間の判断は、社労士・税理士にご確認ください。
// ------------------------------------------------------------
function MyNumberRetentionCard({ accounts, onListMyNumbers, onDeleteMyNumber, isDesktop }) {
  const [items, setItems] = useState(null); // null = 未読み込み
  const [years, setYears] = useState(7);
  const [busyId, setBusyId] = useState(null);
  const [loading, setLoading] = useState(false);

  const load = async () => {
    setLoading(true);
    const res = await onListMyNumbers();
    setItems(res || []);
    setLoading(false);
  };

  const byId = {};
  accounts.forEach((a) => { byId[a.id] = a; });

  const today = new Date();
  const rows = (items || []).map((it) => {
    const acc = byId[it.employee_id];
    const resignation = acc?.resignationDate || '';
    let elapsed = null;
    if (resignation) {
      const d = new Date(`${resignation}T00:00:00`);
      elapsed = (today.getTime() - d.getTime()) / (365.25 * 24 * 60 * 60 * 1000);
    }
    return {
      id: it.employee_id,
      name: acc?.name || '（削除されたスタッフ）',
      resignation,
      elapsed,
      updatedAt: it.updated_at,
    };
  });

  const expired = rows.filter((r) => r.elapsed !== null && r.elapsed >= years);
  const retired = rows.filter((r) => r.elapsed !== null && r.elapsed < years);
  const active = rows.filter((r) => r.elapsed === null);

  const discard = async (row) => {
    if (!window.confirm(
      `${row.name}さんのマイナンバーを廃棄します。\n\n`
      + '元に戻すことはできません。よろしいですか？'
    )) return;
    setBusyId(row.id);
    const ok = await onDeleteMyNumber(row.id);
    setBusyId(null);
    if (ok) await load();
  };

  const discardAllExpired = async () => {
    if (expired.length === 0) return;
    if (!window.confirm(
      `保存期間（${years}年）を過ぎた${expired.length}件のマイナンバーを廃棄します。\n\n`
      + `対象：${expired.map((r) => r.name).join('、')}\n\n`
      + '元に戻すことはできません。よろしいですか？'
    )) return;
    setBusyId('all');
    for (const row of expired) {
      await onDeleteMyNumber(row.id);
    }
    setBusyId(null);
    await load();
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="px-5 py-3.5 border-b border-slate-100 flex items-center gap-2 flex-wrap">
        <ShieldCheck size={15} className="text-slate-400" />
        <h2 className="font-bold text-[13.5px]">マイナンバーの保存期間</h2>
        {items !== null && (
          <span className="text-[11px] text-slate-400">保存中 {rows.length}件</span>
        )}
        <button
          onClick={load}
          disabled={loading}
          className="ml-auto text-[12px] font-bold text-slate-600 border border-slate-200 rounded-lg px-2.5 py-1.5 disabled:text-slate-300"
        >
          {loading ? '確認中…' : items === null ? '保存状況を確認する' : '再読み込み'}
        </button>
      </div>

      <div className="px-5 py-3 border-b border-slate-100 text-[11.5px] leading-relaxed text-slate-500">
        保存期間を過ぎたマイナンバーは、番号法により廃棄が必要です。
        ここでは退職日からの経過年数で判定しています。
        在籍中の方は対象外です。
        <span className="text-slate-400">（保存期間の最終的な判断は社労士・税理士にご確認ください）</span>
      </div>

      {items === null ? (
        <div className="px-5 py-10 text-center text-[12.5px] text-slate-300">
          「保存状況を確認する」を押すと、誰の番号が保存されているかを確認できます<br />
          <span className="text-[11px]">（番号そのものは表示されません）</span>
        </div>
      ) : rows.length === 0 ? (
        <div className="px-5 py-10 text-center text-[12.5px] text-slate-300">
          保存されているマイナンバーはありません
        </div>
      ) : (
        <>
          <div className="px-5 py-3 border-b border-slate-100 flex items-center gap-2 flex-wrap">
            <span className="text-[12px] text-slate-600">保存期間</span>
            <select
              value={years}
              onChange={(e) => setYears(Number(e.target.value))}
              className="border border-slate-200 rounded-lg px-2.5 py-1.5 text-[12.5px] bg-white"
            >
              {[5, 7, 10].map((y) => <option key={y} value={y}>退職から{y}年</option>)}
            </select>
            {expired.length > 0 && (
              <button
                onClick={discardAllExpired}
                disabled={busyId !== null}
                className="ml-auto text-[12px] font-bold text-white bg-rose-600 disabled:bg-slate-200 rounded-lg px-3 py-1.5"
              >
                {busyId === 'all' ? '廃棄中…' : `期間を過ぎた${expired.length}件を廃棄`}
              </button>
            )}
          </div>

          {expired.length > 0 && (
            <div className="px-5 py-3 bg-amber-50 border-b border-amber-100">
              <div className="text-[12px] font-bold text-amber-900">
                保存期間を過ぎています（{expired.length}件）
              </div>
              <div className="mt-2 space-y-1.5">
                {expired.map((r) => (
                  <div key={r.id} className="flex items-center justify-between gap-3">
                    <div className="min-w-0">
                      <span className="text-[12.5px] font-semibold text-slate-800">{r.name}</span>
                      <span className="ml-2 text-[11px] text-slate-500">
                        退職 {dateLabel(r.resignation)}（{Math.floor(r.elapsed)}年経過）
                      </span>
                    </div>
                    <button
                      onClick={() => discard(r)}
                      disabled={busyId !== null}
                      className="shrink-0 text-[11.5px] font-bold text-rose-600 border border-rose-200 rounded-lg px-2.5 py-1 disabled:text-slate-300"
                    >
                      {busyId === r.id ? '廃棄中…' : '廃棄'}
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="divide-y divide-slate-100">
            {retired.map((r) => (
              <div key={r.id} className="px-5 py-2.5 flex items-center justify-between gap-3">
                <div className="min-w-0">
                  <span className="text-[12.5px] text-slate-700">{r.name}</span>
                  <span className="ml-2 text-[11px] text-slate-400">
                    退職 {dateLabel(r.resignation)}（{Math.floor(r.elapsed)}年経過・保存期間内）
                  </span>
                </div>
                <button
                  onClick={() => discard(r)}
                  disabled={busyId !== null}
                  className="shrink-0 text-[11.5px] font-medium text-slate-400 border border-slate-200 rounded-lg px-2.5 py-1"
                >
                  廃棄
                </button>
              </div>
            ))}
            {active.length > 0 && (
              <div className="px-5 py-2.5 text-[11.5px] text-slate-400">
                在籍中のスタッフ {active.length}名 ぶんは保存中です（廃棄の対象外）
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

function AccountManagement({ employeeAccounts, onAddAccount, onChangeLoginEmail, onUpdateDates, onDeleteAccount, onResetPassword, onFetchMyNumber, onSaveMyNumber, onListMyNumbers, onDeleteMyNumber, groupLeaveSchedules, employeeAttendanceSchedules, onSaveEmployeeAttendance, resignationReasons = [], settings = {}, initialProfileId = null, onConsumeInitialProfile, rowInfo = {}, rowActions = {}, session, leaveGrants = [], leaveRequests = [], onLeaveGrantsChanged, isDesktop }) {
  const knownGroups = Array.from(new Set([...employeeAccounts.map((a) => a.mainGroup).filter(Boolean), ...Object.keys(groupLeaveSchedules || {})]));
  const [listGroupFilter, setListGroupFilter] = useState('all');
  const [listStaffTypeFilter, setListStaffTypeFilter] = useState('all');
  const [listNameQuery, setListNameQuery] = useState('');
  const [listStatusFilter, setListStatusFilter] = useState('active'); // all | active | retired
  const [listSort, setListSort] = useState('name'); // name | hireDateDesc | hireDateAsc
  const [sei, setSei] = useState('');
  const [mei, setMei] = useState('');
  const [seiKana, setSeiKana] = useState('');
  const [meiKana, setMeiKana] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [hireDate, setHireDate] = useState(todayKey());
  const [role, setRole] = useState('employee');
  const [adminPermissions, setAdminPermissions] = useState(['attendance', 'labor', 'hr', 'payroll']);
  const [showForm, setShowForm] = useState(false);
  const [profileModalAccount, setProfileModalAccount] = useState(null);
  const [csvModalOpen, setCsvModalOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [resetPasswordTarget, setResetPasswordTarget] = useState(null);
  const [loginEmailTarget, setLoginEmailTarget] = useState(null);
  const [backingUp, setBackingUp] = useState(false);
  // 登録情報の入力を求めるか（既定は求める）。
  // この下にスタッフ詳細を開くときの早期 return があるため、
  // useState はかならずそれより前に置くこと。後ろに書くと、詳細を開いた
  // ときだけフックの数が減り、React が描画を止める（error #300）。
  const [requireProfileSetup, setRequireProfileSetup] = useState(true);
  const isMasterAdmin = session?.role === 'master_admin';

  // 詳細を開いたとき・一覧に戻ったときは、前の画面のスクロール位置を引き継がない
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, [profileModalAccount?.id]);

  // 他の画面で氏名がクリックされた場合、そのスタッフの詳細を自動で開く
  useEffect(() => {
    if (!initialProfileId) return;
    const target = employeeAccounts.find((a) => a.id === initialProfileId);
    if (target) setProfileModalAccount(target);
    if (onConsumeInitialProfile) onConsumeInitialProfile();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialProfileId]);

  // 全テーブルを1つのExcelファイル（テーブルごとにシート）に書き出す
  const runFullBackup = async () => {
    setBackingUp(true);
    try {
      const wb = XLSX.utils.book_new();
      let failed = [];
      const backedUpCounts = {};
      for (const table of BACKUP_TABLES) {
        // Supabaseは1回のリクエストで返す行数に上限があるため、1000件ずつ繰り返し取得して全件つなげる
        const rows = [];
        let from = 0;
        const CHUNK = 1000;
        let tableFailed = false;
        for (;;) {
          const source = BACKUP_SOURCE[table] || table;
          const { data: chunk, error } = await supabase.from(source).select('*').range(from, from + CHUNK - 1);
          if (error) {
            tableFailed = true;
            break;
          }
          rows.push(...(chunk || []));
          if (!chunk || chunk.length < CHUNK) break;
          from += CHUNK;
        }
        if (tableFailed) {
          failed.push(table);
          continue;
        }
        const flat = rows.map((row) => {
          const out = {};
          for (const [k, v] of Object.entries(row)) {
            out[k] = v !== null && typeof v === 'object' ? JSON.stringify(v) : v;
          }
          return out;
        });
        backedUpCounts[table] = rows.length;
        const ws = XLSX.utils.json_to_sheet(flat.length ? flat : [{ 情報: 'データなし' }]);
        XLSX.utils.book_append_sheet(wb, ws, table.slice(0, 31));
      }
      XLSX.writeFile(wb, `brown-work_バックアップ_${todayKey()}.xlsx`);

      // 口座情報・給与を含むファイルの持ち出しなので、
      // 誰がいつ実行したかを必ず監査ログに残す。
      // （マイナンバーは対象外。BACKUP_TABLES のコメントを参照）
      const staffCount = backedUpCounts.employees || 0;
      await logAudit(
        session,
        '全データバックアップを作成',
        `${BACKUP_TABLES.length - failed.length}個のテーブルを書き出し`
          + `（スタッフ${staffCount}名分の口座情報・給与を含む／マイナンバーは対象外）`
          + (failed.length ? ` ／ 取得できず：${failed.join('、')}` : ''),
      );

      if (failed.length) {
        alert(`一部のデータを取得できませんでした：\n${failed.join('\n')}`);
      }
      alert(
        'バックアップを保存しました。\n\n'
        + 'このファイルには口座情報と給与が含まれます。\n'
        + '（マイナンバーは含まれません）\n'
        + '保管場所にご注意のうえ、不要になったら削除してください。\n'
        + 'この操作は監査ログに記録されました。'
      );
    } catch (e) {
      alert('バックアップの作成に失敗しました。時間をおいて再度お試しください。');
    }
    setBackingUp(false);
  };

  if (profileModalAccount) {
    return (
      <EmployeeProfileModal
        account={profileModalAccount}
        onClose={() => setProfileModalAccount(null)}
        onSave={onUpdateDates}
        onFetchMyNumber={onFetchMyNumber}
        onSaveMyNumber={onSaveMyNumber}
        isMasterAdmin={isMasterAdmin}
        knownGroups={knownGroups}
        groupAttendanceSchedules={groupLeaveSchedules}
        employeeAttendanceSchedule={employeeAttendanceSchedules?.[profileModalAccount.id] || {}}
        onSaveEmployeeAttendance={onSaveEmployeeAttendance}
        resignationReasons={resignationReasons}
        settings={settings}
        actor={session}
        leaveGrants={leaveGrants}
        leaveRequests={leaveRequests}
        onLeaveGrantsChanged={onLeaveGrantsChanged}
        isDesktop={isDesktop}
      />
    );
  }

  // ログイン案内メールを送るため、ログインIDはメールアドレス形式を必須にする
  const canSubmit = sei.trim() && mei.trim() && username.trim().includes('@') && isPasswordOk(password.trim()) && hireDate;

  const filteredEmployeeAccounts = employeeAccounts
    .filter((acc) => {
      if (listGroupFilter !== 'all' && acc.mainGroup !== listGroupFilter) return false;
      if (listStaffTypeFilter !== 'all' && acc.staffType !== listStaffTypeFilter) return false;
      if (listStatusFilter === 'active' && acc.resignationDate) return false;
      if (listStatusFilter === 'retired' && !acc.resignationDate) return false;
      const q = listNameQuery.trim();
      if (q && !((acc.name || '').includes(q) || (acc.furigana || '').includes(q))) return false;
      return true;
    })
    .sort((a, b) => {
      if (listSort === 'hireDateDesc') return (b.hireDate || '').localeCompare(a.hireDate || '');
      if (listSort === 'hireDateAsc') return (a.hireDate || '').localeCompare(b.hireDate || '');
      return (a.name || '').localeCompare(b.name || '', 'ja');
    });

  const toggleAdminPermission = (key) => {
    setAdminPermissions((prev) => (prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]));
  };

  const submit = async (e) => {
    e.preventDefault();
    if (!canSubmit) return;
    const trimmedUsername = username.trim();
    const ok = await onAddAccount({
      name: `${sei.trim()} ${mei.trim()}`,
      furigana: [seiKana.trim(), meiKana.trim()].filter(Boolean).join(' '),
      username: trimmedUsername,
      password: password.trim(),
      hireDate,
      role,
      adminPermissions: role === 'admin' ? adminPermissions : undefined,
      // ユーザー名がメールアドレス形式の場合は、連絡用メールアドレスにも自動で反映する
      contactEmail: trimmedUsername.includes('@') ? trimmedUsername : undefined,
      requireProfileSetup,
    });
    if (ok) {
      setSei('');
      setMei('');
      setSeiKana('');
      setMeiKana('');
      setUsername('');
      setPassword('');
      setHireDate(todayKey());
      setRole('employee');
      setAdminPermissions(['attendance', 'labor', 'hr', 'payroll']);
      setShowForm(false);
    }
  };

  const listCard = (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="px-5 py-3.5 border-b border-slate-100 flex items-center gap-2 flex-wrap">
        <Users size={15} className="text-slate-400" />
        <h2 className="font-bold text-[13.5px]">スタッフ一覧</h2>
        <span className="text-[11px] text-slate-400">{filteredEmployeeAccounts.length}名 / 全{employeeAccounts.length}名</span>
        {isMasterAdmin && (
          <button onClick={() => setCsvModalOpen(true)} className="ml-auto flex items-center gap-1 text-[12px] font-bold text-slate-500 border border-slate-200 rounded-lg px-2.5 py-1.5">
            <Download size={13} className="rotate-180" /> CSV一括登録
          </button>
        )}
        {isMasterAdmin && (
          <button
            onClick={runFullBackup}
            disabled={backingUp}
            className="flex items-center gap-1 text-[12px] font-bold text-slate-500 disabled:text-slate-300 border border-slate-200 rounded-lg px-2.5 py-1.5"
          >
            <Download size={13} /> {backingUp ? '作成中…' : 'データバックアップ'}
          </button>
        )}
      </div>

      <div className="px-5 py-3.5 border-b border-slate-100 grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-2.5">
        <Field label="氏名で検索">
          <input value={listNameQuery} onChange={(e) => setListNameQuery(e.target.value)} placeholder="1文字から絞り込み" className="w-full border border-slate-200 rounded-lg px-2.5 py-1.5 text-[12.5px]" />
        </Field>
        {knownGroups.length > 0 && (
          <Field label="所属グループ">
            <select value={listGroupFilter} onChange={(e) => setListGroupFilter(e.target.value)} className="w-full border border-slate-200 rounded-lg px-2.5 py-1.5 text-[12.5px] bg-white">
              <option value="all">全て</option>
              {knownGroups.map((g) => <option key={g} value={g}>{g}</option>)}
            </select>
          </Field>
        )}
        <Field label="スタッフ種別">
          <select value={listStaffTypeFilter} onChange={(e) => setListStaffTypeFilter(e.target.value)} className="w-full border border-slate-200 rounded-lg px-2.5 py-1.5 text-[12.5px] bg-white">
            <option value="all">全て</option>
            {STAFF_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </Field>
        <Field label="在籍・退職">
          <select value={listStatusFilter} onChange={(e) => setListStatusFilter(e.target.value)} className="w-full border border-slate-200 rounded-lg px-2.5 py-1.5 text-[12.5px] bg-white">
            <option value="active">在籍のみ</option>
            <option value="retired">退職のみ</option>
            <option value="all">全て</option>
          </select>
        </Field>
        <Field label="並び順">
          <select value={listSort} onChange={(e) => setListSort(e.target.value)} className="w-full border border-slate-200 rounded-lg px-2.5 py-1.5 text-[12.5px] bg-white">
            <option value="name">氏名順</option>
            <option value="hireDateDesc">入職日が新しい順</option>
            <option value="hireDateAsc">入職日が古い順</option>
          </select>
        </Field>
      </div>
      {isDesktop ? (
        <div className="overflow-x-auto">
        <table className="w-full min-w-[920px] text-[13px]">
          <thead>
            <tr className="text-left text-[11px] text-slate-400 border-b border-slate-100">
              <th className="px-5 py-2 font-medium">氏名</th>
              <th className="px-3 py-2 font-medium">グループ</th>
              <th className="px-3 py-2 font-medium">本日</th>
              <th className="px-3 py-2 font-medium">今月の勤務</th>
              <th className="px-3 py-2 font-medium">有休残</th>
              <th className="px-3 py-2 font-medium">未処理</th>
              {isMasterAdmin && <th className="px-2 py-2 font-medium"></th>}
              <th className="px-2 py-2 font-medium"></th>
              <th className="px-2 py-2 font-medium"></th>
              <th className="px-3 py-2 font-medium"></th>
            </tr>
          </thead>
          <tbody>
            {filteredEmployeeAccounts.map((acc) => {
              const retired = !!acc.resignationDate;
              const info = rowInfo[acc.id];
              const state = info && !retired ? STAFF_TODAY_STATE[info.todayState] : null;
              return (
                <tr key={acc.id} className="border-b border-slate-100 last:border-0">
                  <td className="px-5 py-2.5 font-semibold text-slate-800 cursor-pointer hover:text-amber-700" onClick={() => setProfileModalAccount(acc)}>
                    {acc.name}
                    {retired && <span className="ml-1.5 text-[10px] font-bold text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded">退職済み</span>}
                    {acc.furigana && <div className="text-[10.5px] font-normal text-slate-400">{acc.furigana}</div>}
                  </td>
                  <td className="px-3 py-2.5 text-slate-600 whitespace-nowrap">{acc.mainGroup || acc.staffType || '正社員'}</td>
                  <td className={`px-3 py-2.5 font-bold whitespace-nowrap ${state ? state.cls : 'text-slate-300'}`}>{state ? state.label : '—'}</td>
                  <td className="px-3 py-2.5 font-mono text-slate-600 whitespace-nowrap">{info ? minutesToHHMM(info.monthWorkedMin) : '—'}</td>
                  <td className={`px-3 py-2.5 font-mono whitespace-nowrap ${info?.leaveShort ? 'text-rose-600 font-bold' : 'text-slate-600'}`}>
                    {!info ? '—' : info.leavePending ? <span className="text-amber-700 font-bold">集計中</span> : `${fmtDays(info.leaveRemaining)}日`}
                  </td>
                  <td className="px-3 py-2.5">
                    {info && info.pendingKinds.length > 0 ? (
                      <span className="flex flex-wrap gap-1">
                        {info.pendingKinds.map((p) => (
                          <span key={p.kind} className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${APPROVAL_KIND_META[p.kind].cls}`}>
                            {APPROVAL_KIND_META[p.kind].label} {p.count}
                          </span>
                        ))}
                      </span>
                    ) : (
                      <span className="text-[11.5px] text-slate-300">なし</span>
                    )}
                  </td>
                  {isMasterAdmin && (
                    <td className="px-2 py-2.5"><button onClick={() => setLoginEmailTarget(acc)} className="text-slate-300 hover:text-amber-600" title="ログインIDを変更"><Mail size={14} /></button></td>
                  )}
                  <td className="px-2 py-2.5"><button onClick={() => setResetPasswordTarget(acc)} className="text-slate-300 hover:text-amber-600" title="パスワードリセット"><Key size={14} /></button></td>
                  <td className="px-2 py-2.5"><button onClick={() => setDeleteTarget(acc)} className="text-slate-300 hover:text-rose-500" title="削除"><Trash2 size={14} /></button></td>
                  <td className="px-3 py-2.5">
                    <StaffRowMenu
                      account={acc}
                      info={info}
                      onOpenProfile={setProfileModalAccount}
                      onOpenAttendance={rowActions.onOpenAttendance || (() => {})}
                      onOpenApprovals={rowActions.onOpenApprovals || (() => {})}
                      onOpenPayroll={rowActions.onOpenPayroll || (() => {})}
                    />
                  </td>
                </tr>
              );
            })}
            {filteredEmployeeAccounts.length === 0 && (
              <tr><td colSpan={isMasterAdmin ? 10 : 9} className="px-5 py-8 text-center text-[12.5px] text-slate-300">該当するスタッフがいません</td></tr>
            )}
          </tbody>
        </table>
        </div>
      ) : (
        <div className="divide-y divide-slate-100">
          {filteredEmployeeAccounts.map((acc) => {
            const retired = !!acc.resignationDate;
            const info = rowInfo[acc.id];
            const state = info && !retired ? STAFF_TODAY_STATE[info.todayState] : null;
            return (
              <div key={acc.id} className="px-5 py-3.5">
                <div className="flex items-center justify-between">
                  <div className="cursor-pointer" onClick={() => setProfileModalAccount(acc)}>
                    <div className="text-[13px] font-semibold text-slate-800 flex items-center gap-1.5">
                      {acc.name}
                      {retired && <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded">退職済み</span>}
                      {state && <span className={`text-[11px] font-bold ${state.cls}`}>{state.label}</span>}
                    </div>
                    {acc.furigana && <div className="text-[10.5px] text-slate-400">{acc.furigana}</div>}
                    <div className="text-[11.5px] text-slate-500 mt-0.5">
                      {acc.mainGroup || acc.staffType || '正社員'}
                      {info && <span className="ml-2 font-mono">今月 {minutesToHHMM(info.monthWorkedMin)}</span>}
                      {info && <span className={`ml-2 font-mono ${info.leaveShort ? 'text-rose-600 font-bold' : ''}`}>有休 {info.leavePending ? '集計中' : `${fmtDays(info.leaveRemaining)}日`}</span>}
                    </div>
                    {info && info.pendingKinds.length > 0 && (
                      <div className="mt-1 flex flex-wrap gap-1">
                        {info.pendingKinds.map((p) => (
                          <span key={p.kind} className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${APPROVAL_KIND_META[p.kind].cls}`}>
                            {APPROVAL_KIND_META[p.kind].label} {p.count}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-1">
                    {isMasterAdmin && (
                      <button onClick={() => setLoginEmailTarget(acc)} className="text-slate-300 hover:text-amber-600 p-1" title="ログインIDを変更"><Mail size={14} /></button>
                    )}
                    <button onClick={() => setResetPasswordTarget(acc)} className="text-slate-300 hover:text-amber-600 p-1" title="パスワードリセット"><Key size={14} /></button>
                    <button onClick={() => setDeleteTarget(acc)} className="text-slate-300 hover:text-rose-500 p-1" title="削除"><Trash2 size={14} /></button>
                    <StaffRowMenu
                      account={acc}
                      info={info}
                      onOpenProfile={setProfileModalAccount}
                      onOpenAttendance={rowActions.onOpenAttendance || (() => {})}
                      onOpenApprovals={rowActions.onOpenApprovals || (() => {})}
                      onOpenPayroll={rowActions.onOpenPayroll || (() => {})}
                    />
                  </div>
                </div>
              </div>
            );
          })}
          {filteredEmployeeAccounts.length === 0 && (
            <div className="px-5 py-8 text-center text-[12.5px] text-slate-300">該当するスタッフがいません</div>
          )}
        </div>
      )}
    </div>
  );

  // 登録フォームは開閉できるようにして、普段は一覧を広く使えるようにする
  const formToggle = isMasterAdmin && (
    <button
      type="button"
      onClick={() => setShowForm((v) => !v)}
      className={`flex w-full items-center gap-2 rounded-2xl border px-5 py-3 text-left shadow-sm transition-colors ${
        showForm ? 'border-slate-300 bg-slate-50' : 'border-slate-200 bg-white hover:bg-slate-50'
      }`}
    >
      <UserPlus size={15} className="text-amber-600" />
      <span className="text-[13.5px] font-bold text-slate-800">新しいアカウントを作成</span>
      <span className="ml-auto flex items-center gap-1.5 text-[11.5px] font-bold text-slate-500">
        {showForm ? '閉じる' : '開く'}
        <ChevronDown size={14} className={showForm ? 'rotate-180 transition-transform' : 'transition-transform'} />
      </span>
    </button>
  );

  const formCard = isMasterAdmin && showForm && (
    <form onSubmit={submit} className="bg-white rounded-2xl shadow-sm border border-slate-200 p-5 space-y-3.5 h-fit">
      <div className="grid grid-cols-2 gap-3">
        <Field label="姓">
          <input value={sei} onChange={(e) => setSei(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-[14px]" placeholder="例）田中" />
        </Field>
        <Field label="名">
          <input value={mei} onChange={(e) => setMei(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-[14px]" placeholder="例）花子" />
        </Field>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <Field label="せい（ふりがな）">
          <input value={seiKana} onChange={(e) => setSeiKana(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-[14px]" placeholder="例）たなか" />
        </Field>
        <Field label="めい（ふりがな）">
          <input value={meiKana} onChange={(e) => setMeiKana(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-[14px]" placeholder="例）はなこ" />
        </Field>
      </div>
      <Field label="メールアドレス（ログインID）">
        <input type="email" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 font-mono text-[14px]" placeholder="例）tanaka@example.com" />
        <div className="text-[10.5px] text-slate-400 mt-1">このアドレスがログインIDになり、ログイン案内のメールもここへ届きます。</div>
      </Field>
      <Field label={`仮パスワード（${PASSWORD_RULE_TEXT}）`}>
        <div className="flex gap-2">
          <input type="text" value={password} onChange={(e) => setPassword(e.target.value)} className="flex-1 border border-slate-200 rounded-lg px-3 py-2 font-mono text-[14px]" placeholder="仮パスワードを入力" />
          <button type="button" onClick={() => setPassword(generateTempPassword())} className="shrink-0 text-[12px] font-bold text-slate-500 border border-slate-200 rounded-lg px-3">自動生成</button>
        </div>
        <div className="text-[10.5px] text-slate-400 mt-1">初回ログイン時に、本人がパスワードを変更します。</div>
      </Field>
      {/* すでに在籍している方を登録するときなど、登録情報の入力を省きたい場合に外す。
          外しても、本人があとから「登録情報の閲覧・変更」で入力できる。 */}
      <label className="flex items-start gap-2 cursor-pointer select-none">
        <input
          type="checkbox"
          checked={requireProfileSetup}
          onChange={(e) => setRequireProfileSetup(e.target.checked)}
          className="mt-0.5 w-4 h-4 shrink-0 accent-amber-600"
        />
        <span className="text-[12.5px] text-slate-600 leading-relaxed">
          初回ログイン時に、登録情報（住所・口座など）の入力を求める
          <span className="block text-[10.5px] text-slate-400 mt-0.5">
            {requireProfileSetup
              ? 'パスワードの変更のあと、登録情報の入力画面が出ます。'
              : 'パスワードの変更だけで、すぐ通常の画面に入れます。登録情報は本人があとから入力できます。'}
          </span>
        </span>
      </label>
      <Field label="入職日">
        <input type="date" value={hireDate} onChange={(e) => setHireDate(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 font-mono text-[14px]" />
      </Field>
      {isMasterAdmin && (
        <>
          <Field label="役割">
            <select value={role} onChange={(e) => setRole(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-[14px] bg-white">
              <option value="employee">スタッフ</option>
              <option value="admin">管理者</option>
              <option value="master_admin">マスター管理者</option>
            </select>
          </Field>
          {role === 'admin' && (
            <Field label="利用できるタブ（権限）">
              <div className="grid grid-cols-2 gap-2">
                {ADMIN_TAB_OPTIONS.map((opt) => (
                  <label key={opt.key} className="flex items-center gap-2 text-[13px] text-slate-600 border border-slate-200 rounded-lg px-3 py-2">
                    <input type="checkbox" checked={adminPermissions.includes(opt.key)} onChange={() => toggleAdminPermission(opt.key)} />
                    {opt.label}
                  </label>
                ))}
              </div>
            </Field>
          )}
        </>
      )}
      <button type="submit" disabled={!canSubmit} className="w-full py-2.5 rounded-lg bg-slate-800 disabled:bg-slate-200 text-white text-[13.5px] font-bold">
        アカウントを作成
      </button>
    </form>
  );

  const disclaimer = (
    <div className="space-y-2">
      <div className="flex items-start gap-2 bg-blue-50 border border-blue-200 rounded-xl px-4 py-3 text-[11.5px] text-blue-800">
        <Calendar size={14} className="mt-0.5 shrink-0" />
        <span>法定有休は、入職日から週5日フルタイム勤務を前提とした労働基準法の付与スケジュール（勤続6ヶ月で10日〜6年6ヶ月以降20日）に基づき自動計算されます。短時間勤務者の比例付与や繰越・時効の管理には完全には対応していないため、正確な運用には社労士への確認をおすすめします。</span>
      </div>
      <div className="flex items-start gap-2 bg-emerald-50 border border-emerald-200 rounded-xl px-4 py-3 text-[11.5px] text-emerald-800">
        <Lock size={14} className="mt-0.5 shrink-0" />
        <span>パスワードはSupabase Authが管理しており、アプリ側では平文はもちろんハッシュ値も保持していません。</span>
      </div>
    </div>
  );

  const modals = (
    <>
      {csvModalOpen && isMasterAdmin && (
        <CsvImportModal
          onClose={() => setCsvModalOpen(false)}
          onAddAccount={onAddAccount}
        />
      )}
      {deleteTarget && (
        <DeleteAccountModal
          account={deleteTarget}
          onClose={() => setDeleteTarget(null)}
          onConfirm={async () => {
            const ok = await onDeleteAccount(deleteTarget);
            if (ok) setDeleteTarget(null);
          }}
        />
      )}
      {loginEmailTarget && (
        <ChangeLoginEmailModal
          account={loginEmailTarget}
          onClose={() => setLoginEmailTarget(null)}
          onConfirm={async (newEmail, options) => {
            const ok = await onChangeLoginEmail(loginEmailTarget, newEmail, options);
            if (ok) setLoginEmailTarget(null);
            return ok;
          }}
        />
      )}
      {resetPasswordTarget && (
        <ResetPasswordModal
          account={resetPasswordTarget}
          onClose={() => setResetPasswordTarget(null)}
          onConfirm={async (newPassword) => {
            const ok = await onResetPassword(resetPasswordTarget, newPassword);
            if (ok) setResetPasswordTarget(null);
          }}
        />
      )}
    </>
  );

  // 一覧の列が多いため、登録フォームは横に並べず、一覧の上に開閉式で置く
  return (
    <div className="space-y-4">
      {formToggle}
      {formCard}
      {listCard}
      {disclaimer}
      {modals}
    </div>
  );
}

